window.YC_MORE_QBANKS=window.YC_MORE_QBANKS||[];window.YC_MORE_QBANKS.push([{"id":"zz-32101","module":"zhengzhi","prompt":"毛泽东在《整顿党的作风》中反对的错误倾向是：","options":["贪污、浪费、官僚主义","官僚主义、命令主义、自由主义","主观主义、宗派主义、党八股","教条主义、经验主义、修正主义"],"answer":2,"explanation":"1942年毛泽东在《整顿党的作风》中提出反对主观主义、宗派主义、党八股，是延安整风的重要文献。","__sub":"毛思想"},{"id":"zz-32102","module":"zhengzhi","prompt":"毛泽东在《反对党八股》中列举的党八股罪状数量是：","options":["六条","八条","十条","十二条"],"answer":1,"explanation":"1942年毛泽东在《反对党八股》中列举党八股的八条罪状，倡导生动活泼、新鲜有力的马克思列宁主义文风。","__sub":"毛思想"},{"id":"zz-32103","module":"zhengzhi","prompt":"毛泽东在《论人民民主专政》中阐述的国家政权性质是：","options":["资产阶级领导的民主共和国","工人阶级领导的、以工农联盟为基础的人民民主专政","农民阶级领导的工农共和国","各革命阶级联合执政的联邦制国家"],"answer":1,"explanation":"1949年毛泽东在《论人民民主专政》中系统阐述人民民主专政理论，指出其是工人阶级领导的、以工农联盟为基础的国家政权。","__sub":"毛思想"},{"id":"zz-32104","module":"zhengzhi","prompt":"毛泽东在《论人民民主专政》中强调的对人民实行的方法是：","options":["民主","专政","改造","教育"],"answer":0,"explanation":"《论人民民主专政》指出，对人民内部实行民主，对反动派实行专政，二者结合起来就是人民民主专政。","__sub":"毛思想"},{"id":"zz-32105","module":"zhengzhi","prompt":"毛泽东在《论人民民主专政》中强调的对反动派实行的方法是：","options":["专政","民主","教育","改造"],"answer":0,"explanation":"《论人民民主专政》指出，对人民内部实行民主，对反动派实行专政，二者结合起来就是人民民主专政。","__sub":"毛思想"},{"id":"zz-32106","module":"zhengzhi","prompt":"毛泽东在《在中国共产党第七届中央委员会第二次全体会议上的报告》中提出的“两个务必”是：","options":["务必坚持独立自主，务必坚持自力更生","务必保持党的团结统一，务必保持党的纯洁性","务必坚持理论联系实际，务必坚持群众路线","务必使同志们继续地保持谦虚、谨慎、不骄、不躁的作风，务必使同志们继续地保持艰苦奋斗的作风"],"answer":3,"explanation":"1949年毛泽东在七届二中全会上提出“两个务必”，告诫全党警惕资产阶级“糖衣炮弹”的进攻。","__sub":"毛思想"},{"id":"zz-32107","module":"zhengzhi","prompt":"毛泽东在七届二中全会上提出的党的工作重心是：","options":["由城市转移到乡村","由乡村转移到城市","由军事转移到经济","由政治转移到文化"],"answer":1,"explanation":"1949年毛泽东在七届二中全会上提出党的工作重心由乡村转移到城市，城市工作必须以生产建设为中心。","__sub":"毛思想"},{"id":"zz-32108","module":"zhengzhi","prompt":"毛泽东在七届二中全会上提出的城市工作中心是：","options":["生产建设","政权建设","文化建设","军事建设"],"answer":0,"explanation":"七届二中全会指出，党的工作重心由乡村转移到城市后，城市工作必须以生产建设为中心。","__sub":"毛思想"},{"id":"zz-32109","module":"zhengzhi","prompt":"毛泽东在《中国社会各阶级的分析》中提出的革命首要问题是：","options":["确定路线","分清敌友","建立武装","发展经济"],"answer":1,"explanation":"1925年毛泽东在《中国社会各阶级的分析》开篇指出：“谁是我们的敌人？谁是我们的朋友？这个问题是革命的首要问题。”","__sub":"毛思想"},{"id":"zz-32110","module":"zhengzhi","prompt":"毛泽东在《湖南农民运动考察报告》中肯定的中心内容是：","options":["学生运动的先进性","工人运动的组织性","农民运动的革命作用","商人运动的积极性"],"answer":2,"explanation":"1927年毛泽东在《湖南农民运动考察报告》中充分肯定农民运动的革命作用，指出贫农是革命先锋。","__sub":"毛思想"},{"id":"zz-32111","module":"zhengzhi","prompt":"毛泽东在《湖南农民运动考察报告》中称为“革命先锋”的阶层是：","options":["贫农","富农","中农","地主"],"answer":0,"explanation":"《湖南农民运动考察报告》指出，贫农是乡村中一贯冲锋陷阵的“革命先锋”，是农民协会的中坚。","__sub":"毛思想"},{"id":"zz-32112","module":"zhengzhi","prompt":"毛泽东在《新民主主义论》中阐述的新民主主义文化是：","options":["大众的、民主的、自由的文化","革命的、进步的、开放的文化","传统的、民族的、科学的文化","民族的、科学的、大众的文化"],"answer":3,"explanation":"《新民主主义论》提出新民主主义文化纲领：民族的、科学的、大众的文化，即人民大众反帝反封建的文化。","__sub":"毛思想"},{"id":"zz-32113","module":"zhengzhi","prompt":"毛泽东在《新民主主义论》中阐述的新民主主义国体是：","options":["工农民主专政","资产阶级专政","无产阶级专政","各革命阶级联合专政"],"answer":3,"explanation":"《新民主主义论》指出，新民主主义共和国的国体是无产阶级领导的、以工农联盟为基础的各革命阶级联合专政，政体是民主集中制。","__sub":"毛思想"},{"id":"zz-32114","module":"zhengzhi","prompt":"毛泽东在《新民主主义论》中阐述的新民主主义政体是：","options":["民主集中制","议会制","总统制","君主立宪制"],"answer":0,"explanation":"《新民主主义论》指出，新民主主义共和国的政体是民主集中制的人民代表大会制度。","__sub":"毛思想"},{"id":"zz-32115","module":"zhengzhi","prompt":"毛泽东在《新民主主义论》中提出的新民主主义经济纲领是：","options":["没收一切土地归国家所有，消灭一切资本主义","没收封建地主阶级的土地归农民所有，没收官僚资本归新民主主义国家所有，保护民族工商业","平均地权，节制资本","耕者有其田，节制资本"],"answer":1,"explanation":"新民主主义经济纲领包括没收封建地主阶级的土地归农民所有、没收官僚资本归新民主主义国家所有、保护民族工商业三大纲领。","__sub":"毛思想"},{"id":"zz-32116","module":"zhengzhi","prompt":"新民主主义经济纲领中，没收土地归农民所有针对的是：","options":["民族资产阶级","官僚资产阶级","封建地主阶级","小资产阶级"],"answer":2,"explanation":"没收封建地主阶级的土地归农民所有，是新民主主义革命的主要内容，针对的是封建地主阶级的土地所有制。","__sub":"毛思想"},{"id":"zz-32117","module":"zhengzhi","prompt":"新民主主义经济纲领中，保护民族工商业针对的是：","options":["帝国主义在华企业","官僚资产阶级","封建地主阶级","民族资产阶级"],"answer":3,"explanation":"保护民族工商业是新民主主义经济纲领的重要内容，针对的是民族资产阶级的合法权益。","__sub":"毛思想"},{"id":"zz-32118","module":"zhengzhi","prompt":"毛泽东在《中国革命和中国共产党》中分析的中国社会性质是：","options":["半殖民地半封建社会","资本主义社会","封建社会","殖民地社会"],"answer":0,"explanation":"1939年毛泽东在《中国革命和中国共产党》中系统分析近代中国半殖民地半封建的社会性质，为制定革命路线提供依据。","__sub":"毛思想"},{"id":"zz-32119","module":"zhengzhi","prompt":"毛泽东在《中国革命和中国共产党》中提出的中国革命特点是：","options":["武装的革命反对武装的反革命","和平的革命反对武装的反革命","合法斗争反对非法斗争","经济斗争反对政治斗争"],"answer":0,"explanation":"《中国革命和中国共产党》指出，中国革命的特点是武装的革命反对武装的反革命，武装斗争是中国革命的主要形式。","__sub":"毛思想"},{"id":"zz-32120","module":"zhengzhi","prompt":"毛泽东在《〈共产党人〉发刊词》中总结的中国革命规律是：","options":["群众路线、独立自主、实事求是","土地革命、武装斗争、根据地建设","统一战线、武装斗争、党的建设","理论联系实际、密切联系群众、批评与自我批评"],"answer":2,"explanation":"《〈共产党人〉发刊词》总结中国革命规律，提出统一战线、武装斗争、党的建设是三大法宝。","__sub":"毛思想"},{"id":"zz-32121","module":"zhengzhi","prompt":"毛泽东在《〈共产党人〉发刊词》中提出党的建设的目标是：","options":["建设一个全国范围的、广大群众性的、思想上政治上组织上完全巩固的马克思主义政党","建设一个以工人阶级为主体的政党","建设一个以农民阶级为主体的政党","建设一个以知识分子为主体的政党"],"answer":0,"explanation":"《〈共产党人〉发刊词》提出党的建设的目标是建设一个全国范围的、广大群众性的、思想上政治上组织上完全巩固的马克思主义政党，即“伟大的工程”。","__sub":"毛思想"},{"id":"zz-32122","module":"zhengzhi","prompt":"毛泽东在《论持久战》中分析的中日战争四个特点不包括：","options":["敌强我弱","敌强我弱、敌退步我进步、敌小我大、敌寡助我多助中的敌退步我进步","敌小我大","敌寡助我多助"],"answer":1,"explanation":"《论持久战》分析的中日战争四个特点是敌强我弱、敌退步我进步、敌小我大、敌寡助我多助，敌退步我进步是其中之一而非不包括项。","__sub":"毛思想"},{"id":"zz-32123","module":"zhengzhi","prompt":"毛泽东在《论持久战》中批驳“速胜论”的依据是：","options":["敌弱我强的基本事实","敌强我弱的基本事实","敌我力量完全相当","国际形势的突然变化"],"answer":1,"explanation":"《论持久战》批驳“速胜论”，指出敌强我弱的基本事实决定了抗日战争是持久战，不能速胜。","__sub":"毛思想"},{"id":"zz-32124","module":"zhengzhi","prompt":"毛泽东在《论持久战》中批驳“亡国论”的依据是：","options":["敌大我小","敌强我弱","敌退步我进步、敌小我大、敌寡助我多助","敌多助我寡助"],"answer":2,"explanation":"《论持久战》批驳“亡国论”，指出敌退步我进步、敌小我大、敌寡助我多助决定了中国不会亡，最后胜利属于中国。","__sub":"毛思想"},{"id":"zz-32125","module":"zhengzhi","prompt":"毛泽东在《论持久战》中强调的政治动员是：","options":["仅向群众进行经济动员","仅向军队进行军事训练","把战争的政治目的告诉军队和人民","仅向干部进行理论教育"],"answer":2,"explanation":"《论持久战》强调政治动员是把战争的政治目的告诉军队和人民，使每个士兵每个人民都明白为什么要打仗。","__sub":"毛思想"},{"id":"zz-32126","module":"zhengzhi","prompt":"毛泽东在《论联合政府》中提出的党的政治路线是：","options":["建立无产阶级专政的社会主义国家","推翻帝国主义、封建主义和官僚资本主义的统治","放手发动群众，壮大人民力量，在我党的领导下，打败日本侵略者，解放全国人民，建立一个新民主主义的中国","实现工业、农业、国防和科学技术的现代化"],"answer":2,"explanation":"1945年毛泽东在《论联合政府》中提出党的政治路线：放手发动群众，壮大人民力量，在我党的领导下，打败日本侵略者，解放全国人民，建立一个新民主主义的中国。","__sub":"毛思想"},{"id":"zz-32127","module":"zhengzhi","prompt":"毛泽东在《论联合政府》中提出的最高纲领与最低纲领的关系是：","options":["最高纲领为最低纲领规定方向，最低纲领为最高纲领的实现准备条件","最高纲领可以替代最低纲领","最低纲领可以替代最高纲领","二者相互对立"],"answer":0,"explanation":"《论联合政府》指出，党的最高纲领为最低纲领规定方向，最低纲领为最高纲领的实现准备条件，二者辩证统一。","__sub":"毛思想"},{"id":"zz-32128","module":"zhengzhi","prompt":"毛泽东在《论联合政府》中提出的人民战争路线是：","options":["人民战争的路线","正规战争的路线","游击战争的路线","阵地战的路线"],"answer":0,"explanation":"《论联合政府》指出，人民战争的路线是中国共产党领导抗日战争的正确路线，是人民军队建设的根本方向。","__sub":"毛思想"},{"id":"zz-32129","module":"zhengzhi","prompt":"党在过渡时期的总路线正式提出的时间是：","options":["1951年","1953年","1955年","1957年"],"answer":1,"explanation":"1953年，党正式提出过渡时期的总路线，即“一化三改”的总路线，成为过渡时期各项工作的灯塔。","__sub":"毛思想"},{"id":"zz-32130","module":"zhengzhi","prompt":"党在过渡时期总路线的内容可概括为：","options":["“四个现代化”","“两步走”","“一体两翼”","“一化三改”"],"answer":3,"explanation":"党在过渡时期的总路线是要在一个相当长的时期内，逐步实现国家的社会主义工业化，并逐步实现国家对农业、手工业和资本主义工商业的社会主义改造，简称“一化三改”。","__sub":"毛思想"},{"id":"zz-32131","module":"zhengzhi","prompt":"过渡时期总路线中，“一化”指的是：","options":["农业合作化","社会主义工业化","资本主义工商业公有化","科学技术现代化"],"answer":1,"explanation":"过渡时期总路线的主体是逐步实现国家的社会主义工业化，即“一化”，这是国家独立和富强的必然要求。","__sub":"毛思想"},{"id":"zz-32132","module":"zhengzhi","prompt":"过渡时期总路线中，“三改”改造的对象不包括：","options":["个体手工业","个体农业","封建土地制度","资本主义工商业"],"answer":2,"explanation":"“三改”指对个体农业、个体手工业和资本主义工商业的社会主义改造；封建土地制度在1952年土地改革完成后已被废除。","__sub":"毛思想"},{"id":"zz-32133","module":"zhengzhi","prompt":"过渡时期总路线的鲜明特点是：","options":["工业化和改造相互对立","先实现工业化再进行改造","先完成改造再发展工业","社会主义工业化与社会主义改造同时并举"],"answer":3,"explanation":"过渡时期总路线的鲜明特点是社会主义建设与社会主义改造同时并举，“一化”是主体，“三改”是两翼，二者相互促进、相辅相成。","__sub":"毛思想"},{"id":"zz-32134","module":"zhengzhi","prompt":"新民主主义社会的性质是：","options":["属于社会主义体系的过渡性社会","独立的资本主义社会","完全的社会主义社会","新民主主义与社会主义并列的社会"],"answer":0,"explanation":"新民主主义社会不是独立的社会形态，而是属于社会主义体系的、由新民主主义走向社会主义的过渡性质的社会。","__sub":"毛思想"},{"id":"zz-32135","module":"zhengzhi","prompt":"新民主主义社会的主要经济成分是：","options":["计划经济、市场经济和混合经济","社会主义经济、集体经济和外资经济","国营经济、私营经济和外资经济","社会主义经济、个体经济和资本主义经济"],"answer":3,"explanation":"新民主主义社会存在五种经济成分，主要的经济成分是社会主义经济、个体经济和资本主义经济三种。","__sub":"毛思想"},{"id":"zz-32136","module":"zhengzhi","prompt":"新民主主义社会中居于领导地位的经济成分是：","options":["私人资本主义经济","个体经济","国营经济","合作社经济"],"answer":2,"explanation":"新民主主义社会的五种经济成分中，国营经济是社会主义性质的，居于领导地位，是整个国民经济的领导力量。","__sub":"毛思想"},{"id":"zz-32137","module":"zhengzhi","prompt":"土地改革完成后，我国国内的主要矛盾是：","options":["农民阶级和地主阶级的矛盾","人民日益增长的物质文化需要同落后的社会生产之间的矛盾","工人阶级和资产阶级的矛盾、社会主义道路和资本主义道路的矛盾","先进的生产关系同落后的生产力之间的矛盾"],"answer":2,"explanation":"随着土地改革的完成，工人阶级和资产阶级的矛盾、社会主义道路和资本主义道路的矛盾上升为国内主要矛盾，这为进行社会主义改造提供了依据。","__sub":"毛思想"},{"id":"zz-32138","module":"zhengzhi","prompt":"我国农业社会主义改造经历的三个步骤是：","options":["供销小组、供销合作社、生产合作社","互助组、初级社、高级社","互助组、合作社、人民公社","初级社、中级社、人民公社"],"answer":1,"explanation":"农业社会主义改造遵循自愿互利原则，采取从互助组到初级社再到高级社逐步过渡的形式，引导农民走上合作化道路。","__sub":"毛思想"},{"id":"zz-32139","module":"zhengzhi","prompt":"农业合作化运动中，互助组的性质是：","options":["社会主义萌芽性质","半社会主义性质","完全社会主义性质","资本主义性质"],"answer":0,"explanation":"农业互助组以土地私有、共同劳动为特点，带有社会主义萌芽性质，是农业合作化的最初过渡形式。","__sub":"毛思想"},{"id":"zz-32140","module":"zhengzhi","prompt":"农业合作化运动中，初级社的性质是：","options":["半社会主义性质","社会主义萌芽性质","完全社会主义性质","国家资本主义性质"],"answer":0,"explanation":"初级社实行土地入股、统一经营，收益按土地和劳动比例分配，具有半社会主义性质，是农业合作化的过渡形式。","__sub":"毛思想"},{"id":"zz-32141","module":"zhengzhi","prompt":"农业合作化运动中，高级社的性质是：","options":["完全社会主义性质","半社会主义性质","社会主义萌芽性质","个体经济性质"],"answer":0,"explanation":"高级社实行土地等主要生产资料集体所有、按劳分配，是完全社会主义性质的集体经济组织。","__sub":"毛思想"},{"id":"zz-32142","module":"zhengzhi","prompt":"农业合作化运动遵循的方针是：","options":["先急后缓、全面铺开","积极领导、稳步前进","自愿退社、自由发展","国家包办、统一经营"],"answer":1,"explanation":"党在农业合作化运动中坚持积极领导、稳步前进的方针，采取典型示范、逐步推广的办法，引导农民自愿走上合作化道路。","__sub":"毛思想"},{"id":"zz-32143","module":"zhengzhi","prompt":"农业社会主义改造坚持的基本原则是：","options":["先富带后富、逐步推广","统一经营、集中劳动、按需分配","行政命令、限期完成","自愿互利、典型示范、国家帮助"],"answer":3,"explanation":"农业社会主义改造坚持自愿互利、典型示范、国家帮助的原则，尊重农民意愿，不剥夺农民的财产。","__sub":"毛思想"},{"id":"zz-32144","module":"zhengzhi","prompt":"我国手工业社会主义改造采取的步骤是：","options":["手工业供销小组、手工业供销合作社、手工业生产合作社","互助组、初级社、高级社","委托加工、计划订货、公私合营","统购包销、经销代销、定息"],"answer":0,"explanation":"手工业改造从手工业供销小组入手，发展到手工业供销合作社，再进一步建立手工业生产合作社，逐步实现集体化。","__sub":"毛思想"},{"id":"zz-32145","module":"zhengzhi","prompt":"我国对资本主义工商业改造采取的基本方式是：","options":["强制征收","无偿没收","和平赎买","公私合营一步到位"],"answer":2,"explanation":"我国对资本主义工商业实行和平赎买，通过国家资本主义的过渡形式，有代价地把资本家私有制逐步改造为社会主义公有制。","__sub":"毛思想"},{"id":"zz-32146","module":"zhengzhi","prompt":"国家资本主义初级阶段的经营形式包括委托加工、计划订货、统购包销和：","options":["经销代销","公私合营","四马分肥","定息"],"answer":0,"explanation":"国家资本主义的初级形式有委托加工、计划订货、统购包销、经销代销，使私营企业在原料供应和产品销售上同国营经济发生联系。","__sub":"毛思想"},{"id":"zz-32147","module":"zhengzhi","prompt":"国家资本主义的高级形式是：","options":["统购包销","委托加工","公私合营","经销代销"],"answer":2,"explanation":"公私合营是国家资本主义的高级形式，经历了个别企业公私合营和全行业公私合营两个发展阶段。","__sub":"毛思想"},{"id":"zz-32148","module":"zhengzhi","prompt":"个别企业公私合营阶段，企业利润的分配办法是：","options":["资方独占","全部上缴国家","定息","“四马分肥”"],"answer":3,"explanation":"个别企业公私合营阶段实行“四马分肥”，企业利润分为国家所得税、企业公积金、工人福利费、资方红利四个部分，资方所得约四分之一。","__sub":"毛思想"},{"id":"zz-32149","module":"zhengzhi","prompt":"“四马分肥”中，资本家所得的部分是：","options":["工人福利费","国家所得税","企业公积金","资方红利"],"answer":3,"explanation":"“四马分肥”把企业利润分为国家所得税、企业公积金、工人福利费和资方红利四份，资方红利约占四分之一，体现了赎买政策。","__sub":"毛思想"},{"id":"zz-32150","module":"zhengzhi","prompt":"全行业公私合营后，国家对资本家实行的利润分配办法是：","options":["没收资产","“四马分肥”","定息","一次性买断"],"answer":2,"explanation":"全行业公私合营后，国家对资本家的资产按固定利率发放定息，资本家失去企业管理权，企业生产纳入国家计划。","__sub":"毛思想"},{"id":"zz-32151","module":"zhengzhi","prompt":"我国三大改造基本完成的时间是：","options":["1956年底","1952年底","1957年底","1966年底"],"answer":0,"explanation":"1956年底，我国基本完成对农业、手工业和资本主义工商业的社会主义改造，标志着社会主义制度在我国基本确立。","__sub":"毛思想"},{"id":"zz-32152","module":"zhengzhi","prompt":"三大改造基本完成的最重要意义是：","options":["人民生活水平大幅提高","我国实现了工业化","国民经济恢复任务完成","社会主义基本制度在我国初步确立"],"answer":3,"explanation":"三大改造的基本完成，实现了生产资料所有制的深刻变革，社会主义基本制度在我国初步确立，我国进入社会主义初级阶段。","__sub":"毛思想"},{"id":"zz-32153","module":"zhengzhi","prompt":"社会主义改造的一条基本经验是：","options":["先改造后建设、两步分开","社会主义工业化与社会主义改造同时并举","以阶级斗争为中心推动改造","照搬苏联集体农庄模式"],"answer":1,"explanation":"我国在推进社会主义改造的同时开展大规模工业化建设，二者相互促进，避免了社会动荡，这是社会主义改造的重要经验。","__sub":"毛思想"},{"id":"zz-32154","module":"zhengzhi","prompt":"对资本主义工商业者，党实行的政策是：","options":["交由群众批斗处理","一律清除出企业","保留其剥削权利","团结、教育、改造，使其成为自食其力的劳动者"],"answer":3,"explanation":"党对资本主义工商业者坚持团结、教育、改造的政策，把企业改造和人的改造结合起来，使他们逐步成为自食其力的社会主义劳动者。","__sub":"毛思想"},{"id":"zz-32155","module":"zhengzhi","prompt":"中共八大召开的时间是：","options":["1957年9月","1954年9月","1956年9月","1958年5月"],"answer":2,"explanation":"1956年9月，中国共产党第八次全国代表大会在北京召开，这是新中国成立后党召开的第一次全国代表大会。","__sub":"毛思想"},{"id":"zz-32156","module":"zhengzhi","prompt":"中共八大关于国内主要矛盾的表述是：","options":["计划经济和市场经济的矛盾","无产阶级和资产阶级之间的矛盾","人民内部各阶层之间的矛盾","人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾"],"answer":3,"explanation":"中共八大指出，国内主要矛盾已经是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾，以及人民对于经济文化迅速发展的需要同当前经济文化不能满足人民需要的状况之间的矛盾。","__sub":"毛思想"},{"id":"zz-32157","module":"zhengzhi","prompt":"中共八大确定的党和人民的主要任务是：","options":["集中力量发展社会生产力","开展阶级斗争","进行社会主义改造","建立人民公社"],"answer":0,"explanation":"中共八大提出，党和全国人民当前的主要任务是集中力量发展社会生产力，把我国尽快地从落后的农业国变为先进的工业国。","__sub":"毛思想"},{"id":"zz-32158","module":"zhengzhi","prompt":"毛泽东《论十大关系》发表的时间是：","options":["1958年4月","1955年4月","1957年2月","1956年4月"],"answer":3,"explanation":"1956年4月，毛泽东在中央政治局扩大会议上发表《论十大关系》，初步总结了我国社会主义建设的经验。","__sub":"毛思想"},{"id":"zz-32159","module":"zhengzhi","prompt":"《论十大关系》确定的基本方针是：","options":["调动一切积极因素，为社会主义事业服务","以阶级斗争为纲","优先发展重工业","赶英超美、大干快上"],"answer":0,"explanation":"《论十大关系》确定的基本方针是努力把党内党外、国内国外的一切积极因素调动起来，为社会主义事业服务。","__sub":"毛思想"},{"id":"zz-32160","module":"zhengzhi","prompt":"《论十大关系》前三条关系围绕的中心是：","options":["正确处理重工业和轻工业、农业的关系","沿海和内地工业的关系","经济建设和国防建设的关系","中央和地方的关系"],"answer":0,"explanation":"《论十大关系》前三条着重论述重工业和轻工业、农业的关系，强调以苏为鉴，统筹兼顾，走出适合我国情况的工业化道路。","__sub":"毛思想"},{"id":"zz-32161","module":"zhengzhi","prompt":"《论十大关系》提出的中国共产党同各民主党派关系的方针是：","options":["轮流执政、相互制衡","长期共存、互相监督","彻底消灭、逐步取缔","各自为政、互不干涉"],"answer":1,"explanation":"《论十大关系》提出共产党和民主党派“长期共存、互相监督”的方针，确立了中国共产党领导的多党合作制度。","__sub":"毛思想"},{"id":"zz-32162","module":"zhengzhi","prompt":"毛泽东《关于正确处理人民内部矛盾的问题》发表的时间是：","options":["1958年5月","1956年4月","1957年9月","1957年2月"],"answer":3,"explanation":"1957年2月，毛泽东发表《关于正确处理人民内部矛盾的问题》，系统阐述了社会主义社会矛盾学说。","__sub":"毛思想"},{"id":"zz-32163","module":"zhengzhi","prompt":"社会主义社会存在的两类不同性质的社会矛盾是：","options":["阶级矛盾和民族矛盾","敌我矛盾和人民内部矛盾","经济矛盾和政治矛盾","国内矛盾和国际矛盾"],"answer":1,"explanation":"毛泽东指出，社会主义社会存在敌我矛盾和人民内部矛盾两类性质完全不同的矛盾，必须严格区分和正确处理。","__sub":"毛思想"},{"id":"zz-32164","module":"zhengzhi","prompt":"人民内部矛盾应当采用的解决方法是：","options":["行政命令的方法","专政的方法","斗争的方法","民主的方法，即讨论、批评、说服教育的方法"],"answer":3,"explanation":"人民内部矛盾是非对抗性的，只能用民主的方法解决，即讨论的方法、批评的方法、说服教育的方法，而不能用强制的办法。","__sub":"毛思想"},{"id":"zz-32165","module":"zhengzhi","prompt":"敌我矛盾应当采用的解决方法是：","options":["民主的方法","专政的方法","说服教育的方法","批评与自我批评的方法"],"answer":1,"explanation":"敌我矛盾是对抗性的矛盾，必须用专政的方法解决，这是人民民主专政国家政权的职能所在。","__sub":"毛思想"},{"id":"zz-32166","module":"zhengzhi","prompt":"社会主义社会的基本矛盾仍然是：","options":["计划与市场之间的矛盾","人民日益增长的物质文化需要同落后的社会生产之间的矛盾","无产阶级和资产阶级之间的矛盾","生产关系和生产力之间、上层建筑和经济基础之间的矛盾"],"answer":3,"explanation":"毛泽东指出，社会主义社会的基本矛盾仍然是生产关系和生产力之间、上层建筑和经济基础之间的矛盾，但它是非对抗性的，可以通过社会主义制度本身不断地得到解决。","__sub":"毛思想"},{"id":"zz-32167","module":"zhengzhi","prompt":"社会主义社会基本矛盾的性质是：","options":["不可调和的矛盾","对抗性的矛盾","你死我活的矛盾","非对抗性的矛盾"],"answer":3,"explanation":"社会主义社会的基本矛盾是非对抗性的，是在人民根本利益一致基础上的矛盾，可以通过社会主义制度的自我完善和发展得到解决。","__sub":"毛思想"},{"id":"zz-32168","module":"zhengzhi","prompt":"毛泽东提出，国家政治生活的主题是：","options":["正确处理人民内部矛盾","正确处理敌我矛盾","发展国民经济","巩固无产阶级专政"],"answer":0,"explanation":"毛泽东在《关于正确处理人民内部矛盾的问题》中提出，把正确处理人民内部矛盾作为国家政治生活的主题，团结全国人民发展社会主义建设事业。","__sub":"毛思想"},{"id":"zz-32169","module":"zhengzhi","prompt":"解决人民内部矛盾坚持的公式是：","options":["批评—斗争—处理","专政—改造—团结","团结—批评—团结","团结—专政—改造"],"answer":2,"explanation":"解决人民内部矛盾采取“团结—批评—团结”的公式，即从团结的愿望出发，经过批评或者斗争，在新的基础上达到新的团结。","__sub":"毛思想"},{"id":"zz-32170","module":"zhengzhi","prompt":"周恩来在1964年底召开的三届全国人大一次会议上正式提出的战略目标是：","options":["实现四个现代化","实现工业化","实现小康","建成中等发达国家"],"answer":0,"explanation":"1964年底至1965年初召开的三届全国人大一次会议上，周恩来根据毛泽东的提议，在政府工作报告中正式提出实现现代农业、现代工业、现代国防和现代科学技术的四个现代化目标。","__sub":"毛思想"},{"id":"zz-32171","module":"zhengzhi","prompt":"我国提出的“四个现代化”是指现代农业、现代工业、现代国防和：","options":["现代金融业","现代交通运输业","现代教育事业","现代科学技术"],"answer":3,"explanation":"四个现代化的内容是现代农业、现代工业、现代国防和现代科学技术，其中科学技术现代化是关键。","__sub":"毛思想"},{"id":"zz-32172","module":"zhengzhi","prompt":"我国现代化建设“两步走”设想的第一步是：","options":["全面建成小康社会","全面实现四个现代化","实现人均国民生产总值翻两番","建立独立的比较完整的工业体系和国民经济体系"],"answer":3,"explanation":"“两步走”设想的第一步是建立独立的比较完整的工业体系和国民经济体系，第二步是全面实现农业、工业、国防和科学技术的现代化。","__sub":"毛思想"},{"id":"zz-32173","module":"zhengzhi","prompt":"我国第一个五年计划的实施时间是：","options":["1958年至1962年","1949年至1953年","1956年至1960年","1953年至1957年"],"answer":3,"explanation":"第一个五年计划从1953年开始实施，到1957年超额完成，其特点是优先发展重工业，为社会主义工业化奠定了初步基础。","__sub":"毛思想"},{"id":"zz-32174","module":"zhengzhi","prompt":"农业合作化运动中，党依靠的基本阶级力量是：","options":["地主阶级","富农","贫农和下中农","民族资产阶级"],"answer":2,"explanation":"农业合作化运动中，党坚持依靠贫农、下中农，团结中农，限制到逐步消灭富农剥削的阶级政策，保证了合作化运动的顺利进行。","__sub":"毛思想"},{"id":"zz-32175","module":"zhengzhi","prompt":"毛泽东《中国社会各阶级的分析》发表的时间是：","options":["1923年6月","1925年12月","1927年3月","1930年1月"],"answer":1,"explanation":"1925年12月，毛泽东发表《中国社会各阶级的分析》，指出分清敌友是革命的首要问题，是毛泽东思想萌芽的标志之一。","__sub":"毛思想"},{"id":"zz-32176","module":"zhengzhi","prompt":"毛泽东《湖南农民运动考察报告》发表的时间是：","options":["1928年11月","1925年12月","1926年9月","1927年3月"],"answer":3,"explanation":"1927年3月，毛泽东发表《湖南农民运动考察报告》，热情肯定和赞扬农民运动，是党领导农民革命斗争的重要文献。","__sub":"毛思想"},{"id":"zz-32177","module":"zhengzhi","prompt":"毛泽东《中国的红色政权为什么能够存在？》写作的时间是：","options":["1928年11月","1927年8月","1928年10月","1930年1月"],"answer":2,"explanation":"1928年10月，毛泽东撰写《中国的红色政权为什么能够存在？》，分析了红色政权能够存在和发展的原因与条件。","__sub":"毛思想"},{"id":"zz-32178","module":"zhengzhi","prompt":"毛泽东《井冈山的斗争》写作的时间是：","options":["1929年12月","1928年10月","1928年11月","1930年5月"],"answer":2,"explanation":"1928年11月，毛泽东撰写《井冈山的斗争》，总结了井冈山革命根据地斗争的经验，论述了工农武装割据思想。","__sub":"毛思想"},{"id":"zz-32179","module":"zhengzhi","prompt":"毛泽东《星星之火，可以燎原》写作的时间是：","options":["1930年1月","1929年12月","1930年5月","1935年12月"],"answer":0,"explanation":"1930年1月，毛泽东撰写《星星之火，可以燎原》，回答了“红旗到底打得多久”的疑问，初步形成了农村包围城市的理论。","__sub":"毛思想"},{"id":"zz-32180","module":"zhengzhi","prompt":"毛泽东《反对本本主义》写作的时间是：","options":["1930年1月","1929年12月","1930年5月","1937年7月"],"answer":2,"explanation":"1930年5月，毛泽东撰写《反对本本主义》，提出“没有调查，没有发言权”，是党内第一篇反对教条主义的文献。","__sub":"毛思想"},{"id":"zz-32181","module":"zhengzhi","prompt":"毛泽东《论反对日本帝国主义的策略》写作的时间是：","options":["1936年12月","1935年1月","1935年12月","1937年8月"],"answer":2,"explanation":"1935年12月，毛泽东在瓦窑堡会议后作《论反对日本帝国主义的策略》的报告，系统阐述了建立抗日民族统一战线的策略。","__sub":"毛思想"},{"id":"zz-32182","module":"zhengzhi","prompt":"毛泽东《中国革命战争的战略问题》写作的时间是：","options":["1938年5月","1935年12月","1937年7月","1936年12月"],"answer":3,"explanation":"1936年12月，毛泽东撰写《中国革命战争的战略问题》，总结土地革命战争的经验，系统论述了中国革命战争的战略问题。","__sub":"毛思想"},{"id":"zz-32183","module":"zhengzhi","prompt":"毛泽东《实践论》写作的时间是：","options":["1937年8月","1936年12月","1937年7月","1938年5月"],"answer":2,"explanation":"1937年7月，毛泽东撰写《实践论》，以马克思主义认识论观点揭露教条主义，副标题是论认识和实践的关系。","__sub":"毛思想"},{"id":"zz-32184","module":"zhengzhi","prompt":"毛泽东《矛盾论》写作的时间是：","options":["1937年7月","1937年8月","1938年5月","1939年10月"],"answer":1,"explanation":"1937年8月，毛泽东撰写《矛盾论》，深刻阐述对立统一规律，为党的思想路线奠定了哲学基础。","__sub":"毛思想"},{"id":"zz-32185","module":"zhengzhi","prompt":"毛泽东《论持久战》发表的时间是：","options":["1938年11月","1937年8月","1938年5月","1939年10月"],"answer":2,"explanation":"1938年5月，毛泽东发表《论持久战》，在全面抗战爆发十个月之际，科学预见了抗日战争的发展进程和结局。","__sub":"毛思想"},{"id":"zz-32186","module":"zhengzhi","prompt":"毛泽东《〈共产党人〉发刊词》发表的时间是：","options":["1940年1月","1939年12月","1939年10月","1941年5月"],"answer":2,"explanation":"1939年10月，毛泽东发表《〈共产党人〉发刊词》，总结了中国革命三大法宝的宝贵经验。","__sub":"毛思想"},{"id":"zz-32187","module":"zhengzhi","prompt":"毛泽东《中国革命和中国共产党》发表的时间是：","options":["1941年5月","1939年10月","1940年1月","1939年12月"],"answer":3,"explanation":"1939年12月，毛泽东发表《中国革命和中国共产党》，分析了中国社会性质和革命特点，阐述了新民主主义革命的基本问题。","__sub":"毛思想"},{"id":"zz-32188","module":"zhengzhi","prompt":"毛泽东《新民主主义论》发表的时间是：","options":["1941年5月","1939年12月","1940年5月","1940年1月"],"answer":3,"explanation":"1940年1月，毛泽东发表《新民主主义论》，系统阐述新民主主义政治、经济和文化纲领，标志着毛泽东思想走向成熟。","__sub":"毛思想"},{"id":"zz-32189","module":"zhengzhi","prompt":"毛泽东《改造我们的学习》发表的时间是：","options":["1942年5月","1940年1月","1942年2月","1941年5月"],"answer":3,"explanation":"1941年5月，毛泽东作《改造我们的学习》的报告，批判主观主义学风，成为延安整风运动的开端。","__sub":"毛思想"},{"id":"zz-32190","module":"zhengzhi","prompt":"毛泽东《整顿党的作风》发表的时间是：","options":["1942年2月","1941年5月","1942年5月","1945年4月"],"answer":0,"explanation":"1942年2月，毛泽东作《整顿党的作风》的讲演，提出反对主观主义以整顿学风、反对宗派主义以整顿党风、反对党八股以整顿文风。","__sub":"毛思想"},{"id":"zz-32191","module":"zhengzhi","prompt":"毛泽东《反对党八股》发表的时间是：","options":["1941年5月","1942年2月","1942年5月","1945年4月"],"answer":2,"explanation":"1942年5月，毛泽东发表《反对党八股》，列举党八股的八条罪状，成为延安整风运动的重要文献。","__sub":"毛思想"},{"id":"zz-32192","module":"zhengzhi","prompt":"毛泽东《在延安文艺座谈会上的讲话》发表的时间是：","options":["1942年5月","1940年1月","1942年2月","1945年4月"],"answer":0,"explanation":"1942年5月，毛泽东发表《在延安文艺座谈会上的讲话》，指明了文艺为人民大众服务的方向，推动了延安文艺界整风。","__sub":"毛思想"},{"id":"zz-32193","module":"zhengzhi","prompt":"毛泽东《论联合政府》作为政治报告提出的会议是：","options":["中共六届六中全会","中共七大","中共七届二中全会","中共八大"],"answer":1,"explanation":"1945年4月，毛泽东在中共七大上作《论联合政府》的政治报告，阐述了党的政治路线和三大优良作风。","__sub":"毛思想"},{"id":"zz-32194","module":"zhengzhi","prompt":"毛泽东提出“十大军事原则”的著作是：","options":["《目前形势和我们的任务》","《论持久战》","《中国革命战争的战略问题》","《论联合政府》"],"answer":0,"explanation":"1947年12月，毛泽东在《目前形势和我们的任务》中提出著名的十大军事原则，核心是集中优势兵力，各个歼灭敌人。","__sub":"毛思想"},{"id":"zz-32195","module":"zhengzhi","prompt":"毛泽东《在中国共产党第七届中央委员会第二次全体会议上的报告》作于：","options":["1948年12月","1949年3月","1949年6月","1949年9月"],"answer":1,"explanation":"1949年3月，毛泽东在七届二中全会上作报告，提出党的工作重心由乡村转移到城市，并告诫全党坚持“两个务必”。","__sub":"毛思想"},{"id":"zz-32196","module":"zhengzhi","prompt":"毛泽东《论人民民主专政》发表的时间是：","options":["1949年9月","1949年3月","1949年6月30日","1948年12月"],"answer":2,"explanation":"1949年6月30日，为纪念中国共产党成立28周年，毛泽东发表《论人民民主专政》，系统阐述了人民民主专政理论。","__sub":"毛思想"},{"id":"zz-32197","module":"zhengzhi","prompt":"毛泽东《论十大关系》的讲话场合是：","options":["中共七届六中全会","中共中央政治局扩大会议","最高国务会议","中共八大预备会议"],"answer":1,"explanation":"1956年4月，毛泽东在中共中央政治局扩大会议上发表《论十大关系》的讲话，随后又在最高国务会议上作了阐述。","__sub":"毛思想"},{"id":"zz-32198","module":"zhengzhi","prompt":"《星星之火，可以燎原》一文回答的核心疑问是：","options":["“红旗到底打得多久”","“中国革命走什么道路”","“抗日战争能否胜利”","“政权是否由枪杆子取得”"],"answer":0,"explanation":"针对党内一些同志对革命前途的悲观情绪，《星星之火，可以燎原》回答了“红旗到底打得多久”的疑问，坚定了革命必胜信心。","__sub":"毛思想"},{"id":"zz-32199","module":"zhengzhi","prompt":"《反对本本主义》在党的历史上的重要地位是：","options":["第一篇农村调查报告","党内第一篇反对教条主义的文献","第一篇军事著作","第一篇党的建设纲领"],"answer":1,"explanation":"《反对本本主义》尖锐批评教条主义，强调调查研究，是党内第一篇反对教条主义、倡导实事求是思想路线的文献。","__sub":"毛思想"},{"id":"zz-32200","module":"zhengzhi","prompt":"《反对本本主义》首次提出的重要概念是：","options":["“群众路线”","“思想路线”","“统一战线”","“武装斗争”"],"answer":1,"explanation":"《反对本本主义》提出“从斗争中创造新局面的思想路线”，首次在党的历史上提出“思想路线”这一概念。","__sub":"毛思想"},{"id":"zz-32201","module":"zhengzhi","prompt":"《实践论》的副标题是：","options":["论对立统一规律","论认识和实践的关系——知和行的关系","论持久战","论调查研究"],"answer":1,"explanation":"《实践论》副标题为“论认识和实践的关系——知和行的关系”，深刻论述了实践是认识的基础，认识来源于实践。","__sub":"毛思想"},{"id":"zz-32202","module":"zhengzhi","prompt":"《矛盾论》阐述的唯物辩证法的实质和核心是：","options":["对立统一规律","质量互变规律","否定之否定规律","实践与认识的规律"],"answer":0,"explanation":"《矛盾论》系统阐述对立统一规律，指出矛盾规律即对立统一规律是唯物辩证法的实质和核心。","__sub":"毛思想"},{"id":"zz-32203","module":"zhengzhi","prompt":"完整表述新民主主义革命总路线的著作或讲话是：","options":["《在晋绥干部会议上的讲话》","《新民主主义论》","《〈共产党人〉发刊词》","《论联合政府》"],"answer":0,"explanation":"1948年4月，毛泽东在《在晋绥干部会议上的讲话》中完整表述了新民主主义革命总路线，即无产阶级领导的、人民大众的、反帝反封建反官僚资本主义的革命。","__sub":"毛思想"},{"id":"zz-32204","module":"zhengzhi","prompt":"《论人民民主专政》的历史地位是：","options":["提出了抗日民族统一战线策略","标志着毛泽东思想初步形成","为新中国的建立奠定了理论基础和政策基础","确立了党的思想路线"],"answer":2,"explanation":"《论人民民主专政》系统总结了中国革命经验，阐明了即将成立的新中国的国家性质和各阶级在国家中的地位，为新中国的建立奠定了理论基础和政策基础。","__sub":"毛思想"},{"id":"zz-32205","module":"zhengzhi","prompt":"《论十大关系》的历史地位是：","options":["确立了抗日民族统一战线方针","标志着毛泽东思想萌芽","标志着新民主主义理论成熟","以苏为鉴、探索适合中国情况的社会主义建设道路的开篇之作"],"answer":3,"explanation":"《论十大关系》以苏联经验为鉴戒，初步总结了我国社会主义建设的经验，是探索适合中国情况的社会主义建设道路的开篇之作。","__sub":"毛思想"},{"id":"zz-32206","module":"zhengzhi","prompt":"《关于正确处理人民内部矛盾的问题》的理论贡献是：","options":["创立了人民战争思想","提出了新民主主义革命总路线","创立了社会主义社会两类矛盾学说","提出了三大法宝理论"],"answer":2,"explanation":"《关于正确处理人民内部矛盾的问题》系统阐述了社会主义社会矛盾学说，提出严格区分和正确处理两类不同性质的矛盾，丰富和发展了马克思主义。","__sub":"毛思想"},{"id":"zz-32207","module":"zhengzhi","prompt":"科学评价毛泽东同志历史地位和毛泽东思想的会议及文献是：","options":["1978年十一届三中全会公报","1956年中共八大通过党章","1945年中共七大通过党章","1981年十一届六中全会通过《关于建国以来党的若干历史问题的决议》"],"answer":3,"explanation":"1981年6月，十一届六中全会通过《关于建国以来党的若干历史问题的决议》，科学评价了毛泽东同志的历史地位，系统概括了毛泽东思想。","__sub":"毛思想"},{"id":"zz-32208","module":"zhengzhi","prompt":"《新民主主义论》在毛泽东思想发展史上的地位是：","options":["标志着毛泽东思想初步形成","标志着毛泽东思想萌芽","标志着毛泽东思想达到成熟","标志着毛泽东思想继续发展"],"answer":2,"explanation":"《新民主主义论》系统阐述了新民主主义革命的理论，标志着毛泽东思想在土地革命战争后期和抗日战争时期达到成熟。","__sub":"毛思想"},{"id":"zz-32209","module":"zhengzhi","prompt":"《改造我们的学习》《整顿党的作风》《反对党八股》三篇文献的共同历史背景是：","options":["延安整风运动","土地改革运动","农业合作化运动","社会主义教育运动"],"answer":0,"explanation":"这三篇文献都是延安整风运动的重要学习文献，分别从学风、党风和文风方面论述了整顿党的作风的任务。","__sub":"毛思想"},{"id":"zz-32210","module":"zhengzhi","prompt":"《论十大关系》论述的关系数量及开篇关系是：","options":["十大关系，首论重工业和轻工业、农业的关系","八大关系，首论沿海和内地的关系","十大关系，首论中央和地方的关系","十二大关系，首论经济建设和国防建设的关系"],"answer":0,"explanation":"《论十大关系》共论述了十个方面的关系，开篇第一对关系就是重工业和轻工业、农业的关系，强调不能忽视人民生活。","__sub":"毛思想"},{"id":"zz-32211","module":"zhengzhi","prompt":"毛泽东《为人民服务》是为纪念谁而作：","options":["白求恩","雷锋","刘胡兰","张思德"],"answer":3,"explanation":"1944年9月，毛泽东在张思德追悼会上发表《为人民服务》，号召学习他全心全意为人民服务的精神故选D。","__sub":"毛思想"},{"id":"zz-32212","module":"zhengzhi","prompt":"毛泽东《为人民服务》发表的时间是：","options":["1939年12月","1944年9月","1945年6月","1941年1月"],"answer":1,"explanation":"《为人民服务》是毛泽东1944年9月8日在中央警备团追悼张思德会议上的讲演；1939年12月是《纪念白求恩》的发表时间故选B。","__sub":"毛思想"},{"id":"zz-32213","module":"zhengzhi","prompt":"毛泽东《纪念白求恩》赞扬的精神是：","options":["自力更生、艰苦奋斗的精神","愚公移山、坚持不懈的精神","毫不利己、专门利人的精神","全心全意为人民服务的牺牲精神"],"answer":2,"explanation":"《纪念白求恩》赞扬白求恩毫不利己、专门利人的精神，号召学习他毫无自私自利之心的国际主义和共产主义精神故选C。","__sub":"毛思想"},{"id":"zz-32214","module":"zhengzhi","prompt":"毛泽东《纪念白求恩》发表的时间是：","options":["1944年9月","1938年5月","1945年4月","1939年12月"],"answer":3,"explanation":"《纪念白求恩》发表于1939年12月，纪念因医治伤员感染牺牲的加拿大共产党员白求恩故选D。","__sub":"毛思想"},{"id":"zz-32215","module":"zhengzhi","prompt":"毛泽东《愚公移山》的讲话场合是：","options":["中共七大开幕会","中共六届七中全会","延安各界宪政促进会成立大会","中共七大闭幕会"],"answer":3,"explanation":"《愚公移山》是毛泽东1945年6月11日在中共七大闭幕会上的闭幕词故选D。","__sub":"毛思想"},{"id":"zz-32216","module":"zhengzhi","prompt":"毛泽东《愚公移山》中把挖掉帝国主义、封建主义两座大山的希望寄托于：","options":["全中国的人民大众","共产国际的支援","国民党进步力量","苏联的直接援助"],"answer":0,"explanation":"《愚公移山》中，毛泽东把人民群众比作'上帝'，指出感动上帝、挖掉两座大山要依靠全中国的人民大众故选A。","__sub":"毛思想"},{"id":"zz-32217","module":"zhengzhi","prompt":"毛泽东'老三篇'指的是：","options":["《实践论》《矛盾论》《论持久战》","《为人民服务》《实践论》《愚公移山》","《纪念白求恩》《反对自由主义》《为人民服务》","《为人民服务》《纪念白求恩》《愚公移山》"],"answer":3,"explanation":"'老三篇'指毛泽东在延安时期写的《为人民服务》《纪念白求恩》《愚公移山》三篇著作故选D。","__sub":"毛思想"},{"id":"zz-32218","module":"zhengzhi","prompt":"'一切反动派都是纸老虎'的著名论断是毛泽东同哪位记者的谈话中提出的：","options":["埃德加·斯诺","史沫特莱","贝特兰","安娜·路易斯·斯特朗"],"answer":3,"explanation":"1946年8月，毛泽东在同美国记者安娜·路易斯·斯特朗的谈话中提出'一切反动派都是纸老虎'的著名论断故选D。","__sub":"毛思想"},{"id":"zz-32219","module":"zhengzhi","prompt":"'一切反动派都是纸老虎'论断提出的时间是：","options":["1945年8月","1947年6月","1949年10月","1946年8月"],"answer":3,"explanation":"1946年8月，全面内战爆发之初，毛泽东在同斯特朗的谈话中提出'一切反动派都是纸老虎'，指出决定战争胜负的是人民故选D。","__sub":"毛思想"},{"id":"zz-32220","module":"zhengzhi","prompt":"'中国人民站起来了'的著名论断出自：","options":["开国大典上的公告","中国人民政治协商会议第一届全体会议开幕词","中共七届二中全会报告","《论人民民主专政》"],"answer":1,"explanation":"'中国人民站起来了'出自毛泽东1949年9月21日在中国人民政治协商会议第一届全体会议上的开幕词故选B。","__sub":"毛思想"},{"id":"zz-32221","module":"zhengzhi","prompt":"'中国人民站起来了'开幕词发表的时间是：","options":["1949年10月1日","1949年9月30日","1949年9月21日","1949年7月1日"],"answer":2,"explanation":"1949年9月21日，毛泽东在政协一届全体会议开幕词中庄严宣告'中国人民站起来了'；10月1日是开国大典故选C。","__sub":"毛思想"},{"id":"zz-32222","module":"zhengzhi","prompt":"'进京赶考'这一比喻是毛泽东在什么情况下提出的：","options":["1945年中共七大闭幕时","1949年10月开国大典前","1956年中共八大召开前","1949年3月中共中央离开西柏坡前往北平时"],"answer":3,"explanation":"1949年3月，中共中央离开西柏坡迁往北平时，毛泽东把执政比作'进京赶考'，表示决不当李自成故选D。","__sub":"毛思想"},{"id":"zz-32223","module":"zhengzhi","prompt":"'进京赶考'比喻强调的主要问题是：","options":["加快解放全中国的步伐","迅速恢复国民经济","执政后要保持谦虚谨慎、艰苦奋斗的作风","加强城市工业建设"],"answer":2,"explanation":"'进京赶考'强调党执政后面临新的考验，必须继续保持谦虚谨慎、艰苦奋斗的作风，经受住执政的考验故选C。","__sub":"毛思想"},{"id":"zz-32224","module":"zhengzhi","prompt":"'不要四面出击'方针是毛泽东在哪次会议上提出的：","options":["中共七届三中全会","中共七届二中全会","中共七届四中全会","中共八大"],"answer":0,"explanation":"1950年6月，毛泽东在中共七届三中全会上的讲话中提出'不要四面出击'，强调集中力量肃清残余敌人、恢复国民经济故选A。","__sub":"毛思想"},{"id":"zz-32225","module":"zhengzhi","prompt":"'不要四面出击'方针提出的时间是：","options":["1949年3月","1951年12月","1953年6月","1950年6月"],"answer":3,"explanation":"1950年6月，毛泽东在中共七届三中全会上提出'不要四面出击'，团结一切可以团结的力量，实现国家财政经济状况基本好转故选D。","__sub":"毛思想"},{"id":"zz-32226","module":"zhengzhi","prompt":"'发展经济，保障供给'总方针提出的时间是：","options":["1938年","1945年","1942年","1950年"],"answer":2,"explanation":"1942年，毛泽东在抗日根据地经济极端困难的情况下提出'发展经济，保障供给'的总方针，领导大生产运动故选C。","__sub":"毛思想"},{"id":"zz-32227","module":"zhengzhi","prompt":"'发展经济，保障供给'属于哪方面工作的总方针：","options":["财经工作","军事工作","教育工作","统一战线工作"],"answer":0,"explanation":"'发展经济，保障供给'是抗日根据地财政经济工作的总方针，为克服经济困难、坚持抗战发挥了重要作用故选A。","__sub":"毛思想"},{"id":"zz-32228","module":"zhengzhi","prompt":"'七千人大会'上毛泽东着重强调的主题是：","options":["阶级斗争","农业合作化","民主集中制","工业化道路"],"answer":2,"explanation":"1962年1月至2月召开的七千人大会上，毛泽东着重讲了民主集中制问题，强调要造成'又有集中又有民主'的政治局面故选C。","__sub":"毛思想"},{"id":"zz-32229","module":"zhengzhi","prompt":"'七千人大会'召开的时间是：","options":["1962年1月至2月","1961年1月","1960年2月","1963年1月"],"answer":0,"explanation":"七千人大会即1962年1月至2月召开的扩大的中央工作会议，参加者达七千余人，初步总结'大跃进'以来的经验教训故选A。","__sub":"毛思想"},{"id":"zz-32230","module":"zhengzhi","prompt":"毛泽东《人的正确思想是从哪里来的？》回答的问题是：","options":["人的正确思想是从天上掉下来的","人的正确思想只能从社会实践中来","人的正确思想是头脑自生的","人的正确思想是从书本中来的"],"answer":1,"explanation":"《人的正确思想是从哪里来的？》指出，人的正确思想只能从社会实践中来，只能从社会的生产斗争、阶级斗争和科学实验这三项实践中来故选B。","__sub":"毛思想"},{"id":"zz-32231","module":"zhengzhi","prompt":"毛泽东《人的正确思想是从哪里来的？》写作的时间是：","options":["1957年","1960年","1966年","1963年"],"answer":3,"explanation":"《人的正确思想是从哪里来的？》写于1963年5月，是《实践论》思想的继续和发展故选D。","__sub":"毛思想"},{"id":"zz-32232","module":"zhengzhi","prompt":"毛泽东《关于农业合作化问题》发表的时间是：","options":["1955年","1953年","1956年","1951年"],"answer":0,"explanation":"1955年7月，毛泽东在省市自治区党委书记会议上作《关于农业合作化问题》的报告，推动农业合作化运动发展故选A。","__sub":"毛思想"},{"id":"zz-32233","module":"zhengzhi","prompt":"毛泽东《党委会的工作方法》中要求党委书记要善于当：","options":["'参谋'","'教练'","'班长'","'裁判'"],"answer":2,"explanation":"《党委会的工作方法》把党委书记比作'班长'，要求党委书记善于当好'班长'，把'一班人'指挥好故选C。","__sub":"毛思想"},{"id":"zz-32234","module":"zhengzhi","prompt":"毛泽东《党委会的工作方法》写作的时间是：","options":["1949年3月","1945年6月","1948年9月","1950年6月"],"answer":0,"explanation":"《党委会的工作方法》是毛泽东1949年3月在中共七届二中全会上的总结的一部分，系统提出了党委工作十二条方法故选A。","__sub":"毛思想"},{"id":"zz-32235","module":"zhengzhi","prompt":"毛泽东《党委会的工作方法》中'学会弹钢琴'的比喻强调：","options":["加强文艺修养","严格组织纪律","统筹兼顾各方面的工作","深入基层调研"],"answer":2,"explanation":"'弹钢琴'比喻党委要抓紧中心工作，又要围绕中心工作同时开展其他方面的工作，学会统筹兼顾故选C。","__sub":"毛思想"},{"id":"zz-32236","module":"zhengzhi","prompt":"毛泽东《抗日游击战争的战略问题》的重要观点是：","options":["把阵地战提高到战略地位","把抗日游击战争提高到战略地位","把运动战提高到战略地位","把攻坚战提高到战略地位"],"answer":1,"explanation":"1938年5月，毛泽东发表《抗日游击战争的战略问题》，系统论述了抗日游击战争的战略地位和具体战略问题故选B。","__sub":"毛思想"},{"id":"zz-32237","module":"zhengzhi","prompt":"毛泽东《抗日游击战争的战略问题》发表的时间是：","options":["1937年8月","1938年5月","1939年5月","1940年5月"],"answer":1,"explanation":"《抗日游击战争的战略问题》发表于1938年5月，与《论持久战》同期，是指导抗日游击战争的重要军事著作故选B。","__sub":"毛思想"},{"id":"zz-32238","module":"zhengzhi","prompt":"'针锋相对，寸土必争'方针出自毛泽东的著作是：","options":["《论联合政府》","《目前形势和我们的任务》","《将革命进行到底》","《抗日战争胜利后的时局和我们的方针》"],"answer":3,"explanation":"1945年8月，毛泽东在《抗日战争胜利后的时局和我们的方针》中提出对蒋介石'针锋相对，寸土必争'的方针故选D。","__sub":"毛思想"},{"id":"zz-32239","module":"zhengzhi","prompt":"'针锋相对，寸土必争'方针提出的时间是：","options":["1945年4月","1946年6月","1947年6月","1945年8月"],"answer":3,"explanation":"1945年8月抗战胜利后，毛泽东针对蒋介石假和平真内战的图谋，提出'针锋相对，寸土必争'的方针故选D。","__sub":"毛思想"},{"id":"zz-32240","module":"zhengzhi","prompt":"毛泽东强调'关心群众生活，注意工作方法'是在：","options":["抗日战争时期的延安","土地革命战争时期的中央苏区","解放战争时期的西柏坡","新中国成立后的北京"],"answer":1,"explanation":"1934年1月，毛泽东在第二次全国苏维埃代表大会上强调关心群众生活、注意工作方法，要求真心实意为群众谋利益故选B。","__sub":"毛思想"},{"id":"zz-32241","module":"zhengzhi","prompt":"新中国成立初期外交方针中'另起炉灶'的含义是：","options":["先清除帝国主义在华特权再谈建交","不承认国民党政府同各国建立的旧外交关系，在新的基础上同各国建立新的外交关系","坚定地站在社会主义阵营一边","同所有国家立即建立外交关系"],"answer":1,"explanation":"'另起炉灶'指不承认国民党政府同各国建立的旧外交关系，对旧中国同外国的条约一律不承认，在新的基础上同各国另行建立新的平等外交关系故选B。","__sub":"毛思想"},{"id":"zz-32242","module":"zhengzhi","prompt":"新中国成立初期外交方针中'打扫干净屋子再请客'的含义是：","options":["不承认旧外交关系另行建交","先清除帝国主义在华特权，再同外国建立外交关系","坚定地站在社会主义阵营一边","同社会主义国家先行建交"],"answer":1,"explanation":"'打扫干净屋子再请客'指先把帝国主义在华特权和残余势力清除干净，再同外国建立外交关系，巩固新中国的独立和主权故选B。","__sub":"毛思想"},{"id":"zz-32243","module":"zhengzhi","prompt":"新中国成立初期外交方针中'一边倒'的含义是：","options":["只同苏联建立外交关系","拒绝同西方国家来往","坚定地站在以苏联为首的社会主义阵营一边","在美苏之间保持中立"],"answer":2,"explanation":"'一边倒'指新中国坚定地站在以苏联为首的社会主义阵营一边，这是当时国际形势下的战略选择故选C。","__sub":"毛思想"},{"id":"zz-32244","module":"zhengzhi","prompt":"'百花齐放、百家争鸣'方针提出的时间是：","options":["1954年","1956年","1957年","1962年"],"answer":1,"explanation":"1956年4月，毛泽东提出'百花齐放、百家争鸣'的方针，作为繁荣和发展社会主义科学文化事业的基本方针故选B。","__sub":"毛思想"},{"id":"zz-32245","module":"zhengzhi","prompt":"'百花齐放、百家争鸣'方针适用的领域是：","options":["经济建设","国防建设","统一战线工作","科学和文化艺术工作"],"answer":3,"explanation":"'双百'方针适用于科学和文化艺术领域，鼓励艺术上不同形式和风格自由发展，科学上不同学派自由争论故选D。","__sub":"毛思想"},{"id":"zz-32246","module":"zhengzhi","prompt":"毛泽东提出的'中国工业化道路'主要是指：","options":["优先发展重工业的问题","发展乡镇企业的问题","重工业、轻工业和农业的发展关系问题","引进外国先进技术的问题"],"answer":2,"explanation":"毛泽东提出的中国工业化道路，主要指重工业、轻工业和农业的发展关系问题，强调以农业为基础、工业为主导故选C。","__sub":"毛思想"},{"id":"zz-32247","module":"zhengzhi","prompt":"土地革命战争时期党的阶级路线是：","options":["依靠富农，联合中农，消灭贫农","依靠中农，联合富农，限制贫农","依靠地主，联合农民，限制商人","依靠贫农雇农，联合中农，限制富农，保护中小工商业者，消灭地主阶级"],"answer":3,"explanation":"土地革命战争时期，党形成了依靠贫农雇农、联合中农、限制富农、保护中小工商业者、消灭地主阶级的阶级路线，壮大革命力量故选D。","__sub":"毛思想"},{"id":"zz-32248","module":"zhengzhi","prompt":"'实事求是'中'实事'的含义是：","options":["客观事物的内部联系","客观存在着的一切事物","去研究","主观愿望"],"answer":1,"explanation":"毛泽东在《改造我们的学习》中对'实事求是'作了科学阐释：'实事'就是客观存在着的一切事物，'是'就是客观事物的内部联系即规律性，'求'就是我们去研究故选B。","__sub":"毛思想"},{"id":"zz-32249","module":"zhengzhi","prompt":"'实事求是'中'求'的含义是：","options":["客观存在着的一切事物","客观事物的内部联系","主观能动性","去研究"],"answer":3,"explanation":"毛泽东对'实事求是'的阐释中，'求'就是我们去研究，即运用科学方法探求客观事物的规律性故选D。","__sub":"毛思想"},{"id":"zz-32250","module":"zhengzhi","prompt":"毛泽东《实践论》主要解决的认识论问题是：","options":["认识和实践（知和行）的关系","矛盾的普遍性和特殊性的关系","主要矛盾和次要矛盾的关系","量变和质变的关系"],"answer":0,"explanation":"《实践论》以实践为基础，深刻阐述了认识和实践（知和行）的辩证关系，揭示认识发展的辩证过程故选A。","__sub":"毛思想"},{"id":"zz-32251","module":"zhengzhi","prompt":"毛泽东写作《实践论》的主要目的是：","options":["反对经验主义","克服党内严重存在的教条主义思想","批判唯心主义先验论","总结抗日战争经验"],"answer":1,"explanation":"《实践论》副标题为'论认识和实践的关系——知和行的关系'，写作目的是克服党内严重存在的教条主义，特别是轻视实践的教条主义故选B。","__sub":"毛思想"},{"id":"zz-32252","module":"zhengzhi","prompt":"毛泽东《矛盾论》强调矛盾的特殊性，其方法论要求是：","options":["具体问题具体分析","一分为二看问题","抓住主要矛盾","坚持两点论"],"answer":0,"explanation":"《矛盾论》强调矛盾的特殊性，要求对具体事物作具体分析，这是马克思主义活的灵魂的具体体现故选A。","__sub":"毛思想"},{"id":"zz-32253","module":"zhengzhi","prompt":"毛泽东思想在马克思主义中国化进程中的历史地位是：","options":["马克思主义中国化第二次历史性飞跃的理论成果","马克思主义在中国的直接翻版","马克思主义中国化第一次历史性飞跃的理论成果","马克思主义中国化的最终理论成果"],"answer":2,"explanation":"毛泽东思想是马克思列宁主义在中国的运用和发展，是马克思主义中国化第一次历史性飞跃的理论成果故选C。","__sub":"毛思想"},{"id":"zz-32254","module":"zhengzhi","prompt":"毛泽东思想萌芽时期的时间范围是：","options":["土地革命战争前中期","土地革命战争后期和抗日战争时期","中国共产党创建时期和大革命时期","解放战争时期"],"answer":2,"explanation":"毛泽东思想萌芽于党的创建时期和大革命时期，以《中国社会各阶级的分析》《湖南农民运动考察报告》等为代表故选C。","__sub":"毛思想"},{"id":"zz-32255","module":"zhengzhi","prompt":"毛泽东思想初步形成时期的时间范围是：","options":["土地革命战争前中期","党的创建时期","抗日战争时期","解放战争时期"],"answer":0,"explanation":"毛泽东思想在土地革命战争前中期初步形成，以农村包围城市、武装夺取政权革命道路理论的提出为主要标志故选A。","__sub":"毛思想"},{"id":"zz-32256","module":"zhengzhi","prompt":"毛泽东思想继续发展时期的时间范围是：","options":["抗日战争时期","解放战争时期和新中国成立以后","土地革命战争时期","大革命时期"],"answer":1,"explanation":"解放战争时期和新中国成立以后，毛泽东思想得到继续发展，提出了人民民主专政理论、社会主义改造理论等故选B。","__sub":"毛思想"},{"id":"zz-32257","module":"zhengzhi","prompt":"毛泽东在七届二中全会上警告要警惕的'糖衣炮弹'是指：","options":["帝国主义的武装干涉","国民党的军事反扑","投机商人的囤积居奇","资产阶级的腐蚀"],"answer":3,"explanation":"毛泽东在七届二中全会上警告，可能有共产党人经不起人们用糖衣裹着的炮弹的攻击，即在胜利面前被资产阶级的腐蚀所打倒故选D。","__sub":"毛思想"},{"id":"zz-32258","module":"zhengzhi","prompt":"大生产运动中毛泽东提出的口号是：","options":["自己动手，丰衣足食","发展经济，保障供给","自力更生，奋发图强","艰苦奋斗，勤俭建国"],"answer":0,"explanation":"抗日战争时期，毛泽东发出'自己动手，丰衣足食'的号召，领导解放区军民开展大生产运动，克服经济困难故选A。","__sub":"毛思想"},{"id":"zz-32259","module":"zhengzhi","prompt":"延安时期'精兵简政'建议的提出者是：","options":["爱国侨领陈嘉庚","民主人士黄炎培","国民党元老于右任","党外人士李鼎铭"],"answer":3,"explanation":"1941年，党外人士李鼎铭提出'精兵简政'建议，毛泽东予以采纳，将其作为克服根据地物质困难的重要政策故选D。","__sub":"毛思想"},{"id":"zz-32260","module":"zhengzhi","prompt":"毛泽东《在延安文艺座谈会上的讲话》提出的文艺方针是：","options":["文艺为政治运动服务","文艺为市场经济服务","文艺为人民大众（首先为工农兵）服务","文艺为知识分子服务"],"answer":2,"explanation":"1942年5月，毛泽东在延安文艺座谈会上系统阐明了文艺为人民大众首先为工农兵服务的方向，解决了文艺为什么人的问题故选C。","__sub":"毛思想"},{"id":"zz-32261","module":"zhengzhi","prompt":"毛泽东提出'三个世界'划分的时间是：","options":["1971年","1972年","1974年","1976年"],"answer":2,"explanation":"1974年2月，毛泽东会见赞比亚总统卡翁达时提出关于三个世界划分的思想，为我国外交战略提供了重要依据故选C。","__sub":"毛思想"},{"id":"zz-32262","module":"zhengzhi","prompt":"毛泽东'三个世界'划分中，第一世界是指：","options":["亚非拉发展中国家","美国和苏联两个超级大国","欧洲和日本","中国和其他社会主义国家"],"answer":1,"explanation":"毛泽东关于三个世界的划分中，美苏两个超级大国是第一世界，亚非拉等发展中国家是第三世界，介于两者之间的是第二世界故选B。","__sub":"毛思想"},{"id":"zz-32263","module":"zhengzhi","prompt":"毛泽东'向雷锋同志学习'题词的时间是：","options":["1962年3月","1963年3月","1964年3月","1965年3月"],"answer":1,"explanation":"1963年3月，毛泽东题词'向雷锋同志学习'，全国掀起学习雷锋的热潮，雷锋精神影响深远故选B。","__sub":"毛思想"},{"id":"zz-32264","module":"zhengzhi","prompt":"毛泽东提出的对待敌人的战略战术思想是：","options":["战略上重视敌人，战术上藐视敌人","战略战术都藐视敌人","战略上藐视敌人，战术上重视敌人","战略战术都重视敌人"],"answer":2,"explanation":"毛泽东提出'战略上藐视敌人，战术上重视敌人'，即在全局上敢于斗争、敢于胜利，在具体作战上重视敌人、讲究斗争艺术故选C。","__sub":"毛思想"},{"id":"zz-32265","module":"zhengzhi","prompt":"抗日民主政权'三三制'的人员构成是：","options":["共产党员占三分之二","国民党代表占三分之一","共产党员、非党的左派进步分子和不左不右的中间派各占三分之一","工农代表占三分之二"],"answer":2,"explanation":"抗日民主政权实行'三三制'，共产党员、非党的左派进步分子和不左不右的中间派各占三分之一，团结各抗日阶层故选C。","__sub":"毛思想"},{"id":"zz-32266","module":"zhengzhi","prompt":"抗日战争时期党在根据地实行的土地政策是：","options":["没收地主土地","耕者有其田","减租减息","土地国有"],"answer":2,"explanation":"抗日战争时期，党将没收地主土地的政策改为减租减息，既减轻农民负担，又团结地主抗日，维护抗日民族统一战线故选C。","__sub":"毛思想"},{"id":"zz-32267","module":"zhengzhi","prompt":"红军游击战争'十六字诀'的提出者是：","options":["毛泽东","朱德","周恩来","彭德怀"],"answer":0,"explanation":"毛泽东在井冈山斗争中提出'敌进我退，敌驻我扰，敌疲我打，敌退我追'的游击战争十六字诀故选A。","__sub":"毛思想"},{"id":"zz-32268","module":"zhengzhi","prompt":"毛泽东提出'农民问题乃国民革命的中心问题'的著作是：","options":["《中国社会各阶级的分析》","《湖南农民运动考察报告》","《星星之火，可以燎原》","《国民革命与农民运动》"],"answer":3,"explanation":"1926年9月，毛泽东在《国民革命与农民运动》中指出'农民问题乃国民革命的中心问题'，强调农民在中国革命中的重要地位故选D。","__sub":"毛思想"},{"id":"zz-32269","module":"zhengzhi","prompt":"毛泽东提出的对待中外文化遗产的方针是：","options":["古为今用，洋为中用","全盘继承，全面引进","彻底否定，全盘西化","厚古薄今，重外轻中"],"answer":0,"explanation":"毛泽东提出'古为今用，洋为中用'，主张批判地继承历史遗产和吸收外国有益成果，为社会主义文化建设服务故选A。","__sub":"毛思想"},{"id":"zz-32270","module":"zhengzhi","prompt":"毛泽东提出的解决人民内部矛盾的重要方针是：","options":["全面专政、彻底斗争","各自为政、互不干涉","统筹兼顾、适当安排","优先发展、重点突破"],"answer":2,"explanation":"毛泽东在《关于正确处理人民内部矛盾的问题》中提出'统筹兼顾、适当安排'的方针，正确处理人民内部各方面的利益关系故选C。","__sub":"毛思想"},{"id":"zz-32271","module":"zhengzhi","prompt":"毛泽东《论反对日本帝国主义的策略》阐述的核心问题是：","options":["持久战的三个阶段","游击战争的战略地位","建立抗日民族统一战线的必要性和可能性","新民主主义革命的总路线"],"answer":2,"explanation":"1935年12月，毛泽东在瓦窑堡会议后作《论反对日本帝国主义的策略》的报告，系统论述了建立抗日民族统一战线的必要性和可能性故选C。","__sub":"毛思想"},{"id":"zz-32272","module":"zhengzhi","prompt":"毛泽东《将革命进行到底》作为新年献词发表的时间是：","options":["1947年","1949年","1948年","1950年"],"answer":1,"explanation":"1949年，毛泽东发表新年献词《将革命进行到底》，揭露中外反动派'划江而治'的图谋，号召将革命进行到底故选B。","__sub":"毛思想"},{"id":"zz-32273","module":"zhengzhi","prompt":"毛泽东晚年错误与毛泽东思想的关系是：","options":["晚年错误是毛泽东思想的组成部分","晚年错误否定了毛泽东思想","两者没有区别","毛泽东思想是被实践证明了的正确理论原则和经验总结，晚年错误不属于毛泽东思想"],"answer":3,"explanation":"毛泽东思想是被实践证明了的关于中国革命和建设的正确的理论原则和经验总结，毛泽东晚年的错误不属于毛泽东思想的科学体系故选D。","__sub":"毛思想"},{"id":"zz-32274","module":"zhengzhi","prompt":"'人民，只有人民，才是创造世界历史的动力'这一论断出自：","options":["《论联合政府》","《为人民服务》","《愚公移山》","《新民主主义论》"],"answer":0,"explanation":"毛泽东在《论联合政府》中指出'人民，只有人民，才是创造世界历史的动力'，体现了人民群众是历史创造者的唯物史观故选A。","__sub":"毛思想"},{"id":"zz-32275","module":"zhengzhi","prompt":"延安整风运动坚持的方针是：","options":["残酷斗争，无情打击","惩前毖后，治病救人","以牙还牙，以眼还眼","各自检讨，互不追究"],"answer":1,"explanation":"延安整风运动坚持'惩前毖后，治病救人'的方针，既弄清思想又团结同志，达到了全党团结统一的目的故选B。","__sub":"毛思想"},{"id":"zz-32276","module":"zhengzhi","prompt":"毛泽东《论十大关系》借鉴苏联经验教训提出的探索原则是：","options":["以美为鉴","以苏为鉴","以欧为鉴","以日为鉴"],"answer":1,"explanation":"《论十大关系》以苏联经验为鉴戒，总结我国经验，提出调动一切积极因素为社会主义事业服务的基本方针，探索适合中国的建设道路故选B。","__sub":"毛思想"},{"id":"zz-32277","module":"zhengzhi","prompt":"毛泽东提出马克思主义同中国实际进行'第二次结合'的背景是：","options":["1921年中国共产党成立时","1935年遵义会议后","1978年改革开放后","1956年社会主义改造基本完成后探索适合中国的社会主义建设道路"],"answer":3,"explanation":"1956年社会主义改造基本完成后，毛泽东提出要实现马克思主义同中国实际的'第二次结合'，努力找出在中国进行社会主义建设的正确道路故选D。","__sub":"毛思想"},{"id":"zz-32278","module":"zhengzhi","prompt":"毛泽东军事战略思想的基础是：","options":["消极防御","全面进攻","积极防御","阵地决战"],"answer":2,"explanation":"积极防御是毛泽东军事战略思想的基础，强调战略上的防御与战役战斗上的进攻相结合，后发制人故选C。","__sub":"毛思想"},{"id":"zz-32279","module":"zhengzhi","prompt":"毛泽东在《论持久战》中强调战争的决定因素是：","options":["人不是物","武器不是人","经济实力","国际援助"],"answer":0,"explanation":"毛泽东在《论持久战》中指出，武器是战争的重要的因素，但不是决定的因素，决定的因素是人不是物故选A。","__sub":"毛思想"},{"id":"zz-32280","module":"zhengzhi","prompt":"毛泽东提出战争的基本目的是：","options":["占领城市，夺取政权","消耗敌人，等待援助","速战速决，歼灭主力","保存自己，消灭敌人"],"answer":3,"explanation":"毛泽东指出，战争的目的不是别的，就是'保存自己，消灭敌人'，这是战争的本质要求，也是一切战争行动的根据故选D。","__sub":"毛思想"},{"id":"zz-32281","module":"zhengzhi","prompt":"中共一大确定党成立后的中心任务是：","options":["开展武装斗争，夺取中心城市","进行土地革命，建立根据地","组织工人阶级，领导工人运动","联合国民党，共同北伐"],"answer":2,"explanation":"中共一大确定党成立后的中心工作是组织工人阶级、领导工人运动；土地革命和武装斗争是大革命失败后确定的方针，联合国民党北伐是1924年国共合作后的任务故选C。","__sub":"党史"},{"id":"zz-32282","module":"zhengzhi","prompt":"中共一大开幕的地点是：","options":["北京","广州","武汉","上海"],"answer":3,"explanation":"1921年7月23日，中共一大在上海法租界望志路106号开幕故选D。","__sub":"党史"},{"id":"zz-32283","module":"zhengzhi","prompt":"中共一大最后一天的会议是在哪里举行的：","options":["上海法租界","浙江嘉兴南湖的游船上","杭州西湖","苏州太湖"],"answer":1,"explanation":"因法租界巡捕搜查，中共一大最后一天转移到浙江嘉兴南湖一艘游船上举行，通过党的第一个纲领和决议故选B。","__sub":"党史"},{"id":"zz-32284","module":"zhengzhi","prompt":"中共一大选举的中央局中负责宣传工作的是：","options":["张国焘","陈潭秋","李达","董必武"],"answer":2,"explanation":"中共一大选举产生中央局，陈独秀任书记，张国焘负责组织，李达负责宣传；其余选项均为一大代表，但未在中央局负责宣传故选C。","__sub":"党史"},{"id":"zz-32285","module":"zhengzhi","prompt":"中共一大确定党的名称是：","options":["中国共产主义者同盟","中国共产党","中华革命党","中国社会主义者同盟"],"answer":1,"explanation":"中共一大确定党的名称为'中国共产党'，明确党的奋斗目标是以无产阶级革命军队推翻资产阶级政权故选B。","__sub":"党史"},{"id":"zz-32286","module":"zhengzhi","prompt":"中共二大召开的时间是：","options":["1921年7月","1922年7月","1923年6月","1922年1月"],"answer":1,"explanation":"1922年7月，中共二大在上海召开，第一次明确提出了反帝反封建的民主革命纲领故选B。","__sub":"党史"},{"id":"zz-32287","module":"zhengzhi","prompt":"中共二大提出的民主革命纲领是：","options":["推翻资产阶级政权，建立无产阶级专政","打倒列强，除军阀，建立工农政权","废除私有制，实行公有制","打倒军阀，推翻国际帝国主义的压迫，统一中国为真正的民主共和国"],"answer":3,"explanation":"中共二大提出党的最低纲领即民主革命纲领：打倒军阀，推翻国际帝国主义的压迫，统一中国为真正的民主共和国故选D。","__sub":"党史"},{"id":"zz-32288","module":"zhengzhi","prompt":"中共二大召开的地点是：","options":["上海","广州","武汉","北京"],"answer":0,"explanation":"1922年7月，中共二大在上海召开，分析了中国的社会性质和革命性质故选A。","__sub":"党史"},{"id":"zz-32289","module":"zhengzhi","prompt":"中共三大召开的时间和地点是：","options":["1923年6月，广州","1922年7月，上海","1924年1月，广州","1923年6月，上海"],"answer":0,"explanation":"1923年6月，中共三大在广州召开，讨论国共合作问题故选A。","__sub":"党史"},{"id":"zz-32290","module":"zhengzhi","prompt":"中共三大作出的重要决定是：","options":["共产党员以个人身份加入国民党","全体共产党员加入国民党并取消共产党组织","与国民党建立党际联盟","建立抗日民族统一战线"],"answer":0,"explanation":"中共三大决定共产党员以个人身份加入国民党，同时保持党在政治上、思想上、组织上的独立性故选A。","__sub":"党史"},{"id":"zz-32291","module":"zhengzhi","prompt":"中国国民党第一次全国代表大会召开的时间和地点是：","options":["1923年6月，上海","1924年1月，广州","1924年1月，北京","1925年7月，广州"],"answer":1,"explanation":"1924年1月，中国国民党一大在广州召开，标志着第一次国共合作正式形成故选B。","__sub":"党史"},{"id":"zz-32292","module":"zhengzhi","prompt":"第一次国共合作采取的合作形式是：","options":["党内合作","党外合作","党际联盟","联合政府"],"answer":0,"explanation":"第一次国共合作采取党内合作形式，即共产党员以个人身份加入国民党，同时保持党在政治上、思想上、组织上的独立性；党外合作是后来提出的设想，联合政府是抗战末期的主张故选A。","__sub":"党史"},{"id":"zz-32293","module":"zhengzhi","prompt":"国民党一大对三民主义作出的新解释被称为：","options":["旧三民主义","真三民主义","革命三民主义","新三民主义"],"answer":3,"explanation":"国民党一大把旧三民主义发展为新三民主义，成为国共合作的政治基础故选D。","__sub":"党史"},{"id":"zz-32294","module":"zhengzhi","prompt":"黄埔军校建立的时间是：","options":["1923年5月","1925年5月","1924年1月","1924年5月"],"answer":3,"explanation":"1924年5月，黄埔军校在广州成立，孙中山任军校总理，蒋介石任校长，周恩来后任政治部主任故选D。","__sub":"党史"},{"id":"zz-32295","module":"zhengzhi","prompt":"北伐战争开始的时间是：","options":["1926年7月","1925年7月","1927年7月","1926年1月"],"answer":0,"explanation":"1926年7月，国民革命军誓师北伐，直接打击目标是吴佩孚、孙传芳、张作霖三个军阀集团故选A。","__sub":"党史"},{"id":"zz-32296","module":"zhengzhi","prompt":"北伐战争打击的主要对象不包括：","options":["吴佩孚","孙传芳","段祺瑞","张作霖"],"answer":2,"explanation":"北伐战争的对象是吴佩孚、孙传芳、张作霖三个军阀集团，段祺瑞不在其列故选C。","__sub":"党史"},{"id":"zz-32297","module":"zhengzhi","prompt":"四一二反革命政变的发动者是：","options":["蒋介石","汪精卫","张作霖","冯玉祥"],"answer":0,"explanation":"1927年4月12日，蒋介石在上海发动反革命政变，大肆屠杀共产党人和革命群众故选A。","__sub":"党史"},{"id":"zz-32298","module":"zhengzhi","prompt":"七一五反革命政变的发动者是：","options":["汪精卫","蒋介石","许克祥","何应钦"],"answer":0,"explanation":"1927年7月15日，汪精卫在武汉发动'七一五'反革命政变，第一次国共合作全面破裂故选A。","__sub":"党史"},{"id":"zz-32299","module":"zhengzhi","prompt":"大革命失败的最主要教训是：","options":["必须放弃国共合作","必须立即开展土地革命","必须依靠共产国际的指导","必须坚持无产阶级对革命的领导权特别是武装力量的领导权"],"answer":3,"explanation":"大革命失败的教训表明，必须坚持无产阶级对革命的领导权，特别是掌握革命武装，否则革命无法成功故选D。","__sub":"党史"},{"id":"zz-32300","module":"zhengzhi","prompt":"大革命失败的时间标志是：","options":["1927年汪精卫'七一五'反革命政变","1927年蒋介石'四一二'反革命政变","1927年南昌起义","1928年济南惨案"],"answer":0,"explanation":"1927年7月15日汪精卫'分共'，标志着第一次国共合作全面破裂、大革命失败故选A。","__sub":"党史"},{"id":"zz-32301","module":"zhengzhi","prompt":"南昌起义发生的时间是：","options":["1927年9月9日","1927年7月15日","1927年8月1日","1928年1月1日"],"answer":2,"explanation":"1927年8月1日，周恩来、贺龙、叶挺、朱德、刘伯承领导南昌起义，打响了武装反抗国民党反动派的第一枪故选C。","__sub":"党史"},{"id":"zz-32302","module":"zhengzhi","prompt":"南昌起义的历史意义是：","options":["打响了武装反抗国民党反动派的第一枪","确立了农村包围城市的道路","确立了思想建党、政治建军原则","建立了第一个农村革命根据地"],"answer":0,"explanation":"南昌起义打响了武装反抗国民党反动派的第一枪，标志着党独立领导革命战争、创建人民军队的开始故选A。","__sub":"党史"},{"id":"zz-32303","module":"zhengzhi","prompt":"南昌起义的主要领导人不包括：","options":["周恩来","贺龙","毛泽东","叶挺"],"answer":2,"explanation":"南昌起义由周恩来、贺龙、叶挺、朱德、刘伯承等领导，毛泽东当时领导的是湘赣边界秋收起义故选C。","__sub":"党史"},{"id":"zz-32304","module":"zhengzhi","prompt":"八七会议召开的时间和地点是：","options":["1927年8月1日，南昌","1927年8月7日，汉口","1927年9月9日，长沙","1928年1月，上海"],"answer":1,"explanation":"1927年8月7日，中共中央在汉口召开紧急会议，即八七会议，纠正右倾错误，确定新方针故选B。","__sub":"党史"},{"id":"zz-32305","module":"zhengzhi","prompt":"八七会议后毛泽东领导的武装起义是：","options":["南昌起义","广州起义","湘南起义","秋收起义"],"answer":3,"explanation":"八七会议决定发动秋收起义，会后毛泽东以中央特派员身份领导了湘赣边界秋收起义；南昌起义由周恩来等领导，广州起义是1927年12月张太雷等领导的故选D。","__sub":"党史"},{"id":"zz-32306","module":"zhengzhi","prompt":"'枪杆子里面出政权'论断的提出场合是：","options":["八七会议","古田会议","遵义会议","瓦窑堡会议"],"answer":0,"explanation":"毛泽东在八七会议上提出'枪杆子里面出政权'的著名论断，强调武装斗争的重要性故选A。","__sub":"党史"},{"id":"zz-32307","module":"zhengzhi","prompt":"毛泽东领导的湘赣边界秋收起义发生的时间是：","options":["1927年8月","1927年10月","1927年9月","1928年1月"],"answer":2,"explanation":"1927年9月，毛泽东领导湘赣边界秋收起义，进攻长沙受挫后转向农村，开辟井冈山革命根据地故选C。","__sub":"党史"},{"id":"zz-32308","module":"zhengzhi","prompt":"三湾改编确立的重要原则是：","options":["官兵一致","支部建在连上","民主集中制","党指挥枪的绝对领导"],"answer":1,"explanation":"1927年9月，三湾改编把党支部建在连上，从组织上确立了党对军队的领导，是建设新型人民军队的重要开端故选B。","__sub":"党史"},{"id":"zz-32309","module":"zhengzhi","prompt":"中国共产党创建的第一个农村革命根据地是：","options":["井冈山革命根据地","中央革命根据地","鄂豫皖革命根据地","湘鄂西革命根据地"],"answer":0,"explanation":"1927年10月，毛泽东率秋收起义部队到达井冈山，创建了中国第一个农村革命根据地故选A。","__sub":"党史"},{"id":"zz-32310","module":"zhengzhi","prompt":"古田会议召开的时间和地点是：","options":["1929年12月，福建上杭古田","1928年12月，江西井冈山","1929年12月，江西瑞金","1930年12月，福建长汀"],"answer":0,"explanation":"1929年12月，红四军党的第九次代表大会（古田会议）在福建上杭古田村召开故选A。","__sub":"党史"},{"id":"zz-32311","module":"zhengzhi","prompt":"古田会议确立的原则是：","options":["武装斗争、土地革命","统一战线、武装斗争","民主集中、集体领导","思想建党、政治建军"],"answer":3,"explanation":"古田会议确立了思想建党、政治建军的原则，规定红军必须服从党的领导，担负打仗、筹款、做群众工作三大任务故选D。","__sub":"党史"},{"id":"zz-32312","module":"zhengzhi","prompt":"土地革命战争时期危害最大的'左'倾错误是：","options":["瞿秋白'左'倾盲动主义错误","李立三'左'倾冒险主义错误","王明'左'倾教条主义错误","罗章龙分裂主义错误"],"answer":2,"explanation":"王明'左'倾教条主义错误在党内统治时间最长、危害最大，直接导致第五次反'围剿'失败和红军被迫长征故选C。","__sub":"党史"},{"id":"zz-32313","module":"zhengzhi","prompt":"第五次反'围剿'失败的主要原因是：","options":["敌我力量过分悬殊","根据地经济困难","博古、李德等'左'倾错误的军事指挥","共产国际停止援助"],"answer":2,"explanation":"1934年，由于博古、李德等实行'左'倾错误的军事指挥，中央红军第五次反'围剿'失败，被迫长征故选C。","__sub":"党史"},{"id":"zz-32314","module":"zhengzhi","prompt":"遵义会议解决的最迫切的问题是：","options":["军事问题和组织问题","思想路线问题","土地政策问题","经济方针问题"],"answer":0,"explanation":"遵义会议集中解决了当时具有决定意义的军事问题和组织问题，结束了“左”倾教条主义错误在中央的统治；思想路线问题到延安整风时期才系统解决故选A。","__sub":"党史"},{"id":"zz-32315","module":"zhengzhi","prompt":"遵义会议召开的地点是：","options":["四川泸州","贵州遵义","云南扎西","贵州毕节"],"answer":1,"explanation":"1935年1月，中共中央政治局扩大会议在贵州遵义召开，史称遵义会议故选B。","__sub":"党史"},{"id":"zz-32316","module":"zhengzhi","prompt":"遵义会议的历史意义是：","options":["党的历史上一个生死攸关的转折点","确立了抗日民族统一战线方针","确定了土地革命总路线","宣告长征胜利结束"],"answer":0,"explanation":"遵义会议事实上确立了毛泽东在党中央和红军的领导地位，在极其危急的关头挽救了党、挽救了红军、挽救了中国革命，是党的历史上生死攸关的转折点故选A。","__sub":"党史"},{"id":"zz-32317","module":"zhengzhi","prompt":"遵义会议集中解决的问题是：","options":["政治路线问题","军事问题和组织问题","土地政策问题","经济纲领问题"],"answer":1,"explanation":"遵义会议集中解决了当时具有决定意义的军事问题和组织问题，没有涉及政治路线问题故选B。","__sub":"党史"},{"id":"zz-32318","module":"zhengzhi","prompt":"中央红军开始长征的时间是：","options":["1933年10月","1935年1月","1936年10月","1934年10月"],"answer":3,"explanation":"1934年10月，中央红军从江西瑞金等地出发，开始战略转移，即长征故选D。","__sub":"党史"},{"id":"zz-32319","module":"zhengzhi","prompt":"红军长征后，党中央和红军主力落脚的革命根据地是：","options":["井冈山革命根据地","中央革命根据地","鄂豫皖革命根据地","陕甘革命根据地"],"answer":3,"explanation":"1935年10月，中央红军到达陕北，与陕甘红军会师，陕甘革命根据地成为党中央和红军长征的落脚点故选D。","__sub":"党史"},{"id":"zz-32320","module":"zhengzhi","prompt":"瓦窑堡会议召开的时间是：","options":["1935年1月","1936年12月","1937年8月","1935年12月"],"answer":3,"explanation":"1935年12月，中共中央在陕北瓦窑堡召开政治局会议，确立了建立抗日民族统一战线的策略方针故选D。","__sub":"党史"},{"id":"zz-32321","module":"zhengzhi","prompt":"瓦窑堡会议确立的方针是：","options":["开展土地革命","进行战略转移","建立抗日民族统一战线","全面抗战"],"answer":2,"explanation":"瓦窑堡会议分析了国内阶级关系的变化，确立了建立抗日民族统一战线的策略方针故选C。","__sub":"党史"},{"id":"zz-32322","module":"zhengzhi","prompt":"西安事变发生的时间是：","options":["1936年12月9日","1937年7月7日","1936年10月22日","1936年12月12日"],"answer":3,"explanation":"1936年12月12日，张学良、杨虎城发动西安事变，扣押蒋介石，逼蒋抗日故选D。","__sub":"党史"},{"id":"zz-32323","module":"zhengzhi","prompt":"西安事变和平解决的重要意义是：","options":["十年内战基本结束，国共第二次合作初步形成","抗日战争全面爆发","抗日民族统一战线正式形成","国共实现第三次合作"],"answer":0,"explanation":"西安事变和平解决，成为时局转换的枢纽，十年内战的局面基本结束，国共第二次合作初步形成故选A。","__sub":"党史"},{"id":"zz-32324","module":"zhengzhi","prompt":"洛川会议召开的时间是：","options":["1937年7月","1937年8月","1937年9月","1938年5月"],"answer":1,"explanation":"1937年8月，中共中央在陕北洛川召开政治局扩大会议，通过《抗日救国十大纲领》故选B。","__sub":"党史"},{"id":"zz-32325","module":"zhengzhi","prompt":"洛川会议确定的抗战路线是：","options":["全面抗战路线","片面抗战路线","消极防御路线","持久消耗路线"],"answer":0,"explanation":"洛川会议提出动员全民族一切力量、实行人民战争的全面抗战路线，与国民党的片面抗战路线相对立故选A。","__sub":"党史"},{"id":"zz-32326","module":"zhengzhi","prompt":"平型关大捷发生的时间是：","options":["1937年8月","1938年5月","1940年8月","1937年9月"],"answer":3,"explanation":"1937年9月，八路军第一一五师在平型关伏击日军，取得全国抗战以来中国军队的第一个重大胜利故选D。","__sub":"党史"},{"id":"zz-32327","module":"zhengzhi","prompt":"平型关大捷的作战部队是：","options":["八路军第120师","八路军第115师","八路军第129师","新四军"],"answer":1,"explanation":"1937年9月，八路军第115师在平型关伏击日军，取得全国抗战开始后中国军队的第一个重大胜利；第120师、第129师当时在别的方向作战，新四军活动于华中故选B。","__sub":"党史"},{"id":"zz-32328","module":"zhengzhi","prompt":"百团大战发生的时间是：","options":["1939年下半年","1941年上半年","1940年下半年","1940年上半年"],"answer":2,"explanation":"1940年8月至12月，八路军在华北发动百团大战，沉重打击了日军的'囚笼政策'故选C。","__sub":"党史"},{"id":"zz-32329","module":"zhengzhi","prompt":"百团大战发生在抗日战争的哪个阶段：","options":["战略防御阶段","战略相持阶段","战略反攻阶段","战略决战阶段"],"answer":1,"explanation":"百团大战发生于1940年下半年，此时抗日战争已进入战略相持阶段；战略防御阶段为1937年7月至1938年10月，反攻和决战阶段更晚故选B。","__sub":"党史"},{"id":"zz-32330","module":"zhengzhi","prompt":"皖南事变发生的时间是：","options":["1941年1月","1940年1月","1941年7月","1942年1月"],"answer":0,"explanation":"1941年1月，国民党顽固派制造皖南事变，围袭奉命北移的新四军军部，新四军将士大部壮烈牺牲故选A。","__sub":"党史"},{"id":"zz-32331","module":"zhengzhi","prompt":"延安整风运动普遍整风开始的时间是：","options":["1941年","1943年","1940年","1942年"],"answer":3,"explanation":"1942年2月，毛泽东作《整顿党的作风》的报告，延安整风运动在全党普遍展开故选D。","__sub":"党史"},{"id":"zz-32332","module":"zhengzhi","prompt":"中共六届七中全会通过的历史文件是：","options":["《关于建国以来党的若干历史问题的决议》","《关于党的百年奋斗重大成就和历史经验的决议》","《关于若干历史问题的决议》","《关于增强党性的决定》"],"answer":2,"explanation":"1945年4月20日，中共六届七中全会通过《关于若干历史问题的决议》，总结了党的历史经验，为七大召开作了准备故选C。","__sub":"党史"},{"id":"zz-32333","module":"zhengzhi","prompt":"中共七大召开的时间和地点是：","options":["1945年4月至6月，西柏坡","1945年4月至6月，延安","1944年4月至6月，延安","1945年8月，重庆"],"answer":1,"explanation":"1945年4月23日至6月11日，中共七大在延安杨家岭召开，出席代表547名故选B。","__sub":"党史"},{"id":"zz-32334","module":"zhengzhi","prompt":"中共七大的政治报告是：","options":["《新民主主义论》","《论人民民主专政》","《论联合政府》","《目前形势和我们的任务》"],"answer":2,"explanation":"毛泽东在中共七大上作《论联合政府》的政治报告，提出了党的政治路线和三大作风故选C。","__sub":"党史"},{"id":"zz-32335","module":"zhengzhi","prompt":"中共七大概括的党的优良作风是：","options":["谦虚谨慎的作风、艰苦奋斗的作风、实事求是的作风","理论和实践相结合的作风、和人民群众紧密地联系在一起的作风、自我批评的作风","民主的作风、团结的作风、批评的作风","调查研究的作风、群众路线的作风、独立自主的作风"],"answer":1,"explanation":"中共七大概括了党的三大优良作风：理论和实践相结合的作风、和人民群众紧密地联系在一起的作风、自我批评的作风故选B。","__sub":"党史"},{"id":"zz-32336","module":"zhengzhi","prompt":"中共七大确立为党的指导思想的是：","options":["新民主主义理论","人民民主专政理论","列宁主义","毛泽东思想"],"answer":3,"explanation":"中共七大把毛泽东思想确立为党的指导思想并写入党章，这是党的历史上具有深远意义的大事故选D。","__sub":"党史"},{"id":"zz-32337","module":"zhengzhi","prompt":"日本宣布无条件投降的时间是：","options":["1945年9月2日","1945年8月15日","1945年9月3日","1945年10月1日"],"answer":1,"explanation":"1945年8月15日，日本宣布无条件投降；9月2日签署投降书，9月3日成为中国人民抗日战争胜利纪念日故选B。","__sub":"党史"},{"id":"zz-32338","module":"zhengzhi","prompt":"抗日战争胜利的根本意义是：","options":["中国成为世界强国","国共实现第二次合作","近代以来中国反抗外敌入侵第一次取得完全胜利","中国收复东北失地"],"answer":2,"explanation":"抗日战争的胜利是近代以来中国人民反抗外敌入侵第一次取得完全胜利的民族解放战争，是中华民族由衰败走向复兴的重大转折点故选C。","__sub":"党史"},{"id":"zz-32339","module":"zhengzhi","prompt":"重庆谈判开始的时间是：","options":["1945年8月","1945年9月","1946年1月","1945年10月"],"answer":0,"explanation":"1945年8月28日，毛泽东赴重庆与国民党进行谈判，10月10日双方签订《双十协定》故选A。","__sub":"党史"},{"id":"zz-32340","module":"zhengzhi","prompt":"重庆谈判签订的文件是：","options":["《停战协定》","《双十协定》","《共同纲领》","《会谈纪要》"],"answer":1,"explanation":"1945年10月10日，国共双方代表签订《政府与中共代表会谈纪要》，即《双十协定》故选B。","__sub":"党史"},{"id":"zz-32341","module":"zhengzhi","prompt":"全面内战爆发的标志是：","options":["1946年6月国民党进攻陕北解放区","1945年10月进攻上党地区","1946年6月国民党军队进攻中原解放区","1947年3月进攻延安"],"answer":2,"explanation":"1946年6月，国民党军队大举进攻中原解放区，全面内战爆发故选C。","__sub":"党史"},{"id":"zz-32342","module":"zhengzhi","prompt":"解放战争时期的三大战役是：","options":["渡江战役、淮海战役、平津战役","辽沈战役、渡江战役、淮海战役","辽沈战役、淮海战役、平津战役","济南战役、辽沈战役、平津战役"],"answer":2,"explanation":"1948年9月至1949年1月，人民解放军连续进行辽沈、淮海、平津三大战役，基本消灭了国民党军队主力故选C。","__sub":"党史"},{"id":"zz-32343","module":"zhengzhi","prompt":"淮海战役发生的时间是：","options":["1948年9月至11月","1948年11月至1949年1月","1948年11月至1949年3月","1949年4月"],"answer":1,"explanation":"淮海战役于1948年11月6日发起，1949年1月10日结束，共歼敌55万余人故选B。","__sub":"党史"},{"id":"zz-32344","module":"zhengzhi","prompt":"中共七届二中全会召开的时间和地点是：","options":["1949年3月，北平","1948年12月，西柏坡","1949年3月，西柏坡","1949年9月，北平"],"answer":2,"explanation":"1949年3月，中共七届二中全会在河北平山西柏坡召开，讨论党的工作重心转移等问题故选C。","__sub":"党史"},{"id":"zz-32345","module":"zhengzhi","prompt":"七届二中全会提出的党的工作重心是：","options":["由城市转移到乡村","由军事转向经济","由北方转向南方","由乡村转移到城市"],"answer":3,"explanation":"七届二中全会指出，党的工作重心由乡村转移到了城市，必须用极大的努力去学会管理城市和建设城市故选D。","__sub":"党史"},{"id":"zz-32346","module":"zhengzhi","prompt":"渡江战役发起的时间是：","options":["1949年3月","1949年5月","1948年12月","1949年4月"],"answer":3,"explanation":"1949年4月21日，毛泽东、朱德发布《向全国进军的命令》，百万雄师横渡长江故选D。","__sub":"党史"},{"id":"zz-32347","module":"zhengzhi","prompt":"南京解放的时间是：","options":["1949年4月21日","1949年5月27日","1949年10月1日","1949年4月23日"],"answer":3,"explanation":"1949年4月23日，人民解放军占领南京，宣告了国民党反动统治的覆灭故选D。","__sub":"党史"},{"id":"zz-32348","module":"zhengzhi","prompt":"中国人民政治协商会议第一届全体会议召开的时间是：","options":["1949年9月","1949年10月","1949年8月","1948年9月"],"answer":0,"explanation":"1949年9月21日至30日，中国人民政治协商会议第一届全体会议在北平召开，筹备建立新中国故选A。","__sub":"党史"},{"id":"zz-32349","module":"zhengzhi","prompt":"《共同纲领》在当时起的作用是：","options":["正式宪法","基本法律","临时宪法","行政条例"],"answer":2,"explanation":"《中国人民政治协商会议共同纲领》在新中国成立初期起临时宪法的作用故选C。","__sub":"党史"},{"id":"zz-32350","module":"zhengzhi","prompt":"开国大典举行的时间是：","options":["1949年9月30日","1949年10月9日","1949年10月1日","1950年1月1日"],"answer":2,"explanation":"1949年10月1日，毛泽东在天安门城楼上宣告中华人民共和国中央人民政府成立，开国大典隆重举行故选C。","__sub":"党史"},{"id":"zz-32351","module":"zhengzhi","prompt":"《中华人民共和国土地改革法》颁布的时间是：","options":["1950年6月","1949年10月","1951年6月","1952年6月"],"answer":0,"explanation":"1950年6月，中央人民政府颁布《中华人民共和国土地改革法》，在新解放区开展土地改革；1952年底土地改革基本完成故选A。","__sub":"党史"},{"id":"zz-32352","module":"zhengzhi","prompt":"全国土地改革基本完成的时间是：","options":["1952年底","1950年底","1953年底","1956年底"],"answer":0,"explanation":"到1952年底，除部分少数民族地区外，全国土地改革基本完成，彻底废除了封建土地制度；1956年底是三大改造完成的时间故选A。","__sub":"党史"},{"id":"zz-32353","module":"zhengzhi","prompt":"土地改革彻底废除的制度是：","options":["资本主义剥削制度","个体私有制度","富农经济制度","封建土地剥削制度"],"answer":3,"explanation":"土地改革废除地主阶级封建剥削的土地所有制，实行农民的土地所有制，解放了农村生产力；选项中的资本主义剥削制度不是土改对象故选D。","__sub":"党史"},{"id":"zz-32354","module":"zhengzhi","prompt":"中国人民志愿军司令员是：","options":["林彪","彭德怀","刘伯承","陈毅"],"answer":1,"explanation":"1950年10月，彭德怀受命担任中国人民志愿军司令员兼政治委员，指挥抗美援朝作战；林彪当时并未担任该职故选B。","__sub":"党史"},{"id":"zz-32355","module":"zhengzhi","prompt":"中国人民志愿军跨过鸭绿江入朝作战的时间是：","options":["1950年6月","1951年6月","1949年10月","1950年10月"],"answer":3,"explanation":"1950年10月，应朝鲜党和政府请求，中国人民志愿军入朝作战；1950年6月是朝鲜战争爆发和中央作出组建志愿军决策的时间故选D。","__sub":"党史"},{"id":"zz-32356","module":"zhengzhi","prompt":"抗美援朝战争结束的标志是：","options":["1953年7月日内瓦会议召开","1953年7月签订停战协定","1954年4月万隆会议召开","1952年10月上甘岭战役结束"],"answer":1,"explanation":"1953年7月27日，朝鲜停战协定在板门店签署，抗美援朝战争胜利结束；日内瓦会议1954年召开，万隆会议1955年召开故选B。","__sub":"党史"},{"id":"zz-32357","module":"zhengzhi","prompt":"抗美援朝战争中用胸膛堵住敌人机枪射口的英雄是：","options":["邱少云","黄继光","董存瑞","杨根思"],"answer":1,"explanation":"黄继光在上甘岭战役中用胸膛堵住敌人机枪射口壮烈牺牲；董存瑞是解放战争时期的舍身炸碉堡英雄，邱少云是严守纪律烈火中牺牲的英雄故选B。","__sub":"党史"},{"id":"zz-32358","module":"zhengzhi","prompt":"1951年底开展的“三反”运动的内容是：","options":["反贪污、反浪费、反官僚主义","反行贿、反偷税漏税、反盗骗国家财产","反贪污、反盗窃、反投机倒把","反浪费、反保守、反冒进"],"answer":0,"explanation":"1951年底，党中央决定在国家机关中开展反贪污、反浪费、反官僚主义的“三反”运动；反行贿等是1952年“五反”运动的内容故选A。","__sub":"党史"},{"id":"zz-32359","module":"zhengzhi","prompt":"“三反”运动中被处决的贪污犯是：","options":["刘青山、张子善","刘少奇、张闻天","刘峙、张灵甫","刘伯承、张云逸"],"answer":0,"explanation":"1952年，原天津地委书记刘青山、专员张子善因贪污罪被判处死刑，史称“刘张案”，是“三反”运动的标志性事件；其余选项均为革命干部姓名，属易混干扰故选A。","__sub":"党史"},{"id":"zz-32360","module":"zhengzhi","prompt":"1952年开展的“五反”运动针对的对象是：","options":["国家机关工作人员","农村地主阶级","私营工商业者","党内高级干部"],"answer":2,"explanation":"1952年，在私营工商业者中开展反行贿、反偷税漏税、反盗骗国家财产、反偷工减料、反盗窃经济情报的“五反”运动；针对国家机关的是“三反”故选C。","__sub":"党史"},{"id":"zz-32361","module":"zhengzhi","prompt":"第一个五年计划的时间范围是：","options":["1952—1956年","1954—1958年","1953—1958年","1953—1957年"],"answer":3,"explanation":"第一个五年计划从1953年开始执行，到1957年超额完成，集中力量发展重工业；1952年是国民经济恢复完成的时间故选D。","__sub":"党史"},{"id":"zz-32362","module":"zhengzhi","prompt":"第一个五年计划期间苏联援建的重点项目数量是：","options":["100个","156个","256个","56个"],"answer":1,"explanation":"“一五”期间，苏联援建我国156个重点工业项目，奠定了社会主义工业化的初步基础；其余数字均为易混干扰故选B。","__sub":"党史"},{"id":"zz-32363","module":"zhengzhi","prompt":"1956年我国第一辆解放牌汽车诞生的工厂是：","options":["长春第一汽车制造厂","沈阳第一机床厂","武汉钢铁公司","鞍山钢铁公司"],"answer":0,"explanation":"1956年，长春第一汽车制造厂生产出第一批解放牌汽车，结束了中国不能制造汽车的历史；沈阳第一机床厂等其他企业并非第一辆汽车的诞生地故选A。","__sub":"党史"},{"id":"zz-32364","module":"zhengzhi","prompt":"第一个五年计划期间建成的第一座长江大桥位于：","options":["武汉","南京","重庆","九江"],"answer":0,"explanation":"1957年，武汉长江大桥建成通车，实现了“一桥飞架南北，天堑变通途”；南京长江大桥是1968年建成的故选A。","__sub":"党史"},{"id":"zz-32365","module":"zhengzhi","prompt":"1954年建成通车的进藏公路是：","options":["新藏、滇藏公路","川藏、青藏公路","青藏、新藏公路","川藏、滇藏公路"],"answer":1,"explanation":"1954年12月，川藏、青藏公路同时建成通车，创造了公路建设史上的壮举；新藏公路1957年建成，滇藏公路更晚故选B。","__sub":"党史"},{"id":"zz-32366","module":"zhengzhi","prompt":"党在过渡时期总路线提出的时间是：","options":["1951年","1955年","1956年","1953年"],"answer":3,"explanation":"1953年，党正式提出过渡时期总路线，即“一化三改”；1956年是社会主义改造基本完成的时间故选D。","__sub":"党史"},{"id":"zz-32367","module":"zhengzhi","prompt":"过渡时期总路线的主体是：","options":["逐步实现对农业的社会主义改造","逐步实现国家的社会主义工业化","逐步实现对手工业的社会主义改造","逐步实现对资本主义工商业的社会主义改造"],"answer":1,"explanation":"过渡时期总路线是“一化三改、一体两翼”，工业化是主体，三大改造是两翼；选项中的改造内容均为“两翼”部分故选B。","__sub":"党史"},{"id":"zz-32368","module":"zhengzhi","prompt":"第一届全国人民代表大会召开的时间是：","options":["1953年9月","1955年9月","1954年9月","1956年9月"],"answer":2,"explanation":"1954年9月，第一届全国人民代表大会第一次会议在北京召开，通过了新中国第一部宪法；1956年9月是中共八大召开时间故选C。","__sub":"党史"},{"id":"zz-32369","module":"zhengzhi","prompt":"新中国第一部宪法通过于：","options":["1949年","1954年","1956年","1975年"],"answer":1,"explanation":"1954年9月，一届全国人大一次会议通过《中华人民共和国宪法》，这是新中国第一部社会主义类型宪法；1949年通过的是《共同纲领》故选B。","__sub":"党史"},{"id":"zz-32370","module":"zhengzhi","prompt":"中国共产党第八次全国代表大会召开的时间是：","options":["1956年6月","1957年9月","1958年9月","1956年9月"],"answer":3,"explanation":"1956年9月，中共八大在北京召开，这是新中国成立后党召开的第一次全国代表大会；其余时间均不正确故选D。","__sub":"党史"},{"id":"zz-32371","module":"zhengzhi","prompt":"中共八大指出的国内主要矛盾是：","options":["无产阶级和资产阶级之间的矛盾","人民日益增长的物质文化需要同落后的社会生产之间的矛盾","生产的社会化同生产资料私有制之间的矛盾","人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾"],"answer":3,"explanation":"中共八大指出，国内主要矛盾已经是人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾；“人民日益增长的物质文化需要”的表述是1981年十一届六中全会提出的故选D。","__sub":"党史"},{"id":"zz-32372","module":"zhengzhi","prompt":"中共八大确定的主要任务是：","options":["进行社会主义改造","开展人民公社化运动","开展无产阶级文化大革命","集中力量发展社会生产力"],"answer":3,"explanation":"中共八大提出，全国人民的主要任务是集中力量发展社会生产力，实现国家工业化；社会主义改造在八大召开时已基本完成故选D。","__sub":"党史"},{"id":"zz-32373","module":"zhengzhi","prompt":"中共八大确定的经济建设方针是：","options":["鼓足干劲，力争上游，多快好省","既反保守又反冒进，在综合平衡中稳步前进","调整、巩固、充实、提高","发展经济，保障供给"],"answer":1,"explanation":"中共八大坚持既反保守又反冒进、在综合平衡中稳步前进的经济建设方针；“鼓足干劲”是1958年社会主义建设总路线，“调整、巩固、充实、提高”是1961年提出的八字方针故选B。","__sub":"党史"},{"id":"zz-32374","module":"zhengzhi","prompt":"社会主义基本制度在我国确立的标志是：","options":["1954年宪法的颁布","1957年一五计划完成","1956年底社会主义改造基本完成","1949年中华人民共和国成立"],"answer":2,"explanation":"1956年底，三大改造基本完成，社会主义基本制度在我国确立；新中国成立时是过渡时期，一五计划1957年才完成故选C。","__sub":"党史"},{"id":"zz-32375","module":"zhengzhi","prompt":"1958年提出的社会主义建设总路线是：","options":["既反保守又反冒进，在综合平衡中稳步前进","调整、巩固、充实、提高","以农业为基础、以工业为主导","鼓足干劲，力争上游，多快好省地建设社会主义"],"answer":3,"explanation":"1958年5月，八大二次会议通过“鼓足干劲，力争上游，多快好省地建设社会主义”的总路线；其余选项分别是八大方针、八字方针和后来的提法故选D。","__sub":"党史"},{"id":"zz-32376","module":"zhengzhi","prompt":"人民公社化运动开始于：","options":["1958年","1956年","1959年","1960年"],"answer":0,"explanation":"1958年，在社会主义建设总路线提出后，全国农村一哄而起开展人民公社化运动，超越了当时的生产力水平；1956年是三大改造完成时间故选A。","__sub":"党史"},{"id":"zz-32377","module":"zhengzhi","prompt":"1959年庐山会议后期错误开展的斗争是针对：","options":["刘少奇","邓小平","彭德怀","周恩来"],"answer":2,"explanation":"1959年庐山会议后期，错误地开展了对彭德怀的批判，进而在全党开展了“反右倾”斗争，打断了纠“左”进程；其余选项均不符合史实故选C。","__sub":"党史"},{"id":"zz-32378","module":"zhengzhi","prompt":"1964年底三届全国人大一次会议提出的宏伟目标是：","options":["实现工业化","实现小康","实现四个现代化","实现共同富裕"],"answer":2,"explanation":"1964年底至1965年初，周恩来在三届全国人大一次会议上作政府工作报告，首次提出把我国建设成为具有现代农业、现代工业、现代国防和现代科学技术的社会主义强国故选C。","__sub":"党史"},{"id":"zz-32379","module":"zhengzhi","prompt":"我国第一颗原子弹爆炸成功的地点是：","options":["新疆罗布泊","甘肃酒泉","青海海晏","四川绵阳"],"answer":0,"explanation":"1964年10月16日，我国第一颗原子弹在新疆罗布泊试验场爆炸成功；酒泉、海晏、绵阳均为核工业相关基地，但不是第一颗原子弹的爆炸地点故选A。","__sub":"党史"},{"id":"zz-32380","module":"zhengzhi","prompt":"我国第一颗氢弹爆炸成功的时间是：","options":["1966年10月","1964年10月","1967年6月","1968年6月"],"answer":2,"explanation":"1967年6月17日，我国第一颗氢弹空爆试验成功，从原子弹到氢弹仅用两年零八个月，速度居世界前列故选C。","__sub":"党史"},{"id":"zz-32381","module":"zhengzhi","prompt":"我国第一颗人造地球卫星发射成功的时间是：","options":["1970年4月","1969年4月","1971年4月","1972年4月"],"answer":0,"explanation":"1970年4月24日，我国第一颗人造地球卫星东方红一号发射成功，使我国成为世界上第五个能独立发射卫星的国家；其余时间均不正确故选A。","__sub":"党史"},{"id":"zz-32382","module":"zhengzhi","prompt":"“文化大革命”发动的标志是：","options":["1965年11月姚文元发表《评新编历史剧〈海瑞罢官〉》","1966年8月中共八届十一中全会召开","1969年4月中共九大召开","1966年5月中央政治局扩大会议通过《五一六通知》"],"answer":3,"explanation":"1966年5月中央政治局扩大会议通过《五一六通知》，“文化大革命”正式发动；姚文元文章只是导火索，八届十一中全会是发动后的会议故选D。","__sub":"党史"},{"id":"zz-32383","module":"zhengzhi","prompt":"“文化大革命”结束的标志是：","options":["1976年10月粉碎“四人帮”","1971年9月九一三事件","1976年1月周恩来逝世","1977年7月十届三中全会召开"],"answer":0,"explanation":"1976年10月，党中央粉碎江青反革命集团，“文化大革命”结束；九一三事件是林彪反革命集团覆灭的标志故选A。","__sub":"党史"},{"id":"zz-32384","module":"zhengzhi","prompt":"九一三事件发生于：","options":["1971年9月","1970年9月","1972年9月","1973年9月"],"answer":0,"explanation":"1971年9月13日，林彪等人乘飞机外逃，在蒙古温都尔汗附近坠机身亡，史称九一三事件，客观上宣告了“文化大革命”理论和实践的失败故选A。","__sub":"党史"},{"id":"zz-32385","module":"zhengzhi","prompt":"中华人民共和国恢复在联合国合法席位是在第几届联合国大会上：","options":["第24届","第25届","第27届","第26届"],"answer":3,"explanation":"1971年10月25日，第26届联合国大会通过第2758号决议，恢复中华人民共和国在联合国的一切合法权利；其余届次均不正确故选D。","__sub":"党史"},{"id":"zz-32386","module":"zhengzhi","prompt":"1972年2月访华的美国总统是：","options":["基辛格","尼克松","福特","卡特"],"answer":1,"explanation":"1972年2月，美国总统尼克松访华，双方在上海发表《联合公报》，中美关系开始走向正常化；基辛格是总统国家安全事务助理，曾秘密访华故选B。","__sub":"党史"},{"id":"zz-32387","module":"zhengzhi","prompt":"中美两国正式建立外交关系的时间是：","options":["1979年1月1日","1972年2月21日","1978年12月16日","1980年1月1日"],"answer":0,"explanation":"1979年1月1日，中美正式建立外交关系；1978年12月16日是中美发表建交公报的时间，易混淆故选A。","__sub":"党史"},{"id":"zz-32388","module":"zhengzhi","prompt":"中日邦交正常化实现于：","options":["1971年9月","1972年9月","1972年2月","1978年8月"],"answer":1,"explanation":"1972年9月，日本首相田中角荣访华，中日签署联合声明，实现邦交正常化；1972年2月是尼克松访华时间故选B。","__sub":"党史"},{"id":"zz-32389","module":"zhengzhi","prompt":"和平共处五项原则的首次提出者是：","options":["毛泽东","刘少奇","周恩来","邓小平"],"answer":2,"explanation":"1953年12月，周恩来在会见印度代表团时首次提出和平共处五项原则，后成为国际关系基本准则；其余选项均不符合史实故选C。","__sub":"党史"},{"id":"zz-32390","module":"zhengzhi","prompt":"和平共处五项原则中居于首要地位的是：","options":["互不侵犯","互不干涉内政","互相尊重主权和领土完整","平等互利"],"answer":2,"explanation":"和平共处五项原则以互相尊重主权和领土完整为首要原则，其余各项均在此基础上展开；互不侵犯、互不干涉内政、平等互利分别是第二至第四项故选C。","__sub":"党史"},{"id":"zz-32391","module":"zhengzhi","prompt":"新中国首次以世界五大国之一身份参加的国际会议是：","options":["1955年万隆会议","1954年日内瓦会议","1971年联合国大会","1961年不结盟会议"],"answer":1,"explanation":"1954年4月至7月，周恩来率团参加日内瓦会议，这是新中国首次以五大国之一身份参加的国际会议；万隆会议是亚非会议，不涉及五大国身份故选B。","__sub":"党史"},{"id":"zz-32392","module":"zhengzhi","prompt":"万隆会议上周恩来提出的方针是：","options":["另起炉灶","求同存异","打扫干净屋子再请客","一边倒"],"answer":1,"explanation":"1955年4月，周恩来在万隆会议上提出“求同存异”方针，推动会议取得成功；“另起炉灶”等是新中国成立初期的外交方针故选B。","__sub":"党史"},{"id":"zz-32393","module":"zhengzhi","prompt":"万隆会议召开的时间是：","options":["1954年4月","1956年4月","1955年4月","1957年4月"],"answer":2,"explanation":"1955年4月，亚非会议在印度尼西亚万隆举行，这是第一次没有西方殖民国家参加的亚非会议；1954年4月是日内瓦会议召开时间故选C。","__sub":"党史"},{"id":"zz-32394","module":"zhengzhi","prompt":"20世纪60年代中期开始的三线建设，重点布局的地区是：","options":["中西部内陆地区","东南沿海地区","东北地区","京津地区"],"answer":0,"explanation":"1964年起，基于备战需要，国家在中西部内陆地区开展三线建设，形成一大批工业基地；东南沿海当时被称为一线地区故选A。","__sub":"党史"},{"id":"zz-32395","module":"zhengzhi","prompt":"被誉为“铁人”的大庆石油工人是：","options":["焦裕禄","雷锋","时传祥","王进喜"],"answer":3,"explanation":"王进喜是大庆油田工人，以“宁肯少活二十年，拼命也要拿下大油田”的忘我精神被誉为“铁人”；焦裕禄是兰考县委书记故选D。","__sub":"党史"},{"id":"zz-32396","module":"zhengzhi","prompt":"被称颂为“党的好干部”的兰考县委书记是：","options":["王进喜","孔繁森","谷文昌","焦裕禄"],"answer":3,"explanation":"焦裕禄1962年任河南兰考县委书记，带领群众治理内涝、风沙、盐碱，积劳成疾去世，被誉为“党的好干部”；王进喜是石油工人故选D。","__sub":"党史"},{"id":"zz-32397","module":"zhengzhi","prompt":"1961年党中央提出的对国民经济实行的方针是：","options":["鼓足干劲，力争上游，多快好省","既反保守又反冒进，综合平衡","发展经济，保障供给","调整、巩固、充实、提高"],"answer":3,"explanation":"1961年1月，八届九中全会决定对国民经济实行“调整、巩固、充实、提高”的八字方针；“鼓足干劲”是1958年总路线的表述故选D。","__sub":"党史"},{"id":"zz-32398","module":"zhengzhi","prompt":"1950年6月党的七届三中全会提出的任务是：","options":["争取国家财政经济状况的基本好转","实现国家工业化","完成社会主义改造","开展文化大革命"],"answer":0,"explanation":"1950年6月，七届三中全会确定党在国民经济恢复时期的中心任务是争取国家财政经济状况的基本好转；工业化、改造均非当时提出的中心任务故选A。","__sub":"党史"},{"id":"zz-32399","module":"zhengzhi","prompt":"1978年5月《光明日报》发表的引起真理标准问题讨论的文章是：","options":["《解放思想，实事求是，团结一致向前看》","《坚持四项基本原则》","《在武昌、深圳、珠海、上海等地的谈话要点》","《实践是检验真理的唯一标准》"],"answer":3,"explanation":"1978年5月11日，《光明日报》发表特约评论员文章《实践是检验真理的唯一标准》，引发关于真理标准问题的大讨论；《解放思想，实事求是，团结一致向前看》是邓小平在中央工作会议上的讲话故选D。","__sub":"党史"},{"id":"zz-32400","module":"zhengzhi","prompt":"关于真理标准问题讨论的重大意义是：","options":["直接宣告了文化大革命的结束","是一场深刻的思想解放运动，为十一届三中全会召开作了思想准备","标志着改革开放全面展开","确立了社会主义市场经济体制目标"],"answer":1,"explanation":"真理标准问题大讨论冲破了“两个凡是”的思想禁锢，是一场深刻的思想解放运动，为党的十一届三中全会召开作了思想理论准备故选B。","__sub":"党史"},{"id":"zz-32401","module":"zhengzhi","prompt":"党的十一届三中全会重新成立的机构是：","options":["中央顾问委员会","中央纪律检查委员会","中央监察委员会","国家监察委员会"],"answer":1,"explanation":"党的十一届三中全会决定恢复成立中央纪律检查委员会，陈云任第一书记，为拨乱反正和端正党风提供了组织保证；中央顾问委员会是1982年设立的，中央监察委员会是1927年设立的故选B。","__sub":"党史"},{"id":"zz-32402","module":"zhengzhi","prompt":"党的十一届三中全会重新确立的思想路线是：","options":["独立自主、自力更生","百花齐放、百家争鸣","解放思想、实事求是","与时俱进、开拓创新"],"answer":2,"explanation":"十一届三中全会冲破长期“左”的错误的严重束缚，重新确立了解放思想、实事求是的思想路线；“百花齐放、百家争鸣”是文艺学术方针故选C。","__sub":"党史"},{"id":"zz-32403","module":"zhengzhi","prompt":"党的十一届三中全会形成的领导核心是：","options":["以毛泽东为核心的第一代中央领导集体","以江泽民为核心的第三代中央领导集体","以胡锦涛为总书记的党中央","以邓小平为核心的第二代中央领导集体"],"answer":3,"explanation":"十一届三中全会后，以邓小平为核心的第二代中央领导集体逐步形成，开创了改革开放和社会主义现代化建设新时期故选D。","__sub":"党史"},{"id":"zz-32404","module":"zhengzhi","prompt":"十一届三中全会作出把党和国家工作中心转移到：","options":["政治斗争上来","文化建设上来","经济建设上来","国防建设上来"],"answer":2,"explanation":"十一届三中全会果断结束“以阶级斗争为纲”，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策故选C。","__sub":"党史"},{"id":"zz-32405","module":"zhengzhi","prompt":"我国农村实行家庭联产承包责任制的开端是：","options":["1978年底安徽凤阳小岗村农民实行分田到户","1958年河南七里营建立人民公社","1980年广东深圳设立经济特区","1982年江苏华西村兴办乡镇企业"],"answer":0,"explanation":"1978年底，安徽凤阳小岗村农民率先实行分田到户、包产到户，拉开了农村改革的序幕；人民公社化运动是1958年的“左”的错误故选A。","__sub":"党史"},{"id":"zz-32406","module":"zhengzhi","prompt":"1980年中央决定设立的经济特区是：","options":["上海、天津、广州、福州","海南、浦东、滨海、重庆","深圳、珠海、汕头、厦门","大连、青岛、宁波、温州"],"answer":2,"explanation":"1980年5月，中央决定在深圳、珠海、汕头、厦门设立经济特区，作为对外开放的窗口和试验田；海南是1988年设立的省级经济特区故选C。","__sub":"党史"},{"id":"zz-32407","module":"zhengzhi","prompt":"我国最大的经济特区是：","options":["海南","深圳","浦东","厦门"],"answer":0,"explanation":"1988年4月，七届全国人大一次会议批准设立海南省，划定海南岛为经济特区，这是我国最大的经济特区；深圳是第一个经济特区故选A。","__sub":"党史"},{"id":"zz-32408","module":"zhengzhi","prompt":"邓小平在党的十二大开幕词中提出的著名论断是：","options":["发展才是硬道理","走自己的道路，建设有中国特色的社会主义","科学技术是第一生产力","和平与发展是当代世界的两大问题"],"answer":1,"explanation":"1982年9月，邓小平在十二大开幕词中提出“走自己的道路，建设有中国特色的社会主义”，成为新时期改革的旗帜；“发展才是硬道理”出自1992年南方谈话故选B。","__sub":"党史"},{"id":"zz-32409","module":"zhengzhi","prompt":"党的十三大系统阐述的重大理论是：","options":["社会主义初级阶段理论","社会主义市场经济理论","社会主义本质理论","社会主义和谐社会理论"],"answer":0,"explanation":"1987年10月，党的十三大系统阐述了社会主义初级阶段理论，制定了党在社会主义初级阶段的基本路线；社会主义市场经济体制目标是十四大提出的故选A。","__sub":"党史"},{"id":"zz-32410","module":"zhengzhi","prompt":"党在社会主义初级阶段基本路线的核心内容是：","options":["一个中心、两个基本点","两手抓、两手都要硬","三步走战略","两个文明一起抓"],"answer":0,"explanation":"党的基本路线概括为“一个中心、两个基本点”，即以经济建设为中心，坚持四项基本原则，坚持改革开放；其余选项均非基本路线的核心表述故选A。","__sub":"党史"},{"id":"zz-32411","module":"zhengzhi","prompt":"党的十三大制定的社会主义现代化建设“三步走”战略部署的第一步是：","options":["人民生活达到小康水平","解决人民的温饱问题","达到中等发达国家水平","全面建成小康社会"],"answer":1,"explanation":"十三大“三步走”战略：第一步解决温饱，第二步到20世纪末达到小康，第三步到21世纪中叶达到中等发达国家水平；其余选项分别是第二步、第三步的目标故选B。","__sub":"党史"},{"id":"zz-32412","module":"zhengzhi","prompt":"1992年初邓小平南方谈话中提出的著名论断是：","options":["走自己的道路，建设有中国特色的社会主义","发展才是硬道理","一个中心、两个基本点","科学技术是第一生产力"],"answer":1,"explanation":"1992年1月至2月，邓小平视察武昌、深圳、珠海、上海等地并发表南方谈话，提出“发展才是硬道理”；“走自己的道路”出自1982年十二大开幕词故选B。","__sub":"党史"},{"id":"zz-32413","module":"zhengzhi","prompt":"南方谈话中邓小平关于计划和市场的重要观点是：","options":["计划和市场都是经济手段","计划经济是社会主义的本质特征","市场经济是资本主义的专利","计划和市场不能结合"],"answer":0,"explanation":"南方谈话指出，计划多一点还是市场多一点，不是社会主义与资本主义的本质区别，计划和市场都是经济手段，为十四大确立市场经济体制目标奠定基础故选A。","__sub":"党史"},{"id":"zz-32414","module":"zhengzhi","prompt":"党的十四大明确提出的经济体制改革目标是：","options":["建立计划与市场相结合的体制","建立有计划的商品经济体制","建立社会主义市场经济体制","建立现代企业制度"],"answer":2,"explanation":"1992年10月，党的十四大明确提出我国经济体制改革的目标是建立社会主义市场经济体制；“有计划的商品经济”是1984年的提法故选C。","__sub":"党史"},{"id":"zz-32415","module":"zhengzhi","prompt":"党的十五大把什么理论确立为党的指导思想并写入党章：","options":["“三个代表”重要思想","科学发展观","习近平新时代中国特色社会主义思想","邓小平理论"],"answer":3,"explanation":"1997年9月，党的十五大把邓小平理论确立为党的指导思想并写入党章；“三个代表”重要思想是2002年十六大写入党章的故选D。","__sub":"党史"},{"id":"zz-32416","module":"zhengzhi","prompt":"党的十五大提出的治国基本方略是：","options":["以德治国","依法治国","依规治党","科教兴国"],"answer":1,"explanation":"1997年，党的十五大提出依法治国、建设社会主义法治国家，把依法治国确定为党领导人民治理国家的基本方略故选B。","__sub":"党史"},{"id":"zz-32417","module":"zhengzhi","prompt":"党的十六大把什么思想确立为党的指导思想并写入党章：","options":["“三个代表”重要思想","邓小平理论","科学发展观","毛泽东思想"],"answer":0,"explanation":"2002年11月，党的十六大把“三个代表”重要思想确立为党的指导思想并写入党章，提出全面建设小康社会的奋斗目标；邓小平理论是十五大写入党章的故选A。","__sub":"党史"},{"id":"zz-32418","module":"zhengzhi","prompt":"科学发展观写入党章是在：","options":["党的十七大","党的十六大","党的十八大","党的十五大"],"answer":0,"explanation":"2007年10月，党的十七大把科学发展观写入党章；2012年党的十八大进一步把科学发展观确立为党的指导思想故选A。","__sub":"党史"},{"id":"zz-32419","module":"zhengzhi","prompt":"科学发展观被确立为党的指导思想是在：","options":["党的十七大","党的十六大","党的十九大","党的十八大"],"answer":3,"explanation":"2012年11月，党的十八大把科学发展观确立为党必须长期坚持的指导思想；十七大只是将其写入党章故选D。","__sub":"党史"},{"id":"zz-32420","module":"zhengzhi","prompt":"党的十一届六中全会通过的重要文件是：","options":["《关于若干历史问题的决议》","《关于建国以来党的若干历史问题的决议》","《中共中央关于党的百年奋斗重大成就和历史经验的决议》","《关于经济体制改革的决定》"],"answer":1,"explanation":"1981年6月，十一届六中全会通过《关于建国以来党的若干历史问题的决议》，标志着党在指导思想上的拨乱反正胜利完成；《关于若干历史问题的决议》是1945年六届七中全会通过的故选B。","__sub":"党史"},{"id":"zz-32421","module":"zhengzhi","prompt":"中英两国政府签署关于香港问题联合声明的时间是：","options":["1984年12月","1982年9月","1990年4月","1997年6月"],"answer":0,"explanation":"1984年12月，中英两国政府在北京正式签署关于香港问题的联合声明，确认中国于1997年7月1日对香港恢复行使主权故选A。","__sub":"党史"},{"id":"zz-32422","module":"zhengzhi","prompt":"香港特别行政区成立的时间是：","options":["1984年12月19日","1997年7月1日","1990年4月4日","1999年12月20日"],"answer":1,"explanation":"1997年7月1日，中国政府对香港恢复行使主权，香港特别行政区成立；1999年12月20日是澳门回归时间故选B。","__sub":"党史"},{"id":"zz-32423","module":"zhengzhi","prompt":"中国政府恢复对澳门行使主权所依据的文件是：","options":["中英联合声明","九二共识","中葡联合声明","开罗宣言"],"answer":2,"explanation":"1987年4月，中葡两国政府签署关于澳门问题的联合声明，确认中国于1999年12月20日对澳门恢复行使主权；中英联合声明针对的是香港问题故选C。","__sub":"党史"},{"id":"zz-32424","module":"zhengzhi","prompt":"“一国两制”构想的提出者是：","options":["邓小平","毛泽东","周恩来","叶剑英"],"answer":0,"explanation":"“一国两制”是邓小平在20世纪80年代初提出的实现祖国和平统一的创造性构想，最早是针对台湾问题提出的，首先运用于解决香港问题故选A。","__sub":"党史"},{"id":"zz-32425","module":"zhengzhi","prompt":"“一国两制”构想最早是针对什么问题提出的：","options":["香港问题","台湾问题","澳门问题","西藏问题"],"answer":1,"explanation":"“一国两制”构想最早是针对台湾问题提出的，但首先运用于解决香港、澳门问题；香港、澳门是其实践对象而非最初针对对象故选B。","__sub":"党史"},{"id":"zz-32426","module":"zhengzhi","prompt":"香港特别行政区保持原有的资本主义制度和生活方式的年限是：","options":["30年不变","100年不变","50年不变","20年不变"],"answer":2,"explanation":"按照“一国两制”方针和基本法，香港保持原有的资本主义制度和生活方式50年不变；其余年限均不正确故选C。","__sub":"党史"},{"id":"zz-32427","module":"zhengzhi","prompt":"海峡两岸均坚持一个中国原则的“九二共识”达成于：","options":["1990年","1992年","1993年","1995年"],"answer":1,"explanation":"1992年，海峡两岸关系协会与台湾海基会达成各自以口头方式表述“海峡两岸均坚持一个中国原则”的共识，史称“九二共识”故选B。","__sub":"党史"},{"id":"zz-32428","module":"zhengzhi","prompt":"中国加入世界贸易组织标志着：","options":["我国经济体制改革的开始","社会主义市场经济体制的建立","我国对外开放进入新阶段","经济特区建设的起步"],"answer":2,"explanation":"2001年12月，中国正式加入世界贸易组织，标志着我国对外开放进入新阶段；经济体制改革始于1978年，市场经济体制目标于1992年确立，经济特区建设始于1980年故选C。","__sub":"党史"},{"id":"zz-32429","module":"zhengzhi","prompt":"西部大开发战略提出的时间是：","options":["1995年","2002年","2005年","2000年"],"answer":3,"explanation":"2000年，党中央作出实施西部大开发战略的决策，重点支持西部地区基础设施建设等，促进区域协调发展故选D。","__sub":"党史"},{"id":"zz-32430","module":"zhengzhi","prompt":"科教兴国战略提出的时间是：","options":["1990年","2000年","1995年","2005年"],"answer":2,"explanation":"1995年，党中央提出实施科教兴国战略，把科技和教育摆在经济社会发展的重要位置；1988年邓小平提出的是“科学技术是第一生产力”故选C。","__sub":"党史"},{"id":"zz-32431","module":"zhengzhi","prompt":"“三个代表”重要思想首次提出是在：","options":["2000年2月广东考察时","1997年9月党的十五大上","2001年7月建党80周年讲话中","2002年11月党的十六大上"],"answer":0,"explanation":"2000年2月，江泽民在广东考察工作时首次完整提出“三个代表”要求；十五大提出的是邓小平理论，十六大将其写入党章故选A。","__sub":"党史"},{"id":"zz-32432","module":"zhengzhi","prompt":"科学发展观首次提出是在：","options":["2002年11月党的十六大上","2007年10月党的十七大上","2003年10月党的十六届三中全会上","2004年9月十六届四中全会上"],"answer":2,"explanation":"2003年10月，党的十六届三中全会提出坚持以人为本、全面协调可持续的科学发展观；十七大是将其写入党章故选C。","__sub":"党史"},{"id":"zz-32433","module":"zhengzhi","prompt":"“科学技术是第一生产力”论断的提出者是：","options":["毛泽东","周恩来","江泽民","邓小平"],"answer":3,"explanation":"1988年9月，邓小平提出“科学技术是第一生产力”的论断，丰富和发展了马克思主义关于生产力的学说；其余选项均不符合史实故选D。","__sub":"党史"},{"id":"zz-32434","module":"zhengzhi","prompt":"1985年邓小平提出的关于时代主题的判断是：","options":["战争与革命是时代主题","竞争与合作是时代主题","改革与发展是时代主题","和平与发展是当代世界的两大问题"],"answer":3,"explanation":"1985年，邓小平指出和平与发展是当代世界的两大问题，为党和国家工作重心调整和对外开放提供了重要依据故选D。","__sub":"党史"},{"id":"zz-32435","module":"zhengzhi","prompt":"1985年6月邓小平宣布的中国人民解放军裁军数量是：","options":["50万","100万","150万","200万"],"answer":1,"explanation":"1985年6月，邓小平在中央军委扩大会议上宣布，中国裁减军队员额100万，体现了和平时期军队建设的战略转变故选B。","__sub":"党史"},{"id":"zz-32436","module":"zhengzhi","prompt":"上海合作组织成立的时间是：","options":["1996年4月","2001年10月","2001年6月","2002年6月"],"answer":2,"explanation":"2001年6月，上海合作组织成立大会在上海举行，这是首个在中国境内成立、以中国城市命名的区域性国际组织故选C。","__sub":"党史"},{"id":"zz-32437","module":"zhengzhi","prompt":"《反分裂国家法》通过的时间是：","options":["2005年3月","2000年3月","2004年3月","2008年3月"],"answer":0,"explanation":"2005年3月，十届全国人大三次会议通过《反分裂国家法》，以法律形式反对和遏制“台独”分裂势力故选A。","__sub":"党史"},{"id":"zz-32438","module":"zhengzhi","prompt":"我国全面取消农业税的时间是：","options":["2006年1月1日","2004年1月1日","2005年1月1日","2008年1月1日"],"answer":0,"explanation":"2006年1月1日，农业税条例正式废止，我国全面取消农业税，延续了2600多年的种田纳税历史宣告终结故选A。","__sub":"党史"},{"id":"zz-32439","module":"zhengzhi","prompt":"我国经济总量跃居世界第二位的时间是：","options":["2005年","2008年","2012年","2010年"],"answer":3,"explanation":"2010年，我国国内生产总值超过日本，成为世界第二大经济体；其余时间均不正确故选D。","__sub":"党史"},{"id":"zz-32440","module":"zhengzhi","prompt":"2008年北京奥运会是第几届夏季奥运会：","options":["第28届","第30届","第27届","第29届"],"answer":3,"explanation":"2008年8月，第29届夏季奥运会在北京举行，中国体育代表团获得51枚金牌，位居金牌榜第一；伦敦是第30届故选D。","__sub":"党史"},{"id":"zz-32441","module":"zhengzhi","prompt":"1979年1月1日全国人大常委会发表的推动两岸关系发展的文献是：","options":["《为促进祖国统一大业的完成而继续奋斗》","《反分裂国家法》","《台湾问题与新时代中国统一事业》白皮书","《告台湾同胞书》"],"answer":3,"explanation":"1979年1月1日，全国人大常委会发表《告台湾同胞书》，郑重宣布争取祖国和平统一的大政方针，两岸关系由此揭开新篇章故选D。","__sub":"党史"},{"id":"zz-32442","module":"zhengzhi","prompt":"首次“汪辜会谈”举行的时间和地点是：","options":["1993年4月，新加坡","1992年10月，香港","1994年4月，北京","1998年10月，上海"],"answer":0,"explanation":"1993年4月，海协会会长汪道涵与台湾海基会董事长辜振甫在新加坡举行会谈，这是两岸授权民间团体领导人的首次会谈故选A。","__sub":"党史"},{"id":"zz-32443","module":"zhengzhi","prompt":"党中央、国务院宣布开发开放浦东的时间是：","options":["1984年4月","1990年4月","1992年4月","1995年4月"],"answer":1,"explanation":"1990年4月，党中央、国务院作出开发开放上海浦东的重大决策，带动长三角和长江流域经济发展；1984年是开放14个沿海城市的时间故选B。","__sub":"党史"},{"id":"zz-32444","module":"zhengzhi","prompt":"1984年5月我国进一步开放的沿海港口城市数量是：","options":["4个","14个","10个","20个"],"answer":1,"explanation":"1984年5月，党中央、国务院决定进一步开放大连、天津、青岛、上海、广州等14个沿海港口城市，形成对外开放的前沿地带故选B。","__sub":"党史"},{"id":"zz-32445","module":"zhengzhi","prompt":"党的十七大概括的中国特色社会主义理论体系不包括：","options":["邓小平理论","“三个代表”重要思想","科学发展观","毛泽东思想"],"answer":3,"explanation":"2007年，党的十七大把邓小平理论、“三个代表”重要思想、科学发展观统称为中国特色社会主义理论体系；毛泽东思想是单独的理论体系，不在其中故选D。","__sub":"党史"},{"id":"zz-32446","module":"zhengzhi","prompt":"党在历史上通过的三个历史决议按时间先后排序正确的是：","options":["1981年决议、1945年决议、2021年决议","1945年决议、1981年决议、2021年决议","1945年决议、2021年决议、1981年决议","2021年决议、1981年决议、1945年决议"],"answer":1,"explanation":"三个历史决议分别是1945年六届七中全会《关于若干历史问题的决议》、1981年十一届六中全会《关于建国以来党的若干历史问题的决议》、2021年十九届六中全会《中共中央关于党的百年奋斗重大成就和历史经验的决议》故选B。","__sub":"党史"},{"id":"zz-32447","module":"zhengzhi","prompt":"党的十二大提出的到20世纪末经济发展的战略目标是：","options":["国内生产总值翻一番","工农业年总产值翻两番","经济总量翻三番","人均收入翻两番"],"answer":1,"explanation":"1982年，党的十二大提出从1981年到20世纪末，力争使全国工农业年总产值翻两番，人民生活达到小康水平；其余表述均不准确故选B。","__sub":"党史"},{"id":"zz-32448","module":"zhengzhi","prompt":"新中国成立以来颁布的现行宪法是：","options":["第一部宪法","第二部宪法","第四部宪法","第三部宪法"],"answer":2,"explanation":"我国先后颁布1954年、1975年、1978年、1982年四部宪法，现行宪法是1982年通过的第四部宪法，历经多次修正故选C。","__sub":"党史"},{"id":"zz-32449","module":"zhengzhi","prompt":"党的十三大对现代化建设战略部署的第三步目标是：","options":["到20世纪末人民生活达到小康水平","到21世纪中叶全面建成社会主义现代化强国","到2035年基本实现社会主义现代化","到21世纪中叶人均国民生产总值达到中等发达国家水平"],"answer":3,"explanation":"十三大“三步走”的第三步是到21世纪中叶，人均国民生产总值达到中等发达国家水平，基本实现现代化；“到2035年基本实现社会主义现代化”是党的十九大提出的两步走安排故选D。","__sub":"党史"},{"id":"zz-32450","module":"zhengzhi","prompt":"我国第一座自行设计建造的核电站是：","options":["大亚湾核电站","秦山核电站","田湾核电站","红沿河核电站"],"answer":1,"explanation":"1991年12月，我国自行设计建造的第一座核电站秦山核电站并网发电；大亚湾核电站利用外资建设，晚于秦山开工故选B。","__sub":"党史"},{"id":"zz-32451","module":"zhengzhi","prompt":"党的十四大提出的我国经济体制改革目标确立的依据之一是：","options":["计划经济是社会主义的本质特征","计划和市场都是经济手段","市场经济只存在于资本主义社会","社会主义不能发展商品经济"],"answer":1,"explanation":"1992年南方谈话指出计划和市场都是经济手段，不是社会主义与资本主义的本质区别，为十四大确立社会主义市场经济体制改革目标提供了理论依据故选B。","__sub":"党史"},{"id":"zz-32452","module":"zhengzhi","prompt":"党的十五大提出的面向21世纪党的建设总目标是：","options":["把党建设成为领导无产阶级革命的先锋队","把党建设成为用邓小平理论武装起来、全心全意为人民服务、思想上政治上组织上完全巩固、能够经受住各种风险、始终走在时代前列的马克思主义政党","把党建设成为无产阶级的、有社会主义觉悟的、革命化的部队","把党建设成为始终代表先进生产力发展要求的政党"],"answer":1,"explanation":"1997年，党的十五大提出面向新世纪党的建设总目标，强调用邓小平理论武装全党、经受住各种风险考验；其余选项均非十五大的表述故选B。","__sub":"党史"},{"id":"zz-32453","module":"zhengzhi","prompt":"1997年香港回归时我国对香港恢复行使主权所依据的文件是：","options":["开罗宣言","波茨坦公告","九二共识","中英联合声明"],"answer":3,"explanation":"1984年签署的中英联合声明确认中华人民共和国于1997年7月1日对香港恢复行使主权；开罗宣言、波茨坦公告虽涉及台湾问题，但不是香港回归的直接依据故选D。","__sub":"党史"},{"id":"zz-32454","module":"zhengzhi","prompt":"党的十六大提出的21世纪头20年的奋斗目标是：","options":["解决人民温饱问题","达到中等发达国家水平","建成社会主义现代化强国","全面建设小康社会"],"answer":3,"explanation":"2002年，党的十六大提出要在21世纪头20年集中力量全面建设小康社会；“解决温饱”是三步走第一步的目标故选D。","__sub":"党史"},{"id":"zz-32455","module":"zhengzhi","prompt":"2001年我国成功主办的重大多边外交活动是：","options":["万隆会议","日内瓦会议","不结盟运动首脑会议","亚太经合组织第九次领导人非正式会议"],"answer":3,"explanation":"2001年10月，亚太经合组织第九次领导人非正式会议在上海举行，这是我国首次主办的高级别多边外交活动；万隆、日内瓦会议均在20世纪50年代故选D。","__sub":"党史"},{"id":"zz-32456","module":"zhengzhi","prompt":"党的十五大在所有制理论上的新突破是：","options":["消灭一切非公有制经济","恢复单一的全民所有制","公有制实现形式可以而且应当多样化","私有制是社会主义经济的有益补充"],"answer":2,"explanation":"1997年，党的十五大提出公有制实现形式可以而且应当多样化，非公有制经济是社会主义市场经济的重要组成部分；其余选项均与史实相反或表述错误故选C。","__sub":"党史"},{"id":"zz-32457","module":"zhengzhi","prompt":"2005年连战率团访问大陆被称为：","options":["国共两党时隔60年的再次握手","两岸首次民间交流","两岸首次直接通航","两岸首次政治谈判"],"answer":0,"explanation":"2005年4月，中国国民党主席连战率团访问大陆，这是国共两党最高领导人时隔60年的再次握手，被称为“和平之旅”故选A。","__sub":"党史"},{"id":"zz-32458","module":"zhengzhi","prompt":"党的十四大形成的领导核心是：","options":["以邓小平为核心的第二代中央领导集体","以胡锦涛为总书记的党中央","以江泽民为核心的第三代中央领导集体","以习近平为核心的党中央"],"answer":2,"explanation":"党的十四大确立了以江泽民为核心的第三代中央领导集体的领导地位，提出用邓小平建设有中国特色社会主义理论武装全党故选C。","__sub":"党史"},{"id":"zz-32459","module":"zhengzhi","prompt":"中国特色社会主义进入新时代的重大论断是在：","options":["党的十八大","党的十七大","党的十九大","党的二十大"],"answer":2,"explanation":"2017年，党的十九大作出中国特色社会主义进入新时代的重大政治论断，这是我国发展新的历史方位；党的十八大提出的是全面建成小康社会的目标故选C。","__sub":"党史"},{"id":"zz-32460","module":"zhengzhi","prompt":"党的十七大对改革开放以来取得成绩的根本原因概括为：","options":["坚持了计划经济体制","坚持了以阶级斗争为纲","坚持了人民公社制度","开辟了中国特色社会主义道路，形成了中国特色社会主义理论体系"],"answer":3,"explanation":"党的十七大指出，改革开放以来我们取得一切成绩和进步的根本原因是开辟了中国特色社会主义道路、形成了中国特色社会主义理论体系；其余选项均是被否定的错误做法故选D。","__sub":"党史"},{"id":"zz-32461","module":"zhengzhi","prompt":"党的十八大提出的中国特色社会主义事业总体布局是：","options":["四位一体","六位一体","三个一体","五位一体"],"answer":3,"explanation":"2012年，党的十八大把生态文明建设纳入总体布局，形成经济建设、政治建设、文化建设、社会建设、生态文明建设“五位一体”总体布局；此前是“四位一体”故选D。","__sub":"党史"},{"id":"zz-32462","module":"zhengzhi","prompt":"党的十八届三中全会通过的决定是：","options":["《中共中央关于全面推进依法治国若干重大问题的决定》","《中共中央关于制定国民经济和社会发展第十四个五年规划的建议》","《中共中央关于全面深化改革若干重大问题的决定》","《中共中央关于进一步全面深化改革、推进中国式现代化的决定》"],"answer":2,"explanation":"2013年11月，十八届三中全会通过关于全面深化改革若干重大问题的决定，提出全面深化改革的总目标；全面推进依法治国的决定是十八届四中全会通过的故选C。","__sub":"党史"},{"id":"zz-32463","module":"zhengzhi","prompt":"全面深化改革总目标中的治理能力是指：","options":["制定国家制度的能力","修改宪法和法律的能力","扩大对外开放的能力","运用国家制度管理社会各方面事务的能力"],"answer":3,"explanation":"国家治理能力是运用国家制度管理国家和社会各方面事务的能力；制定制度属于治理体系范畴，修改宪法法律和对外开放均不是治理能力的定义故选D。","__sub":"党史"},{"id":"zz-32464","module":"zhengzhi","prompt":"党的十八届四中全会研究的主题是：","options":["全面从严治党","全面深化改革","全面建成小康社会","全面推进依法治国"],"answer":3,"explanation":"2014年10月，十八届四中全会通过关于全面推进依法治国若干重大问题的决定，这是党的历史上首次以全会形式专题研究法治建设；全面从严治党是十八届六中全会的主题故选D。","__sub":"党史"},{"id":"zz-32465","module":"zhengzhi","prompt":"“四个全面”战略布局首次提出是在：","options":["2012年11月","2013年11月","2015年10月","2014年12月"],"answer":3,"explanation":"2014年12月，习近平在江苏考察时首次把“四个全面”相提并论，即全面建成小康社会、全面深化改革、全面依法治国、全面从严治党故选D。","__sub":"党史"},{"id":"zz-32466","module":"zhengzhi","prompt":"实现中华民族伟大复兴的中国梦首次提出是在：","options":["2012年11月党的十八大报告中","2013年3月全国人大会议上","2012年11月参观《复兴之路》展览时","2017年10月党的十九大报告中"],"answer":2,"explanation":"2012年11月29日，习近平在参观《复兴之路》展览时首次提出实现中华民族伟大复兴的中国梦；十八大报告虽提出“两个一百年”目标，但“中国梦”概念是在参观展览时首次提出的故选C。","__sub":"党史"},{"id":"zz-32467","module":"zhengzhi","prompt":"中国梦的核心内涵是：","options":["自由、平等、公正、法治","创新、协调、绿色、开放、共享","和平、发展、合作、共赢","国家富强、民族振兴、人民幸福"],"answer":3,"explanation":"中国梦的核心内涵是实现中华民族伟大复兴，本质是国家富强、民族振兴、人民幸福；其余选项分别是社会主义核心价值观内容和新发展理念等故选D。","__sub":"党史"},{"id":"zz-32468","module":"zhengzhi","prompt":"中央政治局关于改进工作作风的八项规定出台的时间是：","options":["2013年1月1日","2012年11月15日","2012年12月4日","2014年1月1日"],"answer":2,"explanation":"2012年12月4日，中央政治局会议审议通过关于改进工作作风、密切联系群众的八项规定，成为新时代作风建设的标志性举措故选C。","__sub":"党史"},{"id":"zz-32469","module":"zhengzhi","prompt":"党的群众路线教育实践活动的主要任务是：","options":["集中解决形式主义、官僚主义、享乐主义和奢靡之风问题","集中解决腐败问题","集中解决生态环境问题","集中解决就业问题"],"answer":0,"explanation":"2013年起，党的群众路线教育实践活动把集中解决“四风”问题作为主要任务；“四风”指形式主义、官僚主义、享乐主义和奢靡之风故选A。","__sub":"党史"},{"id":"zz-32470","module":"zhengzhi","prompt":"新发展理念提出的时间是：","options":["2012年11月党的十八大上","2017年10月党的十九大上","2015年10月党的十八届五中全会上","2013年11月十八届三中全会上"],"answer":2,"explanation":"2015年10月，十八届五中全会提出创新、协调、绿色、开放、共享的新发展理念；其余会议均非新发展理念的提出场合故选C。","__sub":"党史"},{"id":"zz-32471","module":"zhengzhi","prompt":"党的十八届六中全会研究的主题是：","options":["全面深化改革","全面依法治国","全面从严治党","全面建成小康社会"],"answer":2,"explanation":"2016年10月，十八届六中全会通过关于新形势下党内政治生活的若干准则和党内监督条例，专题研究全面从严治党；全面深化改革是十八届三中全会的主题故选C。","__sub":"党史"},{"id":"zz-32472","module":"zhengzhi","prompt":"党的十九大召开的时间是：","options":["2017年9月","2016年10月","2018年10月","2017年10月"],"answer":3,"explanation":"2017年10月18日至24日，党的十九大在北京召开，作出中国特色社会主义进入新时代的重大政治论断故选D。","__sub":"党史"},{"id":"zz-32473","module":"zhengzhi","prompt":"党的十九大把什么思想写入党章并确立为党的指导思想：","options":["科学发展观","“三个代表”重要思想","习近平新时代中国特色社会主义思想","邓小平理论"],"answer":2,"explanation":"2017年10月，党的十九大把习近平新时代中国特色社会主义思想写入党章，确立为党必须长期坚持的指导思想；科学发展观是十八大确立的指导思想故选C。","__sub":"党史"},{"id":"zz-32474","module":"zhengzhi","prompt":"党的十九大指出的我国社会主要矛盾是：","options":["人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾","人民日益增长的物质文化需要同落后的社会生产之间的矛盾","人民对于建立先进的工业国的要求同落后的农业国的现实之间的矛盾","无产阶级和资产阶级之间的矛盾"],"answer":0,"explanation":"党的十九大指出，我国社会主要矛盾已经转化为人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾；“物质文化需要同落后的社会生产”是1981年十一届六中全会的表述故选A。","__sub":"党史"},{"id":"zz-32475","module":"zhengzhi","prompt":"党的十九大提出的从2020年到本世纪中叶的两个阶段安排是：","options":["2020年到2035年全面建成小康社会，2035年到本世纪中叶基本实现现代化","2020年到2030年基本实现现代化，2030年到本世纪中叶建成强国","2020年到2035年基本实现社会主义现代化，2035年到本世纪中叶建成社会主义现代化强国","2020年到2040年基本实现现代化，2040年到本世纪中叶建成强国"],"answer":2,"explanation":"党的十九大提出，从2020年到2035年基本实现社会主义现代化，从2035年到本世纪中叶把我国建成富强民主文明和谐美丽的社会主义现代化强国；全面建成小康社会是2020年即已完成的目标故选C。","__sub":"党史"},{"id":"zz-32476","module":"zhengzhi","prompt":"我国脱贫攻坚战取得全面胜利的时间是：","options":["2020年10月","2020年12月","2021年2月","2021年7月"],"answer":2,"explanation":"2021年2月25日，全国脱贫攻坚总结表彰大会举行，习近平庄严宣告我国脱贫攻坚战取得全面胜利；2021年7月是宣布全面建成小康社会的时间故选C。","__sub":"党史"},{"id":"zz-32477","module":"zhengzhi","prompt":"脱贫攻坚战以来我国脱贫的人口规模是：","options":["9899万农村贫困人口全部脱贫","832万农村贫困人口全部脱贫","5000万农村贫困人口全部脱贫","1.2亿农村贫困人口全部脱贫"],"answer":0,"explanation":"脱贫攻坚战使9899万农村贫困人口全部脱贫、832个贫困县全部摘帽；832是贫困县数量，易与脱贫人口数混淆故选A。","__sub":"党史"},{"id":"zz-32478","module":"zhengzhi","prompt":"宣布全面建成小康社会的时间是：","options":["2021年7月1日","2021年2月25日","2020年10月1日","2021年10月1日"],"answer":0,"explanation":"2021年7月1日，习近平在庆祝中国共产党成立100周年大会上庄严宣告，我们实现了第一个百年奋斗目标，在中华大地上全面建成了小康社会故选A。","__sub":"党史"},{"id":"zz-32479","module":"zhengzhi","prompt":"从“建设小康社会”到“建成小康社会”的一字之变首次出现在：","options":["党的十八大","党的十六大","党的十七大","党的十九大"],"answer":0,"explanation":"2012年，党的十八大把“全面建设小康社会”改为“全面建成小康社会”，一字之变体现了奋斗目标的阶段性跃升；十六大提出的是“全面建设小康社会”故选A。","__sub":"党史"},{"id":"zz-32480","module":"zhengzhi","prompt":"“一带一路”倡议中“丝绸之路经济带”首次提出是在：","options":["2013年10月访问印度尼西亚时","2015年3月发布愿景文件时","2013年9月访问哈萨克斯坦时","2017年5月高峰论坛上"],"answer":2,"explanation":"2013年9月，习近平在哈萨克斯坦提出共建丝绸之路经济带；同年10月在印度尼西亚提出共建21世纪海上丝绸之路，二者合称“一带一路”故选C。","__sub":"党史"},{"id":"zz-32481","module":"zhengzhi","prompt":"“21世纪海上丝绸之路”首次提出是在：","options":["2013年10月访问印度尼西亚时","2013年9月访问哈萨克斯坦时","2014年11月访问新西兰时","2016年9月出席G20峰会时"],"answer":0,"explanation":"2013年10月，习近平在印度尼西亚国会演讲中提出共建21世纪海上丝绸之路；哈萨克斯坦之行提出的是丝绸之路经济带故选A。","__sub":"党史"},{"id":"zz-32482","module":"zhengzhi","prompt":"人类命运共同体理念首次提出是在：","options":["2015年9月在联合国大会上","2013年3月在莫斯科国际关系学院演讲时","2017年1月在日内瓦演讲时","2012年11月参观《复兴之路》展览时"],"answer":1,"explanation":"2013年3月，习近平在莫斯科国际关系学院演讲中首次提出人类命运共同体理念；2017年日内瓦演讲是系统阐述“构建人类命运共同体”的中国方案故选B。","__sub":"党史"},{"id":"zz-32483","module":"zhengzhi","prompt":"“不忘初心、牢记使命”主题教育开展的时间是：","options":["2017年","2019年","2018年","2021年"],"answer":1,"explanation":"2019年5月起，“不忘初心、牢记使命”主题教育在全党开展；2021年开展的是党史学习教育故选B。","__sub":"党史"},{"id":"zz-32484","module":"zhengzhi","prompt":"党史学习教育动员大会召开的时间是：","options":["2019年5月","2020年2月","2021年2月","2022年2月"],"answer":2,"explanation":"2021年2月，党史学习教育动员大会在北京召开，习近平号召全党学史明理、学史增信、学史崇德、学史力行故选C。","__sub":"党史"},{"id":"zz-32485","module":"zhengzhi","prompt":"党的十九届六中全会通过的历史决议是：","options":["《中共中央关于党的百年奋斗重大成就和历史经验的决议》","《关于建国以来党的若干历史问题的决议》","《关于若干历史问题的决议》","《中共中央关于全面深化改革若干重大问题的决定》"],"answer":0,"explanation":"2021年11月，十九届六中全会通过党的历史上第三个历史决议《中共中央关于党的百年奋斗重大成就和历史经验的决议》；1981年决议是《关于建国以来党的若干历史问题的决议》故选A。","__sub":"党史"},{"id":"zz-32486","module":"zhengzhi","prompt":"党的十九届六中全会提出的“两个确立”是指：","options":["确立社会主义市场经济体制，确立现代化建设三步走战略","确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位","确立党的基本路线，确立依法治国基本方略","确立新发展理念，确立新发展格局"],"answer":1,"explanation":"十九届六中全会提出“两个确立”，即确立习近平同志党中央的核心、全党的核心地位，确立习近平新时代中国特色社会主义思想的指导地位；其余选项均非“两个确立”的内容故选B。","__sub":"党史"},{"id":"zz-32487","module":"zhengzhi","prompt":"党的二十大召开的时间是：","options":["2022年8月","2021年10月","2022年10月","2023年10月"],"answer":2,"explanation":"2022年10月16日至22日，党的二十大在北京召开，这是在全党全国各族人民迈上全面建设社会主义现代化国家新征程的关键时刻召开的重要大会故选C。","__sub":"党史"},{"id":"zz-32488","module":"zhengzhi","prompt":"党的二十大提出的党的中心任务是：","options":["团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴","全面建成小康社会","实现第一个百年奋斗目标","建设社会主义市场经济体制"],"answer":0,"explanation":"党的二十大提出，从现在起党的中心任务是团结带领全国各族人民全面建成社会主义现代化强国、实现第二个百年奋斗目标，以中国式现代化全面推进中华民族伟大复兴；全面建成小康社会是2021年已宣布完成的目标故选A。","__sub":"党史"},{"id":"zz-32489","module":"zhengzhi","prompt":"党的二十大提出的“三个务必”是：","options":["务必解放思想、实事求是，务必独立自主、自力更生，务必改革开放、开拓创新","务必理论联系实际，务必密切联系群众，务必批评与自我批评","务必勤俭节约，务必清正廉洁，务实担当作为","务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争"],"answer":3,"explanation":"党的二十大提出“三个务必”，即务必不忘初心、牢记使命，务必谦虚谨慎、艰苦奋斗，务必敢于斗争、善于斗争；理论联系实际等是党的三大优良作风故选D。","__sub":"党史"},{"id":"zz-32490","module":"zhengzhi","prompt":"党的二十届三中全会通过的决定是：","options":["《中共中央关于进一步全面深化改革、推进中国式现代化的决定》","《中共中央关于全面深化改革若干重大问题的决定》","《中共中央关于全面推进依法治国若干重大问题的决定》","《中共中央关于制定国民经济和社会发展第十四个五年规划的建议》"],"answer":0,"explanation":"2024年7月，二十届三中全会通过关于进一步全面深化改革、推进中国式现代化的决定；2013年十八届三中全会通过的是关于全面深化改革若干重大问题的决定故选A。","__sub":"党史"},{"id":"zz-32491","module":"zhengzhi","prompt":"党的二十届三中全会提出的到2035年的改革目标是：","options":["全面建成小康社会","建成社会主义现代化强国","实现国内生产总值翻两番","全面建成高水平社会主义市场经济体制"],"answer":3,"explanation":"二十届三中全会提出，到2035年全面建成高水平社会主义市场经济体制，中国特色社会主义制度更加完善；建成社会主义现代化强国是本世纪中叶的目标故选D。","__sub":"党史"},{"id":"zz-32492","module":"zhengzhi","prompt":"全面从严治党首次纳入“四个全面”战略布局的时间是：","options":["2012年11月","2014年12月","2016年10月","2017年10月"],"answer":1,"explanation":"2014年12月，习近平在江苏考察时将“从严治党”首次表述为“全面从严治党”，并使其成为“四个全面”战略布局的组成部分故选B。","__sub":"党史"},{"id":"zz-32493","module":"zhengzhi","prompt":"2018年宪法修正案把什么思想写入宪法：","options":["习近平新时代中国特色社会主义思想","科学发展观","“三个代表”重要思想","邓小平理论"],"answer":0,"explanation":"2018年3月，十三届全国人大一次会议通过宪法修正案，把习近平新时代中国特色社会主义思想写入宪法，并设立国家监察委员会等故选A。","__sub":"党史"},{"id":"zz-32494","module":"zhengzhi","prompt":"党的十九大首次提出的国家战略是：","options":["西部大开发战略","科教兴国战略","乡村振兴战略","可持续发展战略"],"answer":2,"explanation":"2017年，党的十九大首次提出实施乡村振兴战略，按照产业兴旺、生态宜居等总要求推进农业农村现代化；西部大开发、科教兴国分别是2000年和1995年提出的故选C。","__sub":"党史"},{"id":"zz-32495","module":"zhengzhi","prompt":"《粤港澳大湾区发展规划纲要》公布的时间是：","options":["2017年7月","2019年2月","2018年2月","2020年2月"],"answer":1,"explanation":"2019年2月，中共中央、国务院印发《粤港澳大湾区发展规划纲要》，指导大湾区建设；2017年7月签署的是框架协议故选B。","__sub":"党史"},{"id":"zz-32496","module":"zhengzhi","prompt":"我国设立的首个自由贸易试验区位于：","options":["广东","上海","天津","海南"],"answer":1,"explanation":"2013年9月，中国（上海）自由贸易试验区挂牌成立，是我国首个自由贸易试验区；广东、天津自贸区2015年设立，海南自贸港2020年启动建设故选B。","__sub":"党史"},{"id":"zz-32497","module":"zhengzhi","prompt":"中国国际进口博览会首次举办的时间和地点是：","options":["2017年5月，北京","2018年11月，广州","2018年11月，上海","2019年11月，上海"],"answer":2,"explanation":"2018年11月，首届中国国际进口博览会在上海举行，这是世界上首个以进口为主题的国家级展会故选C。","__sub":"党史"},{"id":"zz-32498","module":"zhengzhi","prompt":"我国提出“双碳”目标的时间是：","options":["2019年9月","2021年9月","2020年9月","2020年12月"],"answer":2,"explanation":"2020年9月，习近平在第七十五届联合国大会上宣布，中国二氧化碳排放力争于2030年前达到峰值，努力争取2060年前实现碳中和故选C。","__sub":"党史"},{"id":"zz-32499","module":"zhengzhi","prompt":"全过程人民民主重大理念首次提出是在：","options":["2017年10月党的十九大报告中","2021年7月建党百年讲话中","2019年11月在上海虹桥街道考察时","2022年10月党的二十大报告中"],"answer":2,"explanation":"2019年11月，习近平在上海虹桥街道考察时首次提出“人民民主是一种全过程的民主”；党的十九大报告提出的是健全人民当家作主制度体系故选C。","__sub":"党史"},{"id":"zz-32500","module":"zhengzhi","prompt":"新时代党的强军目标是：","options":["听党指挥、能打胜仗、作风优良","政治过硬、本领高强、作风优良","对党忠诚、英勇善战、纪律严明","忠诚于党、热爱人民、报效国家"],"answer":0,"explanation":"新时代强军目标是建设一支听党指挥、能打胜仗、作风优良的人民军队；其余选项均为拼凑表述，不是强军目标的规范提法故选A。","__sub":"党史"},{"id":"zz-32501","module":"zhengzhi","prompt":"实现建军一百年奋斗目标的时间节点是：","options":["2035年","2027年","2050年","2025年"],"answer":1,"explanation":"党的十九大提出力争到2035年基本实现国防和军队现代化，到本世纪中叶建成世界一流军队；2027年是实现建军一百年奋斗目标的时间节点故选B。","__sub":"党史"},{"id":"zz-32502","module":"zhengzhi","prompt":"跳出治乱兴衰历史周期率的第二个答案是：","options":["人民监督","依法治国","改革开放","自我革命"],"answer":3,"explanation":"经过百年奋斗特别是党的十八大以来新的实践，党给出了跳出历史周期率的第二个答案，这就是自我革命；人民监督是毛泽东在窑洞对中给出的第一个答案故选D。","__sub":"党史"},{"id":"zz-32503","module":"zhengzhi","prompt":"向毛泽东提出历史周期率之问的人士是：","options":["张澜","黄炎培","沈钧儒","章士钊"],"answer":1,"explanation":"1945年7月，民主人士黄炎培访问延安，向毛泽东提出如何跳出治乱兴衰历史周期率之问，毛泽东答以让人民来监督政府；其余选项均为同时期民主人士，不符合史实故选B。","__sub":"党史"},{"id":"zz-32504","module":"zhengzhi","prompt":"党的二十届二中全会研究的主题是：","options":["全面深化改革总体设计","党和国家机构改革","制定“十四五”规划建议","全面推进乡村振兴"],"answer":1,"explanation":"2023年2月，二十届二中全会审议通过党和国家机构改革方案，研究部署深化机构改革工作；制定“十四五”规划建议是十九届五中全会的议题故选B。","__sub":"党史"},{"id":"zz-32505","module":"zhengzhi","prompt":"党的十九大提出的实施乡村振兴战略的总要求是：","options":["产业兴旺、生态宜居、乡风文明、治理有效、生活富裕","生产发展、生活宽裕、乡风文明、村容整洁、管理民主","农业强、农村美、农民富","产业振兴、人才振兴、文化振兴、生态振兴、组织振兴"],"answer":0,"explanation":"党的十九大提出的乡村振兴总要求是产业兴旺、生态宜居、乡风文明、治理有效、生活富裕；“生产发展、生活宽裕”等是2005年社会主义新农村建设的二十字要求故选A。","__sub":"党史"},{"id":"zz-32506","module":"zhengzhi","prompt":"新时代我国经济已由高速增长阶段转向：","options":["高质量发展阶段","中高速增长阶段","中低速增长阶段","低速增长阶段"],"answer":0,"explanation":"党的十九大指出，我国经济已由高速增长阶段转向高质量发展阶段，正处在转变发展方式、优化经济结构、转换增长动力的攻关期故选A。","__sub":"党史"},{"id":"zz-32507","module":"zhengzhi","prompt":"供给侧结构性改革的主攻方向是：","options":["扩大内需","提高供给质量","增加投资","稳定出口"],"answer":1,"explanation":"2015年，党中央提出推进供给侧结构性改革，主攻方向是提高供给质量，减少无效和低端供给，扩大有效和中高端供给；扩大内需是宏观政策的着力点而非主攻方向故选B。","__sub":"党史"},{"id":"zz-32508","module":"zhengzhi","prompt":"党的十九大提出的现代化经济体系建设的战略支撑是：","options":["创新","协调","绿色","共享"],"answer":0,"explanation":"党的十九大强调创新是引领发展的第一动力，是建设现代化经济体系的战略支撑；协调、绿色、共享是新发展理念的其他内容故选A。","__sub":"党史"},{"id":"zz-32509","module":"zhengzhi","prompt":"党的二十大报告指出的中国式现代化的本质要求之一是：","options":["实行多党轮流执政","坚持中国共产党领导","照搬西方政治制度模式","放弃公有制主体地位"],"answer":1,"explanation":"党的二十大报告概括了中国式现代化的本质要求，首要的是坚持中国共产党领导；中国式现代化不照搬西方政治制度模式，坚持公有制主体地位故选B。","__sub":"党史"},{"id":"zz-32510","module":"zhengzhi","prompt":"新时代十年伟大变革中，我国建成的世界最大的社会保障体系覆盖人数约为：","options":["三亿多人","十亿多人","五亿多人","八亿多人"],"answer":1,"explanation":"党的二十大报告指出，我国建成世界上规模最大的教育体系、社会保障体系、医疗卫生体系，基本养老保险覆盖十亿多人；其余数字均不符合实际故选B。","__sub":"党史"},{"id":"zz-32511","module":"zhengzhi","prompt":"中共一大通过的第一个党纲确定党的名称是：","options":["中华革命党","中国共产党","中国社会党","共产主义同盟"],"answer":1,"explanation":"1921年中共一大通过的第一个党纲明确规定，党的名称为中国共产党，奋斗目标是以无产阶级革命军队推翻资产阶级政权。故选B。","__sub":"党史"},{"id":"zz-32512","module":"zhengzhi","prompt":"中共一大最后一天会议转移到的地点是：","options":["广州农讲所","上海石库门","江西井冈山","浙江嘉兴南湖"],"answer":3,"explanation":"中共一大在上海召开期间因遭法租界巡捕搜查，最后一天会议转移到浙江嘉兴南湖的一条游船上举行，完成了大会全部议程。故选D。","__sub":"党史"},{"id":"zz-32513","module":"zhengzhi","prompt":"通过党的历史上第一部党章的大会是：","options":["中共四大","中共一大","中共三大","中共二大"],"answer":3,"explanation":"1922年7月召开的中共二大通过了《中国共产党章程》，这是党的历史上第一部党章，对党的组织建设作出系统规定。故选D。","__sub":"党史"},{"id":"zz-32514","module":"zhengzhi","prompt":"第一次明确提出反帝反封建的民主革命纲领的大会是：","options":["中共二大","中共一大","八七会议","中共三大"],"answer":0,"explanation":"中共二大在中国近代史上第一次明确提出反帝反封建的民主革命纲领，分清了民主革命的对象和动力问题。故选A。","__sub":"党史"},{"id":"zz-32515","module":"zhengzhi","prompt":"第一次国共合作的政治基础是：","options":["社会主义纲领","共产主义纲领","三民主义的旧解释","新三民主义"],"answer":3,"explanation":"以1924年国民党一大通过的宣言为标志，重新解释的三民主义即新三民主义成为第一次国共合作的政治基础。故选D。","__sub":"党史"},{"id":"zz-32516","module":"zhengzhi","prompt":"打响武装反抗国民党反动派第一枪的起义是：","options":["广州起义","秋收起义","南昌起义","湘南起义"],"answer":2,"explanation":"1927年8月1日的南昌起义打响了武装反抗国民党反动派的第一枪，标志着中国共产党独立领导革命战争和创建人民军队的开始。故选C。","__sub":"党史"},{"id":"zz-32517","module":"zhengzhi","prompt":"南昌起义爆发的时间是：","options":["1927年9月9日","1926年8月1日","1927年8月1日","1928年8月1日"],"answer":2,"explanation":"1927年8月1日，周恩来、贺龙、叶挺、朱德、刘伯承等领导发动南昌起义，8月1日后来成为中国人民解放军建军节。故选C。","__sub":"党史"},{"id":"zz-32518","module":"zhengzhi","prompt":"八七会议确定的总方针是：","options":["进行社会主义改造","建立抗日民族统一战线","开展农村土地改革","土地革命和武装反抗国民党反动派"],"answer":3,"explanation":"1927年8月7日中共中央在汉口召开八七会议，确定了土地革命和武装反抗国民党反动派的总方针，使党在革命危急关头明确了方向。故选D。","__sub":"党史"},{"id":"zz-32519","module":"zhengzhi","prompt":"党创建的第一个农村革命根据地是：","options":["井冈山革命根据地","中央革命根据地","鄂豫皖革命根据地","陕甘宁革命根据地"],"answer":0,"explanation":"1927年10月，毛泽东率领秋收起义部队到达井冈山，创建了中国第一个农村革命根据地，开辟了农村包围城市的道路。故选A。","__sub":"党史"},{"id":"zz-32520","module":"zhengzhi","prompt":"井冈山会师的时间是：","options":["1930年6月","1927年10月","1929年1月","1928年4月"],"answer":3,"explanation":"1928年4月，朱德、陈毅率领南昌起义余部与毛泽东领导的部队在井冈山会师，成立工农革命军第四军，壮大了革命力量。故选D。","__sub":"党史"},{"id":"zz-32521","module":"zhengzhi","prompt":"三湾改编发生的时间是：","options":["1929年12月","1927年8月","1928年4月","1927年9月"],"answer":3,"explanation":"1927年9月，毛泽东在江西永新县三湾村领导改编部队，将党支部建在连上，确立了党对军队的组织领导。故选D。","__sub":"党史"},{"id":"zz-32522","module":"zhengzhi","prompt":"遵义会议召开的时间是：","options":["1936年12月","1934年10月","1935年10月","1935年1月"],"answer":3,"explanation":"1935年1月，中共中央在贵州遵义召开政治局扩大会议，集中解决当时具有决定意义的军事问题和组织问题。故选D。","__sub":"党史"},{"id":"zz-32523","module":"zhengzhi","prompt":"遵义会议在党的历史上的地位是：","options":["党的历史上第一次整风运动的开端","党的历史上一个生死攸关的转折点","党创建人民军队的开端","党走向成熟的唯一标志"],"answer":1,"explanation":"遵义会议事实上确立了毛泽东同志在党中央和红军的领导地位，在最危急关头挽救了党、挽救了红军、挽救了中国革命，是党的历史上一个生死攸关的转折点。故选B。","__sub":"党史"},{"id":"zz-32524","module":"zhengzhi","prompt":"确定建立抗日民族统一战线方针的会议是：","options":["遵义会议","洛川会议","瓦窑堡会议","六届六中全会"],"answer":2,"explanation":"1935年12月召开的瓦窑堡会议确定了建立抗日民族统一战线的方针，为全党迎接全民族抗战作了政治准备。故选C。","__sub":"党史"},{"id":"zz-32525","module":"zhengzhi","prompt":"通过《抗日救国十大纲领》的会议是：","options":["洛川会议","瓦窑堡会议","八七会议","古田会议"],"answer":0,"explanation":"1937年8月，中共中央在陕北洛川召开政治局扩大会议，通过《抗日救国十大纲领》，提出了全面抗战路线。故选A。","__sub":"党史"},{"id":"zz-32526","module":"zhengzhi","prompt":"延安整风运动开始的时间是：","options":["1945年","1940年","1941年","1942年"],"answer":3,"explanation":"1942年2月，毛泽东作《整顿党的作风》《反对党八股》等报告，延安整风运动在全党普遍展开。故选D。","__sub":"党史"},{"id":"zz-32527","module":"zhengzhi","prompt":"中共七大召开的时间是：","options":["1945年9月","1943年4月","1945年4月","1947年4月"],"answer":2,"explanation":"1945年4月至6月，中共七大在延安召开，总结了党领导中国革命的经验，制定了夺取抗战胜利的政治路线。故选C。","__sub":"党史"},{"id":"zz-32528","module":"zhengzhi","prompt":"中共七大确立为党的指导思想并写入党章的是：","options":["新民主主义理论","毛泽东思想","人民民主专政理论","马克思主义中国化命题"],"answer":1,"explanation":"中共七大把毛泽东思想确立为党的指导思想并写入党章，使全党在思想上政治上组织上达到空前的统一和团结。故选B。","__sub":"党史"},{"id":"zz-32529","module":"zhengzhi","prompt":"1949年3月在西柏坡召开的会议是：","options":["中共七届三中全会","中共六届六中全会","中共八大","中共七届二中全会"],"answer":3,"explanation":"1949年3月，中共七届二中全会在河北西柏坡召开，规定了党在全国胜利后在政治、经济、外交方面应当采取的基本政策。故选D。","__sub":"党史"},{"id":"zz-32530","module":"zhengzhi","prompt":"第一个五年计划开始实施的时间是：","options":["1956年","1950年","1952年","1953年"],"answer":3,"explanation":"1953年，我国开始实施第一个五年计划，集中主要力量发展重工业，为社会主义工业化奠定初步基础。故选D。","__sub":"党史"},{"id":"zz-32531","module":"zhengzhi","prompt":"新中国第一部宪法通过的时间是：","options":["1952年","1949年","1954年","1956年"],"answer":2,"explanation":"1954年9月，第一届全国人民代表大会第一次会议通过《中华人民共和国宪法》，这是新中国第一部社会主义类型的宪法。故选C。","__sub":"党史"},{"id":"zz-32532","module":"zhengzhi","prompt":"中共八大提出的经济建设方针是：","options":["既反保守又反冒进，在综合平衡中稳步前进","多快好省地建设社会主义","以钢为纲、全面跃进","调整巩固充实提高"],"answer":0,"explanation":"中共八大坚持既反保守又反冒进、在综合平衡中稳步前进的经济建设方针，是党对社会主义建设道路探索的重要成果。故选A。","__sub":"党史"},{"id":"zz-32533","module":"zhengzhi","prompt":"我国第一颗原子弹爆炸成功的时间是：","options":["1962年10月16日","1964年10月16日","1964年5月1日","1967年10月16日"],"answer":1,"explanation":"1964年10月16日，我国第一颗原子弹在新疆罗布泊爆炸成功，打破了超级大国的核垄断，提高了我国的国际地位。故选B。","__sub":"党史"},{"id":"zz-32534","module":"zhengzhi","prompt":"我国第一颗人造地球卫星是：","options":["“风云一号”","“嫦娥一号”","“神舟一号”","“东方红一号”"],"answer":3,"explanation":"1970年4月24日，我国成功发射第一颗人造地球卫星“东方红一号”，成为世界上第五个独立发射卫星的国家。故选D。","__sub":"党史"},{"id":"zz-32535","module":"zhengzhi","prompt":"中华人民共和国恢复在联合国合法席位的时间是：","options":["1973年","1969年","1970年","1971年"],"answer":3,"explanation":"1971年10月，第26届联合国大会通过决议，恢复中华人民共和国在联合国的一切合法权利，我国外交取得重大胜利。故选D。","__sub":"党史"},{"id":"zz-32536","module":"zhengzhi","prompt":"中美双方在上海发表《联合公报》的时间是：","options":["1972年9月","1971年7月","1972年2月","1979年1月"],"answer":2,"explanation":"1972年2月，美国总统尼克松访华，中美双方在上海发表《联合公报》，标志着中美关系开始走向正常化。故选C。","__sub":"党史"},{"id":"zz-32537","module":"zhengzhi","prompt":"真理标准问题大讨论针对的错误观点是：","options":["“以阶级斗争为纲”","“两个凡是”","“大跃进”思想","“无产阶级专政下继续革命”理论"],"answer":1,"explanation":"1978年开展的真理标准问题大讨论，批判了“两个凡是”的错误方针，为党的十一届三中全会召开作了思想准备。故选B。","__sub":"党史"},{"id":"zz-32538","module":"zhengzhi","prompt":"作出把党和国家工作中心转移到经济建设上来、实行改革开放历史性决策的会议是：","options":["党的十三大","党的十一届六中全会","党的十二大","党的十一届三中全会"],"answer":3,"explanation":"1978年12月召开的党的十一届三中全会，作出把党和国家工作中心转移到经济建设上来、实行改革开放的历史性决策，实现了新中国成立以来党的历史上具有深远意义的伟大转折。故选D。","__sub":"党史"},{"id":"zz-32539","module":"zhengzhi","prompt":"我国最早设立的四个经济特区是：","options":["深圳、广州、汕头、福州","深圳、珠海、海口、厦门","深圳、珠海、汕头、厦门","上海、深圳、珠海、厦门"],"answer":2,"explanation":"1980年，中央决定设立深圳、珠海、汕头、厦门四个经济特区，作为对外开放的窗口和试验田。故选C。","__sub":"党史"},{"id":"zz-32540","module":"zhengzhi","prompt":"家庭联产承包责任制率先实行的村庄是：","options":["河南临颍南街村","江苏江阴华西村","山西昔阳大寨村","安徽凤阳小岗村"],"answer":3,"explanation":"1978年冬，安徽凤阳小岗村农民率先实行包产到户，拉开了农村改革的序幕，家庭联产承包制随后在全国推广。故选D。","__sub":"党史"},{"id":"zz-32541","module":"zhengzhi","prompt":"香港特别行政区的首任行政长官是：","options":["何厚铧","董建华","梁振英","曾荫权"],"answer":1,"explanation":"1997年7月1日香港回归祖国后，董建华出任香港特别行政区第一任行政长官，践行了“一国两制”、“港人治港”、高度自治的方针。故选B。","__sub":"党史"},{"id":"zz-32542","module":"zhengzhi","prompt":"澳门特别行政区的首任行政长官是：","options":["崔世安","董建华","何厚铧","贺一诚"],"answer":2,"explanation":"1999年12月20日澳门回归祖国后，何厚铧出任澳门特别行政区第一任行政长官，“一国两制”在澳门的成功实践得到广泛认同。故选C。","__sub":"党史"},{"id":"zz-32543","module":"zhengzhi","prompt":"中国加入世界贸易组织的时间是：","options":["1999年12月","2001年12月","2001年7月","2002年12月"],"answer":1,"explanation":"2001年12月，中国正式加入世界贸易组织，标志着对外开放进入新的阶段，为经济发展赢得了更广阔的空间。故选B。","__sub":"党史"},{"id":"zz-32544","module":"zhengzhi","prompt":"宣告我国全面建成小康社会的时间是：","options":["2020年12月31日","2021年7月1日","2021年10月1日","2022年10月16日"],"answer":1,"explanation":"2021年7月1日，习近平总书记在庆祝中国共产党成立100周年大会上庄严宣告，我国全面建成了小康社会。故选B。","__sub":"党史"},{"id":"zz-32545","module":"zhengzhi","prompt":"《共产党宣言》中文全译本的首位翻译者是：","options":["瞿秋白","李大钊","陈独秀","陈望道"],"answer":3,"explanation":"1920年8月，陈望道翻译的《共产党宣言》中文全译本出版，对马克思主义在中国的传播起了重要作用。故选D。","__sub":"党史"},{"id":"zz-32546","module":"zhengzhi","prompt":"中共一大选举产生的中央局书记是：","options":["毛泽东","李大钊","陈独秀","董必武"],"answer":2,"explanation":"中共一大选举产生中央局，陈独秀任书记，负责党中央的领导工作。故选C。","__sub":"党史"},{"id":"zz-32547","module":"zhengzhi","prompt":"红军长征开始的时间是：","options":["1936年10月","1933年10月","1935年1月","1934年10月"],"answer":3,"explanation":"1934年10月，中共中央和中央红军从江西瑞金等地出发，开始战略转移，长征由此开始。故选D。","__sub":"党史"},{"id":"zz-32548","module":"zhengzhi","prompt":"西安事变和平解决的时间是：","options":["1937年7月","1935年12月","1936年6月","1936年12月"],"answer":3,"explanation":"1936年12月，西安事变和平解决，成为时局转换的枢纽，十年内战的局面由此结束，国内和平基本实现。故选D。","__sub":"党史"},{"id":"zz-32549","module":"zhengzhi","prompt":"平型关大捷的历史意义是：","options":["标志着战略反攻的开始","抗战以来规模最大的会战","彻底粉碎日军全面进攻","全民族抗战以来中国军队取得的第一个重大胜利"],"answer":3,"explanation":"1937年9月，八路军第一一五师在平型关伏击日军取得大捷，打破了日军“不可战胜”的神话，是全民族抗战以来中国军队取得的第一个重大胜利。故选D。","__sub":"党史"},{"id":"zz-32550","module":"zhengzhi","prompt":"百团大战的指挥者是：","options":["林彪","彭德怀","刘伯承","贺龙"],"answer":1,"explanation":"1940年下半年，在彭德怀指挥下，八路军在华北发动百团大战，沉重打击了日军的“囚笼政策”，振奋了全国军民的抗战信心。故选B。","__sub":"党史"},{"id":"zz-32551","module":"zhengzhi","prompt":"邓小平理论初步回答和解决的时代课题是：","options":["如何实现共产主义","如何进行新民主主义革命","如何进行社会主义改造","在中国这样经济文化比较落后的国家如何建设社会主义、如何巩固和发展社会主义"],"answer":3,"explanation":"邓小平理论围绕在中国这样经济文化比较落后的国家如何建设社会主义、如何巩固和发展社会主义的时代课题，形成了系统的科学理论。故选D。","__sub":"中特"},{"id":"zz-32552","module":"zhengzhi","prompt":"社会主义的本质是：","options":["解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕","公有制为主体，多种所有制经济共同发展","计划经济为主，市场调节为辅","按劳分配为主体，多种分配方式并存"],"answer":0,"explanation":"1992年南方谈话中，邓小平把社会主义本质概括为解放生产力，发展生产力，消灭剥削，消除两极分化，最终达到共同富裕。故选A。","__sub":"中特"},{"id":"zz-32553","module":"zhengzhi","prompt":"对社会主义本质作出科学概括的谈话是：","options":["1992年南方谈话","1978年中央工作会议讲话","1984年视察深圳讲话","1989年接见首都戒严部队军以上干部讲话"],"answer":0,"explanation":"1992年初，邓小平在南方谈话中对社会主义本质作出科学概括，把对社会主义的认识提高到新的科学水平。故选A。","__sub":"中特"},{"id":"zz-32554","module":"zhengzhi","prompt":"社会主义的根本任务是：","options":["建设精神文明","巩固人民民主专政","实现共同富裕","解放和发展生产力"],"answer":3,"explanation":"社会主义的根本任务是解放和发展生产力，这是由社会主义本质和初级阶段的基本国情决定的。故选D。","__sub":"中特"},{"id":"zz-32555","module":"zhengzhi","prompt":"系统阐述社会主义初级阶段理论的会议是：","options":["中共十四大","中共十一届三中全会","中共十二大","中共十三大"],"answer":3,"explanation":"1987年召开的中共十三大系统阐述了社会主义初级阶段理论，并在此基础上制定了党在社会主义初级阶段的基本路线。故选D。","__sub":"中特"},{"id":"zz-32556","module":"zhengzhi","prompt":"社会主义初级阶段的两层含义是：","options":["我国已经是社会主义社会，我国的社会主义社会还处在初级阶段","我国已经是共产主义社会，但还不发达","我国是半殖民地半封建社会，需要补课","我国是新民主主义社会，需要过渡"],"answer":0,"explanation":"社会主义初级阶段包括两层含义：第一，我国社会已经是社会主义社会，必须坚持而不能离开社会主义；第二，我国的社会主义社会还处在初级阶段，必须正视而不能超越这个阶段。故选A。","__sub":"中特"},{"id":"zz-32557","module":"zhengzhi","prompt":"社会主义初级阶段的主要矛盾是：","options":["生产社会化与生产资料私人占有之间的矛盾","无产阶级和资产阶级之间的矛盾","人民日益增长的美好生活需要和不平衡不充分的发展之间的矛盾","人民日益增长的物质文化需要同落后的社会生产之间的矛盾"],"answer":3,"explanation":"社会主义初级阶段的主要矛盾是人民日益增长的物质文化需要同落后的社会生产之间的矛盾，这一矛盾决定了党必须以经济建设为中心。故选D。","__sub":"中特"},{"id":"zz-32558","module":"zhengzhi","prompt":"党的基本路线的核心内容是：","options":["“一个中心、两个基本点”","“三步走”战略","“两手抓、两手都要硬”","“三个有利于”标准"],"answer":0,"explanation":"党在社会主义初级阶段的基本路线可概括为“一个中心、两个基本点”，即以经济建设为中心，坚持四项基本原则，坚持改革开放。故选A。","__sub":"中特"},{"id":"zz-32559","module":"zhengzhi","prompt":"基本路线中“一个中心”指的是：","options":["以社会建设为中心","以政治建设为中心","以文化建设为中心","以经济建设为中心"],"answer":3,"explanation":"基本路线坚持以经济建设为中心，这是由社会主义初级阶段主要矛盾决定的，是兴国之要。故选D。","__sub":"中特"},{"id":"zz-32560","module":"zhengzhi","prompt":"基本路线中“两个基本点”指的是：","options":["坚持四项基本原则、坚持改革开放","坚持党的领导、坚持人民民主专政","坚持独立自主、坚持自力更生","坚持物质文明、坚持精神文明"],"answer":0,"explanation":"“两个基本点”即坚持四项基本原则和坚持改革开放，四项基本原则是立国之本，改革开放是强国之路。故选A。","__sub":"中特"},{"id":"zz-32561","module":"zhengzhi","prompt":"四项基本原则被喻为：","options":["立国之本","强国之路","兴国之要","执政之基"],"answer":0,"explanation":"四项基本原则是立国之本，是党和国家生存发展的政治基石，规定了我国的根本性质和发展方向。故选A。","__sub":"中特"},{"id":"zz-32562","module":"zhengzhi","prompt":"改革开放被喻为：","options":["立国之本","强国之路","兴国之要","生命线"],"answer":1,"explanation":"改革开放是强国之路，是党和国家发展进步的活力源泉，是决定当代中国命运的关键抉择。故选B。","__sub":"中特"},{"id":"zz-32563","module":"zhengzhi","prompt":"以经济建设为中心被喻为：","options":["兴国之要","立国之本","强国之路","立党之本"],"answer":0,"explanation":"以经济建设为中心是兴国之要，是党和国家兴旺发达、长治久安的根本要求。故选A。","__sub":"中特"},{"id":"zz-32564","module":"zhengzhi","prompt":"党的基本路线被喻为：","options":["党的力量源泉","党的根本工作路线","党的政治优势","党和国家的生命线"],"answer":3,"explanation":"党的基本路线是党和国家的生命线、人民的幸福线，必须长期坚持、毫不动摇。故选D。","__sub":"中特"},{"id":"zz-32565","module":"zhengzhi","prompt":"党的十一届三中全会召开的时间是：","options":["1979年12月","1978年10月","1978年12月","1980年12月"],"answer":2,"explanation":"1978年12月召开的党的十一届三中全会，重新确立马克思主义的思想路线、政治路线和组织路线，开启了改革开放和社会主义现代化建设新时期。故选C。","__sub":"中特"},{"id":"zz-32566","module":"zhengzhi","prompt":"邓小平理论被写入党章并确立为党的指导思想的会议是：","options":["中共十三大","中共十五大","中共十四大","中共十六大"],"answer":1,"explanation":"1997年召开的中共十五大把邓小平理论写入党章，确立为党的指导思想，明确提出高举邓小平理论伟大旗帜。故选B。","__sub":"中特"},{"id":"zz-32567","module":"zhengzhi","prompt":"邓小平理论的精髓是：","options":["解放思想、实事求是","独立自主、自力更生","与时俱进、开拓创新","群众路线、调查研究"],"answer":0,"explanation":"解放思想、实事求是是邓小平理论的精髓，贯穿于邓小平理论形成和发展的全过程。故选A。","__sub":"中特"},{"id":"zz-32568","module":"zhengzhi","prompt":"被称为开辟新时期新道路的宣言书的著作是：","options":["《解放思想，实事求是，团结一致向前看》","《坚持四项基本原则》","《党和国家领导制度的改革》","《在武昌、深圳、珠海、上海等地的谈话要点》"],"answer":0,"explanation":"1978年12月，邓小平发表《解放思想，实事求是，团结一致向前看》，成为开辟新时期新道路的宣言书，实际上是十一届三中全会的主题报告。故选A。","__sub":"中特"},{"id":"zz-32569","module":"zhengzhi","prompt":"“发展才是硬道理”这一论断提出的场合是：","options":["1985年全国科技工作会议","1978年十一届三中全会","1992年南方谈话","1997年十五大报告"],"answer":2,"explanation":"1992年邓小平在南方谈话中提出“发展才是硬道理”，强调抓住机遇、加快发展，发展是解决中国所有问题的关键。故选C。","__sub":"中特"},{"id":"zz-32570","module":"zhengzhi","prompt":"“科学技术是第一生产力”论断提出的时间是：","options":["1978年","1988年","1982年","1992年"],"answer":1,"explanation":"1988年，邓小平提出“科学技术是第一生产力”的论断，深刻揭示了科学技术对当代生产力发展的决定性作用。故选B。","__sub":"中特"},{"id":"zz-32571","module":"zhengzhi","prompt":"“三步走”发展战略提出的会议是：","options":["中共十二大","中共十三大","中共十四大","中共十五大"],"answer":1,"explanation":"1987年中共十三大制定了“三步走”发展战略，对实现现代化的步骤作出具体部署。故选B。","__sub":"中特"},{"id":"zz-32572","module":"zhengzhi","prompt":"“三步走”发展战略的第二步目标是：","options":["到1990年实现国民生产总值翻一番，解决温饱","到20世纪末，使国民生产总值再增长一倍，人民生活达到小康水平","到21世纪中叶达到中等发达国家水平","到2020年全面建成小康社会"],"answer":1,"explanation":"“三步走”战略的第二步是到20世纪末，使国民生产总值再增长一倍，人民生活达到小康水平，这一目标在2000年如期实现。故选B。","__sub":"中特"},{"id":"zz-32573","module":"zhengzhi","prompt":"确立社会主义市场经济体制改革目标的会议是：","options":["中共十六大","中共十三大","中共十五大","中共十四大"],"answer":3,"explanation":"1992年召开的中共十四大明确提出，我国经济体制改革的目标是建立社会主义市场经济体制。故选D。","__sub":"中特"},{"id":"zz-32574","module":"zhengzhi","prompt":"“三个有利于”标准的内容是：","options":["是否有利于发展社会主义社会的生产力、增强社会主义国家的综合国力、提高人民的生活水平","是否有利于巩固党的领导、维护社会稳定、促进民族团结","是否有利于经济增长、社会进步、文化繁荣","是否有利于改革开放、经济发展、民生改善"],"answer":0,"explanation":"1992年南方谈话提出，判断各方面工作的是非得失，要以是否有利于发展社会主义社会的生产力、增强社会主义国家的综合国力、提高人民的生活水平为标准。故选A。","__sub":"中特"},{"id":"zz-32575","module":"zhengzhi","prompt":"改革在社会主义发展史上的性质是：","options":["一个阶级推翻另一个阶级的革命","社会主义制度的根本变革","社会主义制度的自我完善和发展","对社会主义制度的否定"],"answer":2,"explanation":"改革是社会主义制度的自我完善和发展，不是一个阶级推翻另一个阶级意义上的革命，其实质是体制的变革和利益的调整。故选C。","__sub":"中特"},{"id":"zz-32576","module":"zhengzhi","prompt":"邓小平把改革称为：","options":["中国的自我完善运动","中国的第一次革命","中国的第二次革命","中国的社会改良"],"answer":2,"explanation":"邓小平指出，改革是中国的第二次革命，是社会主义制度的自我完善和发展，其性质同过去的革命一样，也是为了扫除发展社会生产力的障碍。故选C。","__sub":"中特"},{"id":"zz-32577","module":"zhengzhi","prompt":"“一国两制”构想的最初提出是为了解决：","options":["台湾问题","香港问题","澳门问题","西藏问题"],"answer":0,"explanation":"“一国两制”构想最初是为解决台湾问题提出的，但首先运用于解决香港问题，随后用于解决澳门问题。故选A。","__sub":"中特"},{"id":"zz-32578","module":"zhengzhi","prompt":"“一国两制”首先运用于解决的问题是：","options":["香港问题","台湾问题","澳门问题","钓鱼岛问题"],"answer":0,"explanation":"“一国两制”构想虽然最初针对台湾问题提出，但首先运用于解决香港问题，1997年香港顺利回归祖国。故选A。","__sub":"中特"},{"id":"zz-32579","module":"zhengzhi","prompt":"在“一国两制”框架下，国家主体坚持的制度是：","options":["社会主义制度","资本主义制度","混合经济制度","联邦制度"],"answer":0,"explanation":"“一国两制”即在坚持一个中国的前提下，国家的主体坚持社会主义制度，香港、澳门、台湾保持原有的资本主义制度长期不变。故选A。","__sub":"中特"},{"id":"zz-32580","module":"zhengzhi","prompt":"首次系统倡导和平共处五项原则的中国领导人是：","options":["毛泽东","周恩来","邓小平","陈毅"],"answer":1,"explanation":"1953年底，周恩来在会见印度代表团时首次系统提出和平共处五项原则，此后成为我国处理国际关系的基本准则。故选B。","__sub":"中特"},{"id":"zz-32581","module":"zhengzhi","prompt":"邓小平对当代世界主题的判断是：","options":["多极化与全球化","战争与革命","竞争与合作","和平与发展"],"answer":3,"explanation":"邓小平作出和平与发展是当代世界两大主题的科学判断，为党和国家工作中心转移和对外开放提供了依据。故选D。","__sub":"中特"},{"id":"zz-32582","module":"zhengzhi","prompt":"“贫穷不是社会主义”这一论断强调的是：","options":["社会主义必须解放和发展生产力，实现共同富裕","社会主义必须实行平均主义","社会主义必须限制个人利益","社会主义必须消灭商品经济"],"answer":0,"explanation":"“贫穷不是社会主义”强调社会主义要解放和发展生产力，改善人民生活，逐步实现共同富裕，纠正了忽视生产力发展的错误观念。故选A。","__sub":"中特"},{"id":"zz-32583","module":"zhengzhi","prompt":"共同富裕在社会主义制度中的地位是：","options":["社会主义的过渡措施","社会主义的权宜之计","社会主义的辅助政策","社会主义的根本原则"],"answer":3,"explanation":"共同富裕是社会主义的根本原则和最大优越性，体现了社会主义本质的要求，是社会主义与资本主义的根本区别之一。故选D。","__sub":"中特"},{"id":"zz-32584","module":"zhengzhi","prompt":"“先富带后富”政策的含义是：","options":["实行平均主义分配","让少数人先富起来，其他人长期贫困","允许和鼓励一部分地区一部分人先富起来，逐步达到共同富裕","限制高收入者的合法收入"],"answer":2,"explanation":"邓小平提出允许和鼓励一部分地区、一部分人先富起来，先富带动后富，最终达到共同富裕，体现了效率与公平的统一。故选C。","__sub":"中特"},{"id":"zz-32585","module":"zhengzhi","prompt":"社会主义初级阶段基本纲领提出的会议是：","options":["中共十六大","中共十三大","中共十四大","中共十五大"],"answer":3,"explanation":"1997年中共十五大提出了党在社会主义初级阶段的基本纲领，明确了建设有中国特色社会主义的经济、政治、文化的基本目标和基本政策。故选D。","__sub":"中特"},{"id":"zz-32586","module":"zhengzhi","prompt":"依法治国基本方略首次提出的会议是：","options":["中共十七大","中共十四大","中共十六大","中共十五大"],"answer":3,"explanation":"1997年中共十五大首次提出依法治国、建设社会主义法治国家的基本方略，标志着党治国理政方式的重大转变。故选D。","__sub":"中特"},{"id":"zz-32587","module":"zhengzhi","prompt":"依法治国的含义是：","options":["广大人民群众在党的领导下，依照宪法和法律规定，通过各种途径和形式管理国家事务","政府依照行政命令管理国家事务","党依照党内法规直接管理社会事务","司法机关独立行使一切国家权力"],"answer":0,"explanation":"依法治国就是广大人民群众在党的领导下，依照宪法和法律规定，通过各种途径和形式管理国家事务、经济文化事业和社会事务。故选A。","__sub":"中特"},{"id":"zz-32588","module":"zhengzhi","prompt":"“两手抓，两手都要硬”强调的是：","options":["经济建设和国防建设并重","物质文明和精神文明都搞好","城市和农村同步发展","工业和农业协调发展"],"answer":1,"explanation":"邓小平强调物质文明和精神文明“两手抓，两手都要硬”，只有两个文明都搞好，才是有中国特色的社会主义。故选B。","__sub":"中特"},{"id":"zz-32589","module":"zhengzhi","prompt":"我国对外开放形成的格局是：","options":["以引进为主、输出为辅","单方向、单层次、窄领域","以沿海为主、内地为辅","全方位、多层次、宽领域"],"answer":3,"explanation":"经过多年努力，我国形成了全方位、多层次、宽领域的对外开放格局，开放型经济水平不断提高。故选D。","__sub":"中特"},{"id":"zz-32590","module":"zhengzhi","prompt":"经济特区“特”在：","options":["不受中央领导","实行特殊的政治制度","拥有独立主权","实行特殊的经济政策和特殊的经济管理体制"],"answer":3,"explanation":"经济特区的“特”在于实行特殊的经济政策和特殊的经济管理体制，坚持社会主义方向，而不是政治制度上的特殊。故选D。","__sub":"中特"},{"id":"zz-32591","module":"zhengzhi","prompt":"判断改革得失成败的根本标准是：","options":["“三个有利于”标准","经济增长速度","国有资产保值增值","群众满意度调查"],"answer":0,"explanation":"判断改革得失成败的根本标准是“三个有利于”，其中发展生产力是基础和前提，综合国力和人民生活是结果和体现。故选A。","__sub":"中特"},{"id":"zz-32592","module":"zhengzhi","prompt":"邓小平南方谈话的时间是：","options":["1990年初","1992年初","1991年初","1993年初"],"answer":1,"explanation":"1992年初，邓小平先后视察武昌、深圳、珠海、上海等地并发表谈话，科学总结了党的十一届三中全会以来的基本经验。故选B。","__sub":"中特"},{"id":"zz-32593","module":"zhengzhi","prompt":"南方谈话的历史意义是：","options":["标志着改革开放的正式启动","把改革开放和现代化建设事业推向新阶段的又一个宣言书","标志着社会主义市场经济体制的建成","标志着邓小平理论的最终形成"],"answer":1,"explanation":"南方谈话是把改革开放和现代化建设事业推向新阶段的又一个宣言书，为中共十四大的召开作了充分的理论准备。故选B。","__sub":"中特"},{"id":"zz-32594","module":"zhengzhi","prompt":"邓小平理论的历史地位是：","options":["独立于马克思主义的理论体系","马克思主义的个别观点补充","马克思主义的过渡性理论","马克思主义在中国发展的新阶段"],"answer":3,"explanation":"邓小平理论是当代中国的马克思主义，是马克思主义在中国发展的新阶段，开拓了马克思主义的新境界。故选D。","__sub":"中特"},{"id":"zz-32595","module":"zhengzhi","prompt":"首次提出“建设有中国特色的社会主义”命题的会议是：","options":["中共十三大","中共十一届三中全会","中共十二大","中共十四大"],"answer":2,"explanation":"1982年中共十二大上，邓小平提出“把马克思主义的普遍真理同我国的具体实际结合起来，走自己的道路，建设有中国特色的社会主义”。故选C。","__sub":"中特"},{"id":"zz-32596","module":"zhengzhi","prompt":"社会主义初级阶段的基本经济制度是：","options":["全民所有制经济一统天下","公有制为主体、多种所有制经济共同发展","私有制经济自由发展","计划经济与市场经济并存"],"answer":1,"explanation":"社会主义初级阶段坚持公有制为主体、多种所有制经济共同发展的基本经济制度，这是由我国社会主义性质和初级阶段国情决定的。故选B。","__sub":"中特"},{"id":"zz-32597","module":"zhengzhi","prompt":"社会主义初级阶段的分配制度是：","options":["按劳分配为主体、多种分配方式并存","按需分配","按资分配为主","平均主义分配"],"answer":0,"explanation":"与基本经济制度相适应，社会主义初级阶段坚持按劳分配为主体、多种分配方式并存的分配制度。故选A。","__sub":"中特"},{"id":"zz-32598","module":"zhengzhi","prompt":"社会主义市场经济体制的基本特征之一是：","options":["以计划配置资源为主","取消宏观调控","完全自由放任","坚持公有制的主体地位"],"answer":3,"explanation":"社会主义市场经济体制以坚持公有制的主体地位为基本标志，同时使市场在社会主义国家宏观调控下对资源配置起基础性作用。故选D。","__sub":"中特"},{"id":"zz-32599","module":"zhengzhi","prompt":"解决台湾问题、实现祖国完全统一的基本方针是：","options":["维持现状、搁置争议","武力统一、一党专政","联邦制、邦联制","“和平统一、一国两制”"],"answer":3,"explanation":"解决台湾问题、实现祖国完全统一的基本方针是“和平统一、一国两制”，同时决不承诺放弃使用武力。故选D。","__sub":"中特"},{"id":"zz-32600","module":"zhengzhi","prompt":"邓小平重新确立党的思想路线的贡献是：","options":["首次提出群众路线","首次提出实事求是","重新确立解放思想、实事求是的思想路线","首次提出独立自主"],"answer":2,"explanation":"邓小平领导和支持真理标准问题大讨论，重新确立了解放思想、实事求是的思想路线，为改革开放奠定了思想基础。故选C。","__sub":"中特"},{"id":"zz-32601","module":"zhengzhi","prompt":"社会主义本质论断中，处于基础地位的是：","options":["达到共同富裕","消灭剥削","消除两极分化","解放生产力，发展生产力"],"answer":3,"explanation":"社会主义本质论断中，解放生产力、发展生产力是基础，是实现消灭剥削、消除两极分化、最终达到共同富裕的前提条件。故选D。","__sub":"中特"},{"id":"zz-32602","module":"zhengzhi","prompt":"社会主义初级阶段主要矛盾中，矛盾的主要方面是：","options":["分配方式","人民的需要","落后的社会生产","所有制结构"],"answer":2,"explanation":"社会主义初级阶段主要矛盾中，落后的社会生产是矛盾的主要方面，因此必须坚持以经济建设为中心，大力发展生产力。故选C。","__sub":"中特"},{"id":"zz-32603","module":"zhengzhi","prompt":"我国社会主义初级阶段的时间跨度是指：","options":["从新中国成立到社会主义改造完成","从社会主义改造基本完成到社会主义现代化基本实现，至少需要一百年","从改革开放到全面建成小康社会","从建党到新中国成立"],"answer":1,"explanation":"我国社会主义初级阶段，是指从社会主义改造基本完成到社会主义现代化基本实现，至少需要一百年时间。故选B。","__sub":"中特"},{"id":"zz-32604","module":"zhengzhi","prompt":"中共十三大制定的党在社会主义初级阶段的基本路线的奋斗目标是：","options":["为建设社会主义现代化强国而奋斗","为把我国建设成为工业强国而奋斗","为全面建成小康社会而奋斗","为把我国建设成为富强、民主、文明的社会主义现代化国家而奋斗"],"answer":3,"explanation":"中共十三大确定的基本路线把奋斗目标概括为建设富强、民主、文明的社会主义现代化国家，后来十九大修改为富强民主文明和谐美丽。故选D。","__sub":"中特"},{"id":"zz-32605","module":"zhengzhi","prompt":"邓小平理论形成和发展的现实依据是：","options":["中华优秀传统文化","马克思列宁主义基本原理","我国改革开放和社会主义现代化建设的实践","苏联社会主义建设经验"],"answer":2,"explanation":"邓小平理论是在和平与发展成为时代主题的历史条件下，在我国改革开放和现代化建设的实践中形成和发展起来的。故选C。","__sub":"中特"},{"id":"zz-32606","module":"zhengzhi","prompt":"“一国两制”构想中“两制”的含义是：","options":["大陆实行社会主义制度，港澳台实行联邦制","国家的主体坚持社会主义制度，港澳台保持原有的资本主义制度长期不变","大陆和港澳台都实行社会主义制度","大陆实行资本主义制度，港澳台实行社会主义制度"],"answer":1,"explanation":"“两制”指国家的主体坚持社会主义制度，香港、澳门、台湾保持原有的资本主义制度长期不变，两种制度长期共存、和平共处。故选B。","__sub":"中特"},{"id":"zz-32607","module":"zhengzhi","prompt":"社会主义精神文明建设的根本任务是：","options":["培育有理想、有道德、有文化、有纪律的公民","发展文化产业","繁荣市场经济","普及义务教育"],"answer":0,"explanation":"社会主义精神文明建设的根本任务是培育有理想、有道德、有文化、有纪律的公民，提高全民族的思想道德素质和科学文化素质。故选A。","__sub":"中特"},{"id":"zz-32608","module":"zhengzhi","prompt":"邓小平提出的“三步走”战略的第三步目标是：","options":["到21世纪中叶，人均国民生产总值达到中等发达国家水平，人民生活比较富裕，基本实现现代化","到2010年建成小康社会","到2020年实现工业化","到2035年实现共同富裕"],"answer":0,"explanation":"“三步走”战略的第三步是到21世纪中叶，人均国民生产总值达到中等发达国家水平，人民生活比较富裕，基本实现现代化。故选A。","__sub":"中特"},{"id":"zz-32609","module":"zhengzhi","prompt":"邓小平理论回答的时代课题不包括：","options":["巩固和发展社会主义的问题","什么是社会主义、怎样建设社会主义","建设什么样的党、怎样建设党的一部分","实现什么样的发展、怎样发展"],"answer":3,"explanation":"“实现什么样的发展、怎样发展”是科学发展观回答的重大问题，不是邓小平理论回答的时代课题。故选D。","__sub":"中特"},{"id":"zz-32610","module":"zhengzhi","prompt":"社会主义初级阶段基本纲领中，建设中国特色社会主义政治的目标是：","options":["发展社会主义市场经济","在中国共产党领导下，在人民当家作主的基础上，依法治国，发展社会主义民主政治","发展社会主义先进文化","构建社会主义和谐社会"],"answer":1,"explanation":"社会主义初级阶段基本纲领规定，建设中国特色社会主义政治，就是在中国共产党领导下，在人民当家作主的基础上，依法治国，发展社会主义民主政治。故选B。","__sub":"中特"},{"id":"zz-32611","module":"zhengzhi","prompt":"“三个代表”重要思想首次完整提出的时间是：","options":["2000年2月","1998年2月","2001年7月","2002年11月"],"answer":0,"explanation":"2000年2月，江泽民在广东考察工作时，首次对“三个代表”要求作了比较全面的阐述。故选A。","__sub":"中特"},{"id":"zz-32612","module":"zhengzhi","prompt":"“三个代表”重要思想的内容是党要始终代表：","options":["先进技术的发展趋势、先进管理的演进方向、全体公民的个人利益","先进生产关系的发展要求、先进制度的改革方向、最大多数人的眼前利益","中国先进生产力的发展要求、先进文化的前进方向、最广大人民的根本利益","先进产业的投资方向、先进观念的传播路径、广大党员的根本利益"],"answer":2,"explanation":"“三个代表”即党要始终代表中国先进生产力的发展要求、中国先进文化的前进方向、中国最广大人民的根本利益。故选C。","__sub":"中特"},{"id":"zz-32613","module":"zhengzhi","prompt":"“三个代表”重要思想的本质是：","options":["解放思想、实事求是","立党为公、执政为民","与时俱进、开拓创新","艰苦奋斗、勤俭建国"],"answer":1,"explanation":"“三个代表”重要思想的本质是立党为公、执政为民，强调党的一切工作必须以最广大人民的根本利益为最高标准。故选B。","__sub":"中特"},{"id":"zz-32614","module":"zhengzhi","prompt":"贯彻“三个代表”重要思想，关键在：","options":["坚持与时俱进","坚持党的领导","坚持改革开放","坚持依法治国"],"answer":0,"explanation":"贯彻“三个代表”重要思想，关键在坚持与时俱进，核心在坚持党的先进性，本质在坚持执政为民。故选A。","__sub":"中特"},{"id":"zz-32615","module":"zhengzhi","prompt":"贯彻“三个代表”重要思想，核心在：","options":["坚持民主集中制","坚持与时俱进","坚持执政为民","坚持党的先进性"],"answer":3,"explanation":"贯彻“三个代表”重要思想，核心在坚持党的先进性，党的先进性是党生存和发展的根本条件。故选D。","__sub":"中特"},{"id":"zz-32616","module":"zhengzhi","prompt":"贯彻“三个代表”重要思想，本质在：","options":["坚持与时俱进","坚持执政为民","坚持党的先进性","坚持群众路线"],"answer":1,"explanation":"贯彻“三个代表”重要思想，本质在坚持执政为民，这是由党的全心全意为人民服务的宗旨决定的。故选B。","__sub":"中特"},{"id":"zz-32617","module":"zhengzhi","prompt":"“三个代表”重要思想被写入党章并确立为党的指导思想的会议是：","options":["中共十五大","中共十六大","中共十七大","中共十八大"],"answer":1,"explanation":"2002年11月召开的中共十六大把“三个代表”重要思想写入党章，实现党的指导思想的又一次与时俱进。故选B。","__sub":"中特"},{"id":"zz-32618","module":"zhengzhi","prompt":"“三个代表”重要思想形成的时代背景之一是：","options":["党由革命党转变为在野党","党的工作重心转入农村","党的历史方位发生重大变化","党放弃了对国家的领导权"],"answer":2,"explanation":"“三个代表”重要思想是在科学判断党的历史方位的基础上提出来的，党已经从领导人民为夺取全国政权而奋斗的党，成为领导人民掌握全国政权并长期执政的党。故选C。","__sub":"中特"},{"id":"zz-32619","module":"zhengzhi","prompt":"中共十六大党章规定，中国共产党是中国工人阶级的先锋队，同时是：","options":["全体公民的先锋队","中国人民和中华民族的先锋队","知识分子的先锋队","劳动者的先锋队"],"answer":1,"explanation":"中共十六大党章规定，中国共产党是中国工人阶级的先锋队，同时是中国人民和中华民族的先锋队，即“两个先锋队”。故选B。","__sub":"中特"},{"id":"zz-32620","module":"zhengzhi","prompt":"“三个代表”是统一整体，其中发展先进生产力是：","options":["党的建设的直接目标","发展先进文化的最终目的","实现人民利益的唯一内容","发展先进文化、实现最广大人民根本利益的基础条件"],"answer":3,"explanation":"“三个代表”是统一整体，相互联系、相互促进，发展先进生产力是基础条件，发展先进文化是重要力量，实现最广大人民的根本利益是出发点和落脚点。故选D。","__sub":"中特"},{"id":"zz-32621","module":"zhengzhi","prompt":"在“三个代表”的统一整体中，实现最广大人民的根本利益是：","options":["党的建设的次要任务","发展先进生产力的前提","发展先进文化的障碍","发展先进生产力和先进文化的目的"],"answer":3,"explanation":"在“三个代表”统一整体中，人民群众是先进生产力和先进文化的创造主体，实现最广大人民的根本利益是发展先进生产力和先进文化的目的所在。故选D。","__sub":"中特"},{"id":"zz-32622","module":"zhengzhi","prompt":"“三个代表”重要思想创造性地回答的重大问题是：","options":["建设什么样的党、怎样建设党","什么是社会主义、怎样建设社会主义","实现什么样的发展、怎样发展","什么是马克思主义、怎样对待马克思主义"],"answer":0,"explanation":"“三个代表”重要思想创造性地回答了建设什么样的党、怎样建设党的问题，深化了对共产党执政规律的认识。故选A。","__sub":"中特"},{"id":"zz-32623","module":"zhengzhi","prompt":"“三个代表”重要思想的历史地位是：","options":["独立于马克思主义的新体系","马克思主义的阶段性口号","党的临时工作方针","面向21世纪的中国化的马克思主义"],"answer":3,"explanation":"“三个代表”重要思想是面向21世纪的中国化的马克思主义，是对马克思列宁主义、毛泽东思想、邓小平理论的继承和发展。故选D。","__sub":"中特"},{"id":"zz-32624","module":"zhengzhi","prompt":"发展是党执政兴国的：","options":["第一要务","唯一任务","次要任务","最终目标"],"answer":0,"explanation":"十六大报告提出，党要承担起推动中国社会进步的历史责任，必须把发展作为党执政兴国的第一要务。故选A。","__sub":"中特"},{"id":"zz-32625","module":"zhengzhi","prompt":"提出全面建设小康社会奋斗目标的会议是：","options":["中共十五大","中共十六大","中共十七大","中共十八大"],"answer":1,"explanation":"2002年中共十六大提出要在21世纪头二十年，集中力量全面建设惠及十几亿人口的更高水平的小康社会。故选B。","__sub":"中特"},{"id":"zz-32626","module":"zhengzhi","prompt":"马克思主义具有的理论品质是：","options":["一成不变","因循守旧","与时俱进","照搬照抄"],"answer":2,"explanation":"江泽民指出，马克思主义具有与时俱进的理论品质，必须坚持解放思想、实事求是，在实践中丰富和发展马克思主义。故选C。","__sub":"中特"},{"id":"zz-32627","module":"zhengzhi","prompt":"“三个代表”重要思想坚持和发展的思想路线是：","options":["百花齐放、百家争鸣","独立自主、自力更生","解放思想、实事求是","统筹兼顾、协调发展"],"answer":2,"explanation":"“三个代表”重要思想坚持党的解放思想、实事求是的思想路线，把与时俱进同解放思想、实事求是联系起来。故选C。","__sub":"中特"},{"id":"zz-32628","module":"zhengzhi","prompt":"党的先进性的判断标准归根到底是看：","options":["党龄的长短","党员数量的多少","党在推动历史前进中的实际作用","党的机构规模的大小"],"answer":2,"explanation":"党的先进性是具体的、历史的，归根到底要看党在推动历史前进中的实际作用，看党能否始终做到“三个代表”。故选C。","__sub":"中特"},{"id":"zz-32629","module":"zhengzhi","prompt":"中共十六大提出，21世纪头二十年是我国：","options":["完成社会主义改造的时期","全面建设小康社会的新阶段","实现工业化的完成阶段","向共产主义过渡的阶段"],"answer":1,"explanation":"中共十六大判断，21世纪头二十年是一个必须紧紧抓住并且可以大有作为的重要战略机遇期，是全面建设小康社会的新阶段。故选B。","__sub":"中特"},{"id":"zz-32630","module":"zhengzhi","prompt":"2004年中共十六届四中全会通过的重要决定是：","options":["《中共中央关于加强党的执政能力建设的决定》","《关于建国以来党的若干历史问题的决议》","《关于构建社会主义和谐社会若干重大问题的决定》","《中共中央关于全面深化改革若干重大问题的决定》"],"answer":0,"explanation":"2004年中共十六届四中全会通过《中共中央关于加强党的执政能力建设的决定》，把党的执政能力建设作为党的建设的重要任务。故选A。","__sub":"中特"},{"id":"zz-32631","module":"zhengzhi","prompt":"“三个代表”重要思想强调，人民群众是：","options":["单纯的劳动工具","被动的管理对象","先进生产力和先进文化的创造主体","历史的旁观者"],"answer":2,"explanation":"“三个代表”重要思想强调，人民群众是先进生产力和先进文化的创造主体，也是实现自身利益的根本力量。故选C。","__sub":"中特"},{"id":"zz-32632","module":"zhengzhi","prompt":"“三个代表”重要思想中，先进文化的前进方向指的是：","options":["面向现代化、面向世界、面向未来的，民族的科学的大众的社会主义文化","全盘西化的文化","复古守旧的文化","封闭排外的文化"],"answer":0,"explanation":"代表先进文化的前进方向，就是发展面向现代化、面向世界、面向未来的，民族的科学的大众的社会主义文化。故选A。","__sub":"中特"},{"id":"zz-32633","module":"zhengzhi","prompt":"“三个代表”重要思想形成的实践基础是：","options":["改革开放以来特别是十三届四中全会以来的实践","新民主主义革命实践","社会主义改造实践","古代治国理政实践"],"answer":0,"explanation":"“三个代表”重要思想是在建设中国特色社会主义的伟大实践中形成的，改革开放以来特别是十三届四中全会以来的实践是其现实依据。故选A。","__sub":"中特"},{"id":"zz-32634","module":"zhengzhi","prompt":"“三个代表”重要思想对党的建设的根本要求是：","options":["把党建设成为经济利益集团","把党建设成为纯粹的学术团体","把党建设成为行政事务机关","把党建设成为领导中国特色社会主义事业的坚强领导核心"],"answer":3,"explanation":"“三个代表”重要思想要求按照党的建设总目标，把党建设成为用邓小平理论武装起来、全心全意为人民服务、思想上政治上组织上完全巩固、能够经受住各种风险、始终走在时代前列、领导全国人民建设中国特色社会主义的马克思主义政党。故选D。","__sub":"中特"},{"id":"zz-32635","module":"zhengzhi","prompt":"中共十六大提出的21世纪头二十年经济建设目标是：","options":["国内生产总值到2020年比2000年增长十倍","国内生产总值到2020年比2000年翻一番","国内生产总值到2010年比2000年翻两番","国内生产总值到2020年力争比2000年翻两番"],"answer":3,"explanation":"中共十六大提出，在优化结构和提高效益的基础上，国内生产总值到2020年力争比2000年翻两番，综合国力和国际竞争力明显增强。故选D。","__sub":"中特"},{"id":"zz-32636","module":"zhengzhi","prompt":"“三个代表”重要思想强调，党的一切工作的出发点和落脚点是：","options":["追求经济增长速度","维护少数精英的特殊利益","实现好、维护好、发展好最广大人民的根本利益","扩大党的组织规模"],"answer":2,"explanation":"“三个代表”重要思想强调，党的一切工作必须以最广大人民的根本利益为最高标准，把实现好、维护好、发展好最广大人民的根本利益作为出发点和落脚点。故选C。","__sub":"中特"},{"id":"zz-32637","module":"zhengzhi","prompt":"科学发展观首次提出的时间是：","options":["2002年11月","2003年10月","2005年10月","2007年10月"],"answer":1,"explanation":"2003年10月，中共十六届三中全会明确提出坚持以人为本，树立全面、协调、可持续的发展观，促进经济社会和人的全面发展。故选B。","__sub":"中特"},{"id":"zz-32638","module":"zhengzhi","prompt":"提出科学发展观这一重大战略思想的领导人是：","options":["胡锦涛","邓小平","江泽民","习近平"],"answer":0,"explanation":"2003年，以胡锦涛同志为主要代表的中国共产党人在抗击非典和探索发展道路的实践中提出科学发展观这一重大战略思想。故选A。","__sub":"中特"},{"id":"zz-32639","module":"zhengzhi","prompt":"科学发展观的核心是：","options":["以人为本","发展","全面协调可持续","统筹兼顾"],"answer":0,"explanation":"科学发展观的核心是以人为本，强调发展为了人民、发展依靠人民、发展成果由人民共享。故选A。","__sub":"中特"},{"id":"zz-32640","module":"zhengzhi","prompt":"科学发展观的基本要求是：","options":["全面协调可持续","高速增长","重点突破","先富后富"],"answer":0,"explanation":"科学发展观的基本要求是全面协调可持续，强调全面推进各方面建设，实现经济社会永续发展。故选A。","__sub":"中特"},{"id":"zz-32641","module":"zhengzhi","prompt":"科学发展观的根本方法是：","options":["各自为政","重点突破","单兵突进","统筹兼顾"],"answer":3,"explanation":"科学发展观的根本方法是统筹兼顾，要求正确认识和妥善处理中国特色社会主义事业中的重大关系。故选D。","__sub":"中特"},{"id":"zz-32642","module":"zhengzhi","prompt":"科学发展观回答的重大问题是：","options":["建设什么样的党、怎样建设党","什么是社会主义、怎样建设社会主义","新形势下实现什么样的发展、怎样发展","什么是马克思主义、怎样对待马克思主义"],"answer":2,"explanation":"科学发展观深刻回答了新形势下实现什么样的发展、怎样发展等重大问题，深化了对社会主义建设规律的认识。故选C。","__sub":"中特"},{"id":"zz-32643","module":"zhengzhi","prompt":"科学发展观的历史地位是：","options":["马克思主义的个别政策主张","马克思主义关于发展的世界观和方法论的集中体现","独立于马克思主义的发展理论","临时的经济调控手段"],"answer":1,"explanation":"科学发展观是马克思主义关于发展的世界观和方法论的集中体现，是同邓小平理论和“三个代表”重要思想既一脉相承又与时俱进的科学理论。故选B。","__sub":"中特"},{"id":"zz-32644","module":"zhengzhi","prompt":"以人为本中的“人”指的是：","options":["少数精英分子","最广大人民群众","党员干部","城市居民"],"answer":1,"explanation":"以人为本中的“人”指最广大人民群众，在当代中国就是以工人、农民、知识分子等劳动者为主体的最广大人民群众。故选B。","__sub":"中特"},{"id":"zz-32645","module":"zhengzhi","prompt":"以人为本中的“本”指的是：","options":["政府的行政权威","经济发展的总量","最广大人民的根本利益","资本的主导地位"],"answer":2,"explanation":"以人为本的“本”就是最广大人民的根本利益，强调发展为了人民、发展依靠人民、发展成果由人民共享。故选C。","__sub":"中特"},{"id":"zz-32646","module":"zhengzhi","prompt":"科学发展观写入党章的会议是：","options":["中共十八大","中共十六大","中共十七大","中共十九大"],"answer":2,"explanation":"2007年中共十七大将科学发展观写入党章；2012年中共十八大进一步把科学发展观确立为党必须长期坚持的指导思想。故选C。","__sub":"中特"},{"id":"zz-32647","module":"zhengzhi","prompt":"科学发展观确立为党的指导思想的会议是：","options":["中共十八大","中共十七大","中共十六大","中共十九大"],"answer":0,"explanation":"2012年中共十八大把科学发展观同马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想一道确立为党必须长期坚持的指导思想。故选A。","__sub":"中特"},{"id":"zz-32648","module":"zhengzhi","prompt":"统筹兼顾要求统筹的“五个统筹”之一是：","options":["统筹军队与地方发展","统筹城乡发展","统筹中央与个人利益","统筹国内与国外资本"],"answer":1,"explanation":"统筹兼顾要求统筹城乡发展、统筹区域发展、统筹经济社会发展、统筹人与自然和谐发展、统筹国内发展和对外开放。故选B。","__sub":"中特"},{"id":"zz-32649","module":"zhengzhi","prompt":"构建社会主义和谐社会的总要求是：","options":["富强民主、文明和谐、自由平等、公正法治、爱国敬业、诚信友善","民主法治、公平正义、诚信友爱、充满活力、安定有序、人与自然和谐相处","生产发展、生活宽裕、乡风文明、村容整洁、管理民主、环境优美","创新协调、绿色开放、共建共享、法治保障、安全稳定、共同富裕"],"answer":1,"explanation":"构建社会主义和谐社会的总要求是民主法治、公平正义、诚信友爱、充满活力、安定有序、人与自然和谐相处。故选B。","__sub":"中特"},{"id":"zz-32650","module":"zhengzhi","prompt":"提出构建社会主义和谐社会重大任务的会议是：","options":["中共十五届六中全会","中共十六届四中全会","中共十六大","中共十七大"],"answer":1,"explanation":"2004年中共十六届四中全会提出构建社会主义和谐社会的重大任务，2006年十六届六中全会通过构建社会主义和谐社会的专门决定。故选B。","__sub":"中特"},{"id":"zz-32651","module":"zhengzhi","prompt":"社会和谐在中国特色社会主义中的定位是：","options":["中国特色社会主义的最终形态","中国特色社会主义的权宜之计","中国特色社会主义的补充内容","中国特色社会主义的本质属性"],"answer":3,"explanation":"中共十六届六中全会指出，社会和谐是中国特色社会主义的本质属性，是国家富强、民族振兴、人民幸福的重要保证。故选D。","__sub":"中特"},{"id":"zz-32652","module":"zhengzhi","prompt":"社会主义核心价值体系的基本内容包括：","options":["马克思主义指导思想、中国特色社会主义共同理想、以爱国主义为核心的民族精神和以改革创新为核心的时代精神、社会主义荣辱观","富强民主文明和谐、自由平等公正法治、爱国敬业诚信友善","社会主义先进文化、革命文化、中华优秀传统文化","爱国主义、集体主义、社会主义、国际主义"],"answer":0,"explanation":"2006年中共十六届六中全会提出社会主义核心价值体系，包括马克思主义指导思想、中国特色社会主义共同理想、民族精神和时代精神、社会主义荣辱观四个方面。故选A。","__sub":"中特"},{"id":"zz-32653","module":"zhengzhi","prompt":"建设社会主义新农村的总要求是：","options":["农业强、农村美、农民富","产业兴旺、生态宜居、乡风文明、治理有效、生活富裕","生产发展、生活宽裕、乡风文明、村容整洁、管理民主","城乡一体、共同富裕、绿色发展"],"answer":2,"explanation":"2005年中共十六届五中全会提出建设社会主义新农村，总要求是生产发展、生活宽裕、乡风文明、村容整洁、管理民主。故选C。","__sub":"中特"},{"id":"zz-32654","module":"zhengzhi","prompt":"科学发展观的精神实质是：","options":["实现经济高速增长","实现经济社会又好又快发展","实现经济总量扩张","实现经济规模领先"],"answer":1,"explanation":"科学发展观的精神实质是实现经济社会又好又快发展，“好”强调发展的质量和效益，“快”强调发展的速度和机遇。故选B。","__sub":"中特"},{"id":"zz-32655","module":"zhengzhi","prompt":"以人为本体现的历史唯物主义基本原理是：","options":["英雄创造历史","人民群众是历史的创造者","生产力自发发展","意识决定存在"],"answer":1,"explanation":"以人为本体现了人民群众是历史的创造者这一历史唯物主义基本原理，坚持了马克思主义的群众观点。故选B。","__sub":"中特"},{"id":"zz-32656","module":"zhengzhi","prompt":"统筹人与自然和谐发展的基本要求是：","options":["限制工业发展","先污染后治理","以牺牲环境换取增长","建设资源节约型、环境友好型社会"],"answer":3,"explanation":"统筹人与自然和谐发展，要求建设资源节约型、环境友好型社会，实现经济发展与人口、资源、环境相协调。故选D。","__sub":"中特"},{"id":"zz-32657","module":"zhengzhi","prompt":"科学发展观中“全面”的含义是：","options":["只抓政治建设","只抓经济建设","全面推进经济、政治、文化、社会等各方面建设","只抓文化建设"],"answer":2,"explanation":"科学发展观中的“全面”是指全面推进经济、政治、文化、社会等各方面建设，实现经济发展和社会全面进步。故选C。","__sub":"中特"},{"id":"zz-32658","module":"zhengzhi","prompt":"科学发展观中“可持续”的含义是：","options":["实现经济发展与人口、资源、环境相协调，保证一代接一代地永续发展","保持当前增长速度不变","维持现有产业结构不动","延续传统发展模式"],"answer":0,"explanation":"“可持续”就是促进人与自然的和谐，实现经济发展与人口、资源、环境相协调，坚持走生产发展、生活富裕、生态良好的文明发展道路，保证一代接一代地永续发展。故选A。","__sub":"中特"},{"id":"zz-32659","module":"zhengzhi","prompt":"科学发展观与邓小平理论、“三个代表”重要思想的关系是：","options":["彼此无关的发展阶段","相互对立的理论体系","一脉相承又与时俱进的科学理论","前后否定的思想路线"],"answer":2,"explanation":"科学发展观同邓小平理论、“三个代表”重要思想既一脉相承又与时俱进，都坚持马克思主义基本原理，都立足中国实践。故选C。","__sub":"中特"},{"id":"zz-32660","module":"zhengzhi","prompt":"科学发展观形成的现实依据是：","options":["我国经济社会发展的阶段性特征","古代民本思想","西方发展经济学","计划经济体制"],"answer":0,"explanation":"科学发展观是在准确把握我国经济社会发展的阶段性特征、深刻分析我国发展面临的问题的基础上形成的。故选A。","__sub":"中特"},{"id":"zz-32661","module":"zhengzhi","prompt":"“三个代表”重要思想形成的国际背景是：","options":["经济全球化进程逆转","世界重回冷战对峙","世界多极化和经济全球化趋势在曲折中发展","和平与发展主题消失"],"answer":2,"explanation":"世纪之交，世界多极化和经济全球化趋势在曲折中发展，科技进步日新月异，综合国力竞争日趋激烈，这是“三个代表”重要思想形成的国际背景。故选C。","__sub":"中特"},{"id":"zz-32662","module":"zhengzhi","prompt":"始终代表中国最广大人民的根本利益，就是党的理论、路线、纲领、方针、政策和各项工作必须：","options":["坚持把人民的根本利益作为出发点和归宿","以少数群体的利益为优先","以经济增长为唯一目标","以行政效率为最高标准"],"answer":0,"explanation":"始终代表中国最广大人民的根本利益，就是党的理论、路线、纲领、方针、政策和各项工作，必须坚持把人民的根本利益作为出发点和归宿，使人民群众不断获得切实的经济、政治、文化利益。故选A。","__sub":"中特"},{"id":"zz-32663","module":"zhengzhi","prompt":"“三个代表”重要思想强调的执政党建设的核心问题是：","options":["保持党的先进性、巩固党的执政地位","扩大党的组织规模","增加党员数量","提高干部待遇"],"answer":0,"explanation":"“三个代表”重要思想围绕保持党的先进性、巩固党的执政地位这一核心问题，对党的建设作出系统部署。故选A。","__sub":"中特"},{"id":"zz-32664","module":"zhengzhi","prompt":"“三个代表”重要思想被称为党的：","options":["宣传口号、动员形式、活动载体","权宜之计、临时之策、过渡之举","工作方法、管理手段、考核标准","立党之本、执政之基、力量之源"],"answer":3,"explanation":"“三个代表”重要思想是我们的立党之本、执政之基、力量之源，是加强党的建设、推进我国社会主义自我完善和发展的强大理论武器。故选D。","__sub":"中特"},{"id":"zz-32665","module":"zhengzhi","prompt":"系统阐述“三个代表”重要思想的科学内涵和深远意义的讲话是：","options":["1992年南方谈话","2001年7月1日在庆祝中国共产党成立八十周年大会上的讲话","1978年中央工作会议讲话","2017年中共十九大报告"],"answer":1,"explanation":"2001年7月1日，江泽民在庆祝中国共产党成立八十周年大会上发表重要讲话，系统阐述了“三个代表”重要思想的科学内涵和精神实质。故选B。","__sub":"中特"},{"id":"zz-32666","module":"zhengzhi","prompt":"“三个代表”重要思想深化了对“三大规律”的认识，“三大规律”是指：","options":["经济规律、政治规律、文化规律","革命规律、建设规律、改革规律","自然规律、社会规律、思维规律","共产党执政规律、社会主义建设规律、人类社会发展规律"],"answer":3,"explanation":"“三个代表”重要思想深化了对共产党执政规律、社会主义建设规律、人类社会发展规律的认识，丰富和发展了马克思主义。故选D。","__sub":"中特"},{"id":"zz-32667","module":"zhengzhi","prompt":"党的先进性在“三个代表”重要思想中的特点是：","options":["具体的、历史的","抽象的、永恒的","固定的、单一的","偶然的、随意的"],"answer":0,"explanation":"“三个代表”重要思想强调，党的先进性是具体的、历史的，必须放到推动当代中国先进生产力和先进文化的发展中去考察，放到维护和实现最广大人民根本利益的奋斗中去考察。故选A。","__sub":"中特"},{"id":"zz-32668","module":"zhengzhi","prompt":"最广大人民的根本利益与群众具体利益的关系是：","options":["根本利益与具体利益对立","根本利益与具体利益的统一","具体利益可以取代根本利益","根本利益可以忽视具体利益"],"answer":1,"explanation":"“三个代表”重要思想强调，在实现最广大人民根本利益的同时，要正确反映和兼顾不同方面群众的利益，坚持根本利益与具体利益的统一。故选B。","__sub":"中特"},{"id":"zz-32669","module":"zhengzhi","prompt":"“三个代表”重要思想对党的建设提出的要求是按照：","options":["党的组织纪律来进行，围绕党内生活来展开","党的政治路线来进行，围绕党的中心任务来展开","行政命令来进行，围绕经济指标来展开","个人意志来进行，围绕领导偏好来展开"],"answer":1,"explanation":"“三个代表”重要思想要求党的建设必须按照党的政治路线来进行，围绕党的中心任务来展开，朝着党的建设总目标来加强。故选B。","__sub":"中特"},{"id":"zz-32670","module":"zhengzhi","prompt":"“三个代表”重要思想强调，发展先进文化的重要内容和中心环节是：","options":["普及义务教育","发展文化产业","加强社会主义思想道德建设","繁荣娱乐市场"],"answer":2,"explanation":"“三个代表”重要思想强调，加强社会主义思想道德建设，是发展先进文化的重要内容和中心环节，必须把依法治国和以德治国结合起来。故选C。","__sub":"中特"},{"id":"zz-32671","module":"zhengzhi","prompt":"科学发展观提出的根本依据是：","options":["西方发展经济学的启示","我国社会主义初级阶段的基本国情","古代民本思想的传承","国际组织的倡议"],"answer":1,"explanation":"科学发展观提出的根本依据是我国社会主义初级阶段的基本国情，是立足国情、总结实践、借鉴经验提出来的。故选B。","__sub":"中特"},{"id":"zz-32672","module":"zhengzhi","prompt":"2006年中共十六届六中全会通过的重要决定是：","options":["《关于建国以来党的若干历史问题的决议》","《中共中央关于加强党的执政能力建设的决定》","《中共中央关于全面深化改革若干重大问题的决定》","《中共中央关于构建社会主义和谐社会若干重大问题的决定》"],"answer":3,"explanation":"2006年10月，中共十六届六中全会通过《中共中央关于构建社会主义和谐社会若干重大问题的决定》，对构建社会主义和谐社会作出全面部署。故选D。","__sub":"中特"},{"id":"zz-32673","module":"zhengzhi","prompt":"社会主义荣辱观提出的时间是：","options":["2005年3月","2004年3月","2006年3月","2007年3月"],"answer":2,"explanation":"2006年3月，胡锦涛提出以“八荣八耻”为主要内容的社会主义荣辱观，成为社会主义核心价值体系的重要组成部分。故选C。","__sub":"中特"},{"id":"zz-32674","module":"zhengzhi","prompt":"科学发展观中的“协调发展”主要强调：","options":["各地区平均分配资源","各产业同步等速增长","统筹城乡、区域、经济社会、人与自然、国内发展与对外开放","各领域齐头并进不加区分"],"answer":2,"explanation":"科学发展观中的“协调发展”强调统筹城乡发展、区域发展、经济社会发展、人与自然和谐发展、国内发展和对外开放，推进各方面工作相互衔接、相互促进。故选C。","__sub":"中特"},{"id":"zz-32675","module":"zhengzhi","prompt":"以人为本与党的根本宗旨的关系是：","options":["以人为本取代了党的宗旨","以人为本体现了全心全意为人民服务的根本宗旨","以人为本是党的宗旨的对立面","以人为本与党的宗旨无关"],"answer":1,"explanation":"以人为本体现了党的全心全意为人民服务的根本宗旨，是党坚持立党为公、执政为民的必然要求。故选B。","__sub":"中特"},{"id":"zz-32676","module":"zhengzhi","prompt":"转变经济发展方式的主线是：","options":["经济结构战略性调整","扩大投资规模","增加货币投放","提高出口退税"],"answer":0,"explanation":"转变经济发展方式以经济结构战略性调整为主线，推动产业结构优化升级，促进经济增长由主要依靠投资出口拉动向依靠消费、投资、出口协调拉动转变。故选A。","__sub":"中特"},{"id":"zz-32677","module":"zhengzhi","prompt":"2006年提出的建设创新型国家的目标是：","options":["到2010年实现全面创新","到2020年使我国进入创新型国家行列","到2050年建成科技强国","到2035年实现技术垄断"],"answer":1,"explanation":"2006年，党中央提出建设创新型国家的战略目标，到2020年使我国的自主创新能力显著增强，进入创新型国家行列。故选B。","__sub":"中特"},{"id":"zz-32678","module":"zhengzhi","prompt":"科学发展观强调的发展必须是：","options":["粗放发展","高速发展","科学发展","单向发展"],"answer":2,"explanation":"科学发展观强调的发展必须是科学发展，即坚持以人为本、全面协调可持续的发展，注重提高发展质量和效益。故选C。","__sub":"中特"},{"id":"zz-32679","module":"zhengzhi","prompt":"科学发展观为哪一奋斗目标提供了重要遵循：","options":["完成祖国统一","实现共产主义","全面建设小康社会","建成现代化强国"],"answer":2,"explanation":"科学发展观是指导发展的科学理论，为全面建设小康社会、加快推进社会主义现代化提供了重要的指导思想和根本遵循。故选C。","__sub":"中特"},{"id":"zz-32680","module":"zhengzhi","prompt":"中共十七大对经济发展方式提出的要求是：","options":["加快经济增速排名","扩大经济总量规模","转变经济发展方式","维持粗放增长模式"],"answer":2,"explanation":"中共十七大提出转变经济发展方式，要求促进经济增长由主要依靠增加物质资源消耗向主要依靠科技进步、劳动者素质提高、管理创新转变。故选C。","__sub":"中特"},{"id":"zz-32681","module":"zhengzhi","prompt":"首次提出“中国特色社会主义理论体系”这一概念的会议是：","options":["中共十九大","中共十六大","中共十八大","中共十七大"],"answer":3,"explanation":"2007年中共十七大首次对“中国特色社会主义理论体系”作出概括，将其界定为包括邓小平理论、“三个代表”重要思想以及科学发展观等重大战略思想在内的科学理论体系。故选D。","__sub":"中特"},{"id":"zz-32682","module":"zhengzhi","prompt":"中国特色社会主义理论体系包括的重大理论成果是：","options":["毛泽东思想、邓小平理论","邓小平理论、“三个代表”重要思想、科学发展观","新民主主义理论、社会主义改造理论","习近平新时代中国特色社会主义思想单独构成"],"answer":1,"explanation":"中国特色社会主义理论体系包括邓小平理论、“三个代表”重要思想、科学发展观在内的科学理论体系，是改革开放以来党的理论创新成果的总和。故选B。","__sub":"中特"},{"id":"zz-32683","module":"zhengzhi","prompt":"开创中国特色社会主义道路的主要代表人物是：","options":["毛泽东","邓小平","江泽民","胡锦涛"],"answer":1,"explanation":"以邓小平为主要代表的中国共产党人，总结经验教训，成功开创了中国特色社会主义道路。故选B。","__sub":"中特"},{"id":"zz-32684","module":"zhengzhi","prompt":"建设中国特色社会主义的总依据是：","options":["社会主义初级阶段","社会主义市场经济体制","人民民主专政","改革开放"],"answer":0,"explanation":"建设中国特色社会主义的总依据是社会主义初级阶段，一切从初级阶段的实际出发，是制定路线方针政策的根本依据。故选A。","__sub":"中特"},{"id":"zz-32685","module":"zhengzhi","prompt":"建设中国特色社会主义的总布局是：","options":["“五位一体”","“四位一体”","“六位一体”","“三个文明”"],"answer":0,"explanation":"建设中国特色社会主义的总布局是“五位一体”，即经济建设、政治建设、文化建设、社会建设、生态文明建设五位一体。故选A。","__sub":"中特"},{"id":"zz-32686","module":"zhengzhi","prompt":"建设中国特色社会主义的总任务是：","options":["实现工业化","实现社会主义现代化和中华民族伟大复兴","建成小康社会","实现共同富裕"],"answer":1,"explanation":"建设中国特色社会主义的总任务是实现社会主义现代化和中华民族伟大复兴，这是贯穿改革开放以来党的全部理论和实践的总目标。故选B。","__sub":"中特"},{"id":"zz-32687","module":"zhengzhi","prompt":"中国特色社会主义由四个方面构成，其中行动指南是：","options":["中国特色社会主义道路","中国特色社会主义理论体系","中国特色社会主义制度","中国特色社会主义文化"],"answer":1,"explanation":"中国特色社会主义由道路、理论体系、制度、文化构成，其中理论体系是行动指南，道路是实现途径，制度是根本保障，文化是精神力量。故选B。","__sub":"中特"},{"id":"zz-32688","module":"zhengzhi","prompt":"中国特色社会主义由四个方面构成，其中根本保障是：","options":["中国特色社会主义制度","中国特色社会主义道路","中国特色社会主义理论体系","中国特色社会主义文化"],"answer":0,"explanation":"中国特色社会主义制度是当代中国发展进步的根本制度保障，集中体现了中国特色社会主义的特点和优势。故选A。","__sub":"中特"},{"id":"zz-32689","module":"zhengzhi","prompt":"中国特色社会主义由四个方面构成，其中实现途径是：","options":["中国特色社会主义制度","中国特色社会主义理论体系","中国特色社会主义道路","中国特色社会主义文化"],"answer":2,"explanation":"中国特色社会主义道路是实现社会主义现代化、创造人民美好生活的必由之路，是构成中国特色社会主义的实现途径。故选C。","__sub":"中特"},{"id":"zz-32690","module":"zhengzhi","prompt":"马克思主义中国化理论成果的精髓是：","options":["群众路线","实事求是","独立自主","与时俱进"],"answer":1,"explanation":"实事求是是马克思主义中国化理论成果的精髓，毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观都坚持和贯穿了这一精髓。故选B。","__sub":"中特"},{"id":"zz-32691","module":"zhengzhi","prompt":"党的思想路线的完整表述是：","options":["一切从群众利益出发，为群众办事，向群众负责，受群众监督","一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真理","解放思想，改革开放，凝聚力量，攻坚克难","自力更生，艰苦奋斗，奋发图强，勇攀高峰"],"answer":1,"explanation":"党的思想路线是一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真理，其中实事求是是核心。故选B。","__sub":"中特"},{"id":"zz-32692","module":"zhengzhi","prompt":"党的思想路线的基础和前提是：","options":["一切从实际出发","理论联系实际","实事求是","在实践中检验真理和发展真理"],"answer":0,"explanation":"一切从实际出发是党的思想路线的基础和前提，强调主观认识必须符合客观实际。故选A。","__sub":"中特"},{"id":"zz-32693","module":"zhengzhi","prompt":"党的思想路线的验证条件和目的是：","options":["一切从实际出发","在实践中检验真理和发展真理","理论联系实际","实事求是"],"answer":1,"explanation":"在实践中检验真理和发展真理是党的思想路线的验证条件和目的，实践是检验真理的唯一标准。故选B。","__sub":"中特"},{"id":"zz-32694","module":"zhengzhi","prompt":"四项基本原则的内容是：","options":["坚持社会主义道路、坚持人民民主专政、坚持中国共产党的领导、坚持马克思列宁主义毛泽东思想","坚持改革开放、坚持市场经济、坚持依法治国、坚持科教兴国","坚持党的领导、坚持人民当家作主、坚持依法治国、坚持民主集中制","坚持独立自主、坚持和平发展、坚持合作共赢、坚持多边主义"],"answer":0,"explanation":"四项基本原则即坚持社会主义道路、坚持人民民主专政、坚持中国共产党的领导、坚持马克思列宁主义毛泽东思想，是立国之本。故选A。","__sub":"中特"},{"id":"zz-32695","module":"zhengzhi","prompt":"改革开放被称为决定当代中国命运的：","options":["次要手段","权宜之计","临时举措","关键一招"],"answer":3,"explanation":"习近平总书记强调，改革开放是决定当代中国命运的关键一招，也是决定实现“两个一百年”奋斗目标、实现中华民族伟大复兴的关键一招。故选D。","__sub":"中特"},{"id":"zz-32696","module":"zhengzhi","prompt":"中国特色社会主义共同理想的内容是：","options":["建设世界一流强国","实现共产主义远大理想","建设中国特色社会主义，实现中华民族伟大复兴","实现全球一体化"],"answer":2,"explanation":"中国特色社会主义共同理想是建设中国特色社会主义、实现中华民族伟大复兴，它是共产主义远大理想在现阶段的具体体现。故选C。","__sub":"中特"},{"id":"zz-32697","module":"zhengzhi","prompt":"马克思主义中国化的两大理论成果是：","options":["毛泽东思想和中国特色社会主义理论体系","毛泽东思想和邓小平理论","新民主主义理论和社会主义改造理论","邓小平理论和科学发展观"],"answer":0,"explanation":"马克思主义中国化实现了两次历史性飞跃，形成了毛泽东思想和中国特色社会主义理论体系两大理论成果。故选A。","__sub":"中特"},{"id":"zz-32698","module":"zhengzhi","prompt":"改革开放以来党的全部理论和实践的主题是：","options":["实现共同富裕","社会主义市场经济","全面建设小康社会","中国特色社会主义"],"answer":3,"explanation":"中共十九大指出，中国特色社会主义是改革开放以来党的全部理论和实践的主题，必须一以贯之坚持和发展。故选D。","__sub":"中特"},{"id":"zz-32699","module":"zhengzhi","prompt":"中国特色社会主义最本质的特征同制度优势的关系是：","options":["党的领导既是最本质的特征，又是制度优势的集中体现","党的领导只是政治口号","党的领导与制度优势无关","制度优势独立于党的领导"],"answer":0,"explanation":"党的十九大报告指出，中国特色社会主义最本质的特征是中国共产党领导，中国特色社会主义制度的最大优势是中国共产党领导，二者统一于党的领导这一核心。故选A。","__sub":"中特"},{"id":"zz-32700","module":"zhengzhi","prompt":"我国正处于并将长期处于的发展阶段是：","options":["小康社会","新民主主义社会","共产主义社会第一阶段","社会主义初级阶段"],"answer":3,"explanation":"我国正处于并将长期处于社会主义初级阶段，这是当代中国最大的实际、最基本的国情。故选D。","__sub":"中特"},{"id":"zz-32701","module":"zhengzhi","prompt":"党在社会主义初级阶段基本纲领中的经济建设纲领是：","options":["发展社会主义市场经济，解放和发展生产力","发展社会主义民主政治","发展社会主义先进文化","构建社会主义和谐社会"],"answer":0,"explanation":"社会主义初级阶段基本纲领中的经济纲领是发展社会主义市场经济，不断解放和发展生产力，实现国民经济又好又快发展。故选A。","__sub":"中特"},{"id":"zz-32702","module":"zhengzhi","prompt":"坚持党的领导、人民当家作主、依法治国有机统一中，社会主义民主政治的本质和核心是：","options":["依法治国","党的领导","人民当家作主","民主集中制"],"answer":2,"explanation":"人民当家作主是社会主义民主政治的本质和核心，发展社会主义民主政治就是要体现人民意志、保障人民权益。故选C。","__sub":"中特"},{"id":"zz-32703","module":"zhengzhi","prompt":"依法治国在党治国理政方式中的定位是：","options":["党领导人民治理国家的基本方略","党管理干部的具体办法","党联系群众的唯一途径","党制定政策的参考意见"],"answer":0,"explanation":"依法治国是党领导人民治理国家的基本方略，是发展社会主义民主政治的必然要求。故选A。","__sub":"中特"},{"id":"zz-32704","module":"zhengzhi","prompt":"人民代表大会制度在我国政治制度中的地位是：","options":["根本政治制度","基本政治制度","重要政治制度","辅助政治制度"],"answer":0,"explanation":"人民代表大会制度是我国的根本政治制度，是坚持党的领导、人民当家作主、依法治国有机统一的重要制度载体。故选A。","__sub":"中特"},{"id":"zz-32705","module":"zhengzhi","prompt":"我国的基本政治制度包括：","options":["人民代表大会制度、多党合作制度、选举制度","中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度","社会主义制度、市场经济制度、法治制度","中央集权制度、地方自治制度、特别行政区制度"],"answer":1,"explanation":"我国的基本政治制度包括中国共产党领导的多党合作和政治协商制度、民族区域自治制度、基层群众自治制度，人民代表大会制度是根本政治制度。故选B。","__sub":"中特"},{"id":"zz-32706","module":"zhengzhi","prompt":"中国特色社会主义的根本原则是：","options":["同步富裕","平均主义","共同富裕","同等富裕"],"answer":2,"explanation":"共同富裕是中国特色社会主义的根本原则，必须坚持走共同富裕道路，使发展成果更多更公平惠及全体人民。故选C。","__sub":"中特"},{"id":"zz-32707","module":"zhengzhi","prompt":"对外开放被确立为：","options":["权宜之计","临时政策","基本国策","过渡措施"],"answer":2,"explanation":"对外开放是我国的基本国策，是推动我国经济社会发展的重要动力，必须长期坚持。故选C。","__sub":"中特"},{"id":"zz-32708","module":"zhengzhi","prompt":"中国特色社会主义理论体系与毛泽东思想的关系是：","options":["部分重复的理论体系","相互否定的理论体系","彼此独立的理论体系","一脉相承又与时俱进的科学理论体系"],"answer":3,"explanation":"中国特色社会主义理论体系与毛泽东思想是一脉相承又与时俱进的关系，都坚持马克思主义基本原理与中国实际相结合。故选D。","__sub":"中特"},{"id":"zz-32709","module":"zhengzhi","prompt":"邓小平理论在中国特色社会主义理论体系中的地位是：","options":["总结之作","开创之作","补充之作","过渡之作"],"answer":1,"explanation":"邓小平理论是中国特色社会主义理论体系的开创之作，第一次比较系统地初步回答了在中国如何建设社会主义的问题。故选B。","__sub":"中特"},{"id":"zz-32710","module":"zhengzhi","prompt":"我国社会主义民主政治建设坚持的政治发展道路是：","options":["坚持三权分立","坚持多党轮流执政","坚持党的领导、人民当家作主、依法治国有机统一","坚持议会民主"],"answer":2,"explanation":"中国特色社会主义政治发展道路坚持党的领导、人民当家作主、依法治国有机统一，三者统一于我国社会主义民主政治的伟大实践。故选C。","__sub":"中特"},{"id":"zz-32711","module":"zhengzhi","prompt":"中国特色社会主义制度体系中的基本经济制度是：","options":["全民所有制","公有制为主体、多种所有制经济共同发展","集体所有制","私有制为主"],"answer":1,"explanation":"公有制为主体、多种所有制经济共同发展是我国的基本经济制度，是社会主义初级阶段必须长期坚持的制度安排。故选B。","__sub":"中特"},{"id":"zz-32712","module":"zhengzhi","prompt":"党的基本路线中“两个基本点”的相互关系是：","options":["相互贯通、相互依存，统一于中国特色社会主义伟大实践","相互对立、此消彼长","彼此独立、互不相干","先后替代、不能并存"],"answer":0,"explanation":"坚持四项基本原则和坚持改革开放这两个基本点相互贯通、相互依存，统一于建设中国特色社会主义的伟大实践。故选A。","__sub":"中特"},{"id":"zz-32713","module":"zhengzhi","prompt":"中国特色社会主义理论体系的精髓是：","options":["与时俱进","改革开放","解放思想、实事求是","独立自主"],"answer":2,"explanation":"解放思想、实事求是是中国特色社会主义理论体系的精髓，是贯穿各个理论成果的灵魂。故选C。","__sub":"中特"},{"id":"zz-32714","module":"zhengzhi","prompt":"建设中国特色社会主义文化的要求是：","options":["以传统文化为指导，复兴古代礼乐制度","以马克思主义为指导，发展面向现代化、面向世界、面向未来的，民族的科学的大众的文化","以西方文化为蓝本，全盘引进外来文明","以经济利益为导向，发展文化娱乐产业"],"answer":1,"explanation":"建设中国特色社会主义文化，就是以马克思主义为指导，发展面向现代化、面向世界、面向未来的，民族的科学的大众的文化。故选B。","__sub":"中特"},{"id":"zz-32715","module":"zhengzhi","prompt":"社会主义初级阶段主要矛盾决定的中心任务是：","options":["阶级斗争","经济建设","政治建设","文化建设"],"answer":1,"explanation":"社会主义初级阶段的主要矛盾决定了党和国家的中心任务是经济建设，必须坚持以经济建设为中心不动摇。故选B。","__sub":"中特"},{"id":"zz-32716","module":"zhengzhi","prompt":"中国特色社会主义制度优势得以发挥的根本保证是：","options":["党的领导","市场经济","法治建设","科技创新"],"answer":0,"explanation":"党的领导是中国特色社会主义最本质的特征，也是中国特色社会主义制度优势得以发挥的根本保证。故选A。","__sub":"中特"},{"id":"zz-32717","module":"zhengzhi","prompt":"改革开放的目的之一是：","options":["照搬西方模式","改变社会主义基本制度","放弃党的领导","解放和发展社会生产力，实现国家现代化"],"answer":3,"explanation":"改革开放的目的是解放和发展社会生产力、实现国家现代化，让中国人民富裕起来，振兴伟大的中华民族。故选D。","__sub":"中特"},{"id":"zz-32718","module":"zhengzhi","prompt":"我国社会主义初级阶段基本纲领中的政治纲领是：","options":["发展社会主义民主政治，建设社会主义法治国家","发展社会主义市场经济","发展社会主义先进文化","建设社会主义生态文明"],"answer":0,"explanation":"社会主义初级阶段基本纲领中的政治纲领是在中国共产党领导下，在人民当家作主的基础上，依法治国，发展社会主义民主政治，建设社会主义法治国家。故选A。","__sub":"中特"},{"id":"zz-32719","module":"zhengzhi","prompt":"中国特色社会主义理论体系形成和发展的时代背景是：","options":["和平与发展成为时代主题","战争与革命","冷战对峙","经济危机频发"],"answer":0,"explanation":"中国特色社会主义理论体系是在和平与发展成为时代主题的历史条件下形成和发展起来的，反映了时代发展变化对党和国家工作的新要求。故选A。","__sub":"中特"},{"id":"zz-32720","module":"zhengzhi","prompt":"党的基本路线规定的富强民主文明和谐美丽的社会主义现代化强国目标，是在哪次大会上写入的：","options":["中共十七大","中共十六大","中共十八大","中共十九大"],"answer":3,"explanation":"中共十九大将基本路线的奋斗目标修改为“把我国建设成为富强民主文明和谐美丽的社会主义现代化强国”，增加了“和谐美丽”的要求。故选D。","__sub":"中特"},{"id":"zz-32721","module":"zhengzhi","prompt":"中国特色社会主义法治道路的核心要义是：","options":["坚持三权分立、坚持司法独立、坚持违宪审查","坚持党的领导、坚持中国特色社会主义制度、贯彻中国特色社会主义法治理论","坚持全民立法、坚持直接民主、坚持地方自治","坚持德治为主、坚持法治为辅、坚持礼法并用"],"answer":1,"explanation":"中国特色社会主义法治道路的核心要义是坚持党的领导、坚持中国特色社会主义制度、贯彻中国特色社会主义法治理论，三个方面规定了法治道路的性质和方向。故选B。","__sub":"中特"},{"id":"zz-32722","module":"zhengzhi","prompt":"党领导人民治理国家的基本方式是：","options":["依法治国","以德治国","政策治国","经验治国"],"answer":0,"explanation":"依法治国是党领导人民治理国家的基本方式，要求党领导立法、保证执法、支持司法、带头守法。故选A。","__sub":"中特"},{"id":"zz-32723","module":"zhengzhi","prompt":"建设中国特色社会主义的总布局中，生态文明建设的作用是：","options":["经济发展的对立面","可有可无的软性指标","关系人民福祉、关乎民族未来的长远大计","临时应对环境问题的措施"],"answer":2,"explanation":"在“五位一体”总布局中，生态文明建设关系人民福祉、关乎民族未来，必须融入经济建设、政治建设、文化建设、社会建设各方面和全过程。故选C。","__sub":"中特"},{"id":"zz-32724","module":"zhengzhi","prompt":"中国特色社会主义政治制度的鲜明特点是：","options":["坚持党的领导、人民当家作主、依法治国有机统一","实行多党轮流执政","实行三权分立制衡","实行联邦分权治理"],"answer":0,"explanation":"中国特色社会主义政治制度的鲜明特点是坚持党的领导、人民当家作主、依法治国有机统一，保证了人民当家作主的实现。故选A。","__sub":"中特"},{"id":"zz-32725","module":"zhengzhi","prompt":"实现中华民族伟大复兴的根本道路是：","options":["封闭僵化的老路","资本主义道路","中国特色社会主义道路","改旗易帜的邪路"],"answer":2,"explanation":"中国特色社会主义道路是实现社会主义现代化、创造人民美好生活的必由之路，也是实现中华民族伟大复兴的根本道路。故选C。","__sub":"中特"},{"id":"zz-32726","module":"zhengzhi","prompt":"习近平新时代中国特色社会主义思想被写入党章并确立为党的指导思想的会议是：","options":["中共十八大","中共十九大","中共十九届六中全会","中共二十大"],"answer":1,"explanation":"2017年中共十九大将习近平新时代中国特色社会主义思想写入党章，确立为党必须长期坚持的指导思想。故选B。","__sub":"中特"},{"id":"zz-32727","module":"zhengzhi","prompt":"习近平新时代中国特色社会主义思想是马克思主义中国化时代化的：","options":["初步成果","过渡成果","局部成果","最新成果"],"answer":3,"explanation":"习近平新时代中国特色社会主义思想是当代中国马克思主义、二十一世纪马克思主义，是马克思主义中国化时代化的最新成果。故选D。","__sub":"中特"},{"id":"zz-32728","module":"zhengzhi","prompt":"“十个明确”出自的文献是：","options":["中共二十大报告","中共十九大报告","《中共中央关于党的百年奋斗重大成就和历史经验的决议》","《习近平谈治国理政》第一卷"],"answer":2,"explanation":"2021年中共十九届六中全会通过的《中共中央关于党的百年奋斗重大成就和历史经验的决议》以“十个明确”对习近平新时代中国特色社会主义思想的核心内容作出系统概括。故选C。","__sub":"中特"},{"id":"zz-32729","module":"zhengzhi","prompt":"“十四个坚持”出自的文献是：","options":["十九届六中全会决议","中共十八大报告","中共十九大报告","中共二十大报告"],"answer":2,"explanation":"2017年中共十九大报告以“十四个坚持”阐述了新时代坚持和发展中国特色社会主义的基本方略。故选C。","__sub":"中特"},{"id":"zz-32730","module":"zhengzhi","prompt":"“十个明确”与“十四个坚持”的关系是：","options":["二者完全重复","前者是实践纲领，后者是理论概括","前者是理论层面的高度概括，后者是实践层面的行动纲领","二者相互矛盾"],"answer":2,"explanation":"“十个明确”是习近平新时代中国特色社会主义思想的核心内容，属于理论层面的高度概括；“十四个坚持”是新时代坚持和发展中国特色社会主义的基本方略，属于实践层面的行动纲领。故选C。","__sub":"中特"},{"id":"zz-32731","module":"zhengzhi","prompt":"习近平新时代中国特色社会主义思想的世界观和方法论集中体现为：","options":["“六个必须坚持”","“十个明确”","“十四个坚持”","“四个全面”"],"answer":0,"explanation":"党的二十大报告提出“六个必须坚持”，即必须坚持人民至上、自信自立、守正创新、问题导向、系统观念、胸怀天下，集中体现了习近平新时代中国特色社会主义思想的世界观和方法论。故选A。","__sub":"中特"},{"id":"zz-32732","module":"zhengzhi","prompt":"“六个必须坚持”中居于首位的是：","options":["坚持守正创新","坚持自信自立","坚持人民至上","坚持系统观念"],"answer":2,"explanation":"“六个必须坚持”中，坚持人民至上居于首位，体现了人民性是马克思主义的本质属性，人民立场是党的根本政治立场。故选C。","__sub":"中特"},{"id":"zz-32733","module":"zhengzhi","prompt":"提出“把马克思主义基本原理同中国具体实际相结合、同中华优秀传统文化相结合”即“两个结合”的重要论述是在：","options":["2017年10月中共十九大","2012年11月中共十八大","2021年7月1日庆祝中国共产党成立100周年大会","2022年10月中共二十大"],"answer":2,"explanation":"2021年7月1日，习近平总书记在庆祝中国共产党成立100周年大会上提出“两个结合”的重大论断，深化了对马克思主义中国化的规律性认识。故选C。","__sub":"中特"},{"id":"zz-32734","module":"zhengzhi","prompt":"“第二个结合”指的是：","options":["把马克思主义基本原理同西方文明相结合","把马克思主义基本原理同中华优秀传统文化相结合","把中华优秀传统文化同外来文化相结合","把革命文化同社会主义先进文化相结合"],"answer":1,"explanation":"“第二个结合”即把马克思主义基本原理同中华优秀传统文化相结合，是又一次的思想解放，筑牢了道路根基。故选B。","__sub":"中特"},{"id":"zz-32735","module":"zhengzhi","prompt":"中国特色社会主义进入新时代的判断依据之一是：","options":["经济发展速度不断加快","党的组织规模不断扩大","国际地位持续下降","党的十八大以来党和国家事业发生历史性变革"],"answer":3,"explanation":"党的十八大以来，党和国家事业取得历史性成就、发生历史性变革，我国发展站到了新的历史起点上，中国特色社会主义进入了新时代。故选D。","__sub":"中特"},{"id":"zz-32736","module":"zhengzhi","prompt":"党的十九大对社会主要矛盾变化作出的重大判断是：","options":["局部调整的策略性变化","关系全局的历史性变化","临时应对的政策性变化","方向逆转的根本性变化"],"answer":1,"explanation":"党的十九大指出，我国社会主要矛盾的变化是关系全局的历史性变化，对党和国家工作提出了许多新要求。故选B。","__sub":"中特"},{"id":"zz-32737","module":"zhengzhi","prompt":"新时代社会主要矛盾的变化意味着：","options":["我国已经成为发达国家","我国已经跨越社会主义初级阶段","我国社会生产力水平总体上显著提高，但发展不平衡不充分问题突出","以经济建设为中心已经过时"],"answer":2,"explanation":"社会主要矛盾的变化没有改变我们对我国社会主义所处历史阶段的判断，我国仍处于并将长期处于社会主义初级阶段的基本国情没有变。故选C。","__sub":"中特"},{"id":"zz-32738","module":"zhengzhi","prompt":"“两个一百年”奋斗目标是指：","options":["到2020年实现现代化，到2050年实现共产主义","到建党一百年时实现工业化，到新中国成立一百年时实现共同富裕","到建党一百年时全面建成小康社会，到新中国成立一百年时建成社会主义现代化强国","到2035年建成小康社会，到本世纪末建成现代化强国"],"answer":2,"explanation":"“两个一百年”奋斗目标即到建党一百年时全面建成小康社会，到新中国成立一百年时全面建成社会主义现代化强国。故选C。","__sub":"中特"},{"id":"zz-32739","module":"zhengzhi","prompt":"党的十九大提出的全面建设社会主义现代化国家的战略安排是：","options":["分四步走，每十年一个台阶","分三步走，2020年、2035年、2050年分别实现温饱、小康、现代化","一步到位，2020年直接建成现代化强国","分两步走，2035年基本实现社会主义现代化，本世纪中叶建成社会主义现代化强国"],"answer":3,"explanation":"党的十九大提出，从2020年到本世纪中叶分两个阶段安排：第一个阶段从2020年到2035年，基本实现社会主义现代化；第二个阶段从2035年到本世纪中叶，把我国建成富强民主文明和谐美丽的社会主义现代化强国。故选D。","__sub":"中特"},{"id":"zz-32740","module":"zhengzhi","prompt":"2035年基本实现社会主义现代化的远景目标之一是：","options":["建成零碳社会","国内生产总值居世界第一","实现共产主义","人均国内生产总值达到中等发达国家水平"],"answer":3,"explanation":"2035年基本实现社会主义现代化的目标包括经济实力、科技实力大幅跃升，人均国内生产总值达到中等发达国家水平等。故选D。","__sub":"中特"},{"id":"zz-32741","module":"zhengzhi","prompt":"提出构建以国内大循环为主体、国内国际双循环相互促进的新发展格局的场合是：","options":["2001年中国加入世贸组织","2012年中共十八大","2017年中共十九大","2020年5月中共中央政治局常务委员会会议等场合逐步提出"],"answer":3,"explanation":"2020年以来，以习近平同志为核心的党中央提出构建以国内大循环为主体、国内国际双循环相互促进的新发展格局，是根据我国发展阶段、环境、条件变化作出的战略决策。故选D。","__sub":"中特"},{"id":"zz-32742","module":"zhengzhi","prompt":"党的十九大作出的我国经济发展阶段变化的重大判断是：","options":["我国经济已由高速增长阶段转向高质量发展阶段","我国经济已由中速增长阶段转向低速增长阶段","我国经济已进入停滞阶段","我国经济已恢复高速增长阶段"],"answer":0,"explanation":"党的十九大指出，我国经济已由高速增长阶段转向高质量发展阶段，正处在转变发展方式、优化经济结构、转换增长动力的攻关期。故选A。","__sub":"中特"},{"id":"zz-32743","module":"zhengzhi","prompt":"供给侧结构性改革的重点是：","options":["提高供给体系质量和效率","扩大政府投资规模","刺激房地产消费","增加货币发行量"],"answer":0,"explanation":"供给侧结构性改革的重点是提高供给体系质量和效率，增强供给结构对需求变化的适应性和灵活性，使供给能力更好满足人民日益增长的美好生活需要。故选A。","__sub":"中特"},{"id":"zz-32744","module":"zhengzhi","prompt":"提出乡村振兴战略的会议是：","options":["中共十六大","中共十八大","中共十九大","中共十七大"],"answer":2,"explanation":"2017年中共十九大提出实施乡村振兴战略，按照产业兴旺、生态宜居、乡风文明、治理有效、生活富裕的总要求推进农业农村现代化。故选C。","__sub":"中特"},{"id":"zz-32745","module":"zhengzhi","prompt":"实施乡村振兴战略的总目标是：","options":["农业机械化","农业农村现代化","农村城镇化","农民市民化"],"answer":1,"explanation":"实施乡村振兴战略的总目标是农业农村现代化，总方针是坚持农业农村优先发展，按照产业兴旺、生态宜居、乡风文明、治理有效、生活富裕的总要求推进。故选B。","__sub":"中特"},{"id":"zz-32746","module":"zhengzhi","prompt":"习近平总书记提出“绿水青山就是金山银山”理念的时间是：","options":["1998年8月","2005年8月","2012年11月","2017年10月"],"answer":1,"explanation":"2005年8月，时任浙江省委书记的习近平在安吉余村考察时首次提出“绿水青山就是金山银山”的理念，成为习近平生态文明思想的重要内容。故选B。","__sub":"中特"},{"id":"zz-32747","module":"zhengzhi","prompt":"总体国家安全观强调，以什么为宗旨：","options":["政治安全","人民安全","经济安全","军事安全"],"answer":1,"explanation":"总体国家安全观坚持以人民安全为宗旨，以政治安全为根本，以经济安全为基础，以军事、科技、文化、社会安全为保障。故选B。","__sub":"中特"},{"id":"zz-32748","module":"zhengzhi","prompt":"以人民为中心的发展思想回答的核心问题是：","options":["建设什么城市、发展什么乡村","发展什么产业、采用什么技术","发展为了谁、发展依靠谁、发展成果由谁共享","制定什么政策、采取什么措施"],"answer":2,"explanation":"以人民为中心的发展思想强调发展为了人民、发展依靠人民、发展成果由人民共享，回答了发展的根本目的和动力问题。故选C。","__sub":"中特"},{"id":"zz-32749","module":"zhengzhi","prompt":"习近平总书记提出实现中华民族伟大复兴的中国梦的场合是：","options":["2012年11月中共十八大报告","2012年11月参观《复兴之路》展览","2017年10月中共十九大报告","2021年7月建党百年大会"],"answer":1,"explanation":"2012年11月29日，习近平总书记参观《复兴之路》展览时首次提出实现中华民族伟大复兴的中国梦，指出实现中华民族伟大复兴就是中华民族近代以来最伟大的梦想。故选B。","__sub":"中特"},{"id":"zz-32750","module":"zhengzhi","prompt":"中国梦的实现路径之一是：","options":["照搬外国模式","依赖外部援助","走中国道路、弘扬中国精神、凝聚中国力量","放弃独立自主"],"answer":2,"explanation":"实现中国梦必须走中国道路、弘扬中国精神、凝聚中国力量，即走中国特色社会主义道路，弘扬以爱国主义为核心的民族精神和以改革创新为核心的时代精神。故选C。","__sub":"中特"},{"id":"zz-32751","module":"zhengzhi","prompt":"全过程人民民主的定位是：","options":["社会主义市场经济的补充形式","社会主义民主政治的本质属性","党内民主的替代形式","基层治理的权宜之计"],"answer":1,"explanation":"党的二十大报告指出，全过程人民民主是社会主义民主政治的本质属性，是最广泛、最真实、最管用的民主。故选B。","__sub":"中特"},{"id":"zz-32752","module":"zhengzhi","prompt":"全面深化改革的总目标是：","options":["实现共同富裕","建立社会主义市场经济体制","建成小康社会","完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化"],"answer":3,"explanation":"2013年中共十八届三中全会提出全面深化改革的总目标是完善和发展中国特色社会主义制度、推进国家治理体系和治理能力现代化。故选D。","__sub":"中特"},{"id":"zz-32753","module":"zhengzhi","prompt":"全面依法治国的总目标是：","options":["建设法治政府","建设中国特色社会主义法治体系、建设社会主义法治国家","建设司法独立体系","建设国际法律中心"],"answer":1,"explanation":"2014年中共十八届四中全会提出全面依法治国的总目标是建设中国特色社会主义法治体系、建设社会主义法治国家。故选B。","__sub":"中特"},{"id":"zz-32754","module":"zhengzhi","prompt":"习近平总书记指出的跳出治乱兴衰历史周期率的第二个答案是：","options":["依法治国","人民监督","自我革命","改革开放"],"answer":2,"explanation":"习近平总书记指出，经过百年奋斗特别是党的十八大以来新的实践，我们党找到了自我革命这一跳出治乱兴衰历史周期率的第二个答案。故选C。","__sub":"中特"},{"id":"zz-32755","module":"zhengzhi","prompt":"毛泽东在延安窑洞对中给出的跳出历史周期率的第一个答案是：","options":["推行土地改革","实行多党竞争","让人民来监督政府","开展整风运动"],"answer":2,"explanation":"1945年毛泽东在延安回答黄炎培的提问时指出，我们已经找到新路，就是让人民来监督政府，政府才不敢松懈，这是跳出历史周期率的第一个答案。故选C。","__sub":"中特"},{"id":"zz-32756","module":"zhengzhi","prompt":"“四个伟大”中起决定性作用的是：","options":["伟大梦想","伟大斗争","伟大事业","党的建设新的伟大工程"],"answer":3,"explanation":"“四个伟大”即伟大斗争、伟大工程、伟大事业、伟大梦想，其中起决定性作用的是党的建设新的伟大工程。故选D。","__sub":"中特"},{"id":"zz-32757","module":"zhengzhi","prompt":"“四个伟大”的内容是：","options":["伟大斗争、伟大工程、伟大事业、伟大梦想","伟大革命、伟大建设、伟大改革、伟大复兴","伟大政党、伟大国家、伟大军队、伟大人民","伟大理想、伟大奋斗、伟大胜利、伟大光荣"],"answer":0,"explanation":"党的十九大提出“四个伟大”，即进行伟大斗争、建设伟大工程、推进伟大事业、实现伟大梦想，四者紧密联系、相互贯通、相互作用。故选A。","__sub":"中特"},{"id":"zz-32758","module":"zhengzhi","prompt":"习近平新时代中国特色社会主义思想在中国特色社会主义理论体系中的定位是：","options":["中特理论体系的边缘补充","独立于中特理论体系的新体系","中特理论体系的替代方案","中国特色社会主义理论体系的重要组成部分"],"answer":3,"explanation":"习近平新时代中国特色社会主义思想是中国特色社会主义理论体系的重要组成部分，实现了马克思主义中国化时代化新的飞跃。故选D。","__sub":"中特"},{"id":"zz-32759","module":"zhengzhi","prompt":"新时代坚持和发展中国特色社会主义的领导力量是：","options":["人民军队","人民群众","中国共产党","统一战线"],"answer":2,"explanation":"新时代坚持和发展中国特色社会主义，必须坚持党对一切工作的领导，中国共产党是最高政治领导力量。故选C。","__sub":"中特"},{"id":"zz-32760","module":"zhengzhi","prompt":"“四个自信”中，更基础、更广泛、更深厚的自信是：","options":["道路自信","文化自信","理论自信","制度自信"],"answer":1,"explanation":"习近平总书记强调，文化自信是更基础、更广泛、更深厚的自信，是一个国家、一个民族发展中更基本、更深沉、更持久的力量。故选B。","__sub":"中特"},{"id":"zz-32761","module":"zhengzhi","prompt":"习近平总书记强调的“国之大者”的核心指向是：","options":["让人民生活幸福","追求经济总量","扩大国际影响","增加财政收入"],"answer":0,"explanation":"习近平总书记强调，让人民生活幸福是“国之大者”，要求各级干部心中始终装着人民，把为民造福作为最重要的政绩。故选A。","__sub":"中特"},{"id":"zz-32762","module":"zhengzhi","prompt":"新时代党的民族工作的主线是：","options":["培养少数民族干部","发展民族地区经济","铸牢中华民族共同体意识","保护民族文化"],"answer":2,"explanation":"新时代党的民族工作以铸牢中华民族共同体意识为主线，引导各族人民牢固树立休戚与共、荣辱与共、生死与共、命运与共的共同体理念。故选C。","__sub":"中特"},{"id":"zz-32763","module":"zhengzhi","prompt":"习近平总书记提出的“人民对美好生活的向往”是：","options":["我们的改革障碍","我们的工作难点","我们的奋斗目标","我们的次要任务"],"answer":2,"explanation":"习近平总书记强调，人民对美好生活的向往就是我们的奋斗目标，体现了党的根本宗旨和以人民为中心的发展思想。故选C。","__sub":"中特"},{"id":"zz-32764","module":"zhengzhi","prompt":"新时代坚持和发展中国特色社会主义的总依据是：","options":["社会主义初级阶段","社会主义市场经济","人民民主专政","改革开放"],"answer":0,"explanation":"新时代坚持和发展中国特色社会主义，必须牢牢把握社会主义初级阶段这个总依据，立足基本国情谋划发展。故选A。","__sub":"中特"},{"id":"zz-32765","module":"zhengzhi","prompt":"习近平新时代中国特色社会主义思想回答的重大时代课题是：","options":["什么是社会主义、怎样建设社会主义","新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义","建设什么样的党、怎样建设党","实现什么样的发展、怎样发展"],"answer":1,"explanation":"习近平新时代中国特色社会主义思想系统回答了新时代坚持和发展什么样的中国特色社会主义、怎样坚持和发展中国特色社会主义等重大时代课题。故选B。","__sub":"中特"},{"id":"zz-32766","module":"zhengzhi","prompt":"新时代坚持和发展中国特色社会主义的基本方略的数量是：","options":["十四个","八个","十个","十六个"],"answer":0,"explanation":"党的十九大提出新时代坚持和发展中国特色社会主义的基本方略共十四条，即“十四个坚持”，是习近平新时代中国特色社会主义思想的重要组成部分。故选A。","__sub":"中特"},{"id":"zz-32767","module":"zhengzhi","prompt":"习近平总书记强调的“两个毫不动摇”是指：","options":["毫不动摇发展市场经济，毫不动摇加强宏观调控","毫不动摇坚持改革开放，毫不动摇坚持四项基本原则","毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展","毫不动摇扩大内需，毫不动摇扩大开放"],"answer":2,"explanation":"“两个毫不动摇”即毫不动摇巩固和发展公有制经济，毫不动摇鼓励、支持、引导非公有制经济发展，是社会主义基本经济制度的重要内容。故选C。","__sub":"中特"},{"id":"zz-32768","module":"zhengzhi","prompt":"习近平总书记提出的“发展全过程人民民主”写入的文件是：","options":["中共十九大报告","中共二十大报告","《习近平谈治国理政》第一卷","十九届四中全会决定"],"answer":1,"explanation":"党的二十大报告提出发展全过程人民民主，保障人民当家作主，将其作为全面建设社会主义现代化国家的重要内容。故选B。","__sub":"中特"},{"id":"zz-32769","module":"zhengzhi","prompt":"新时代推进生态文明建设的理念是：","options":["以牺牲环境换取增长","先发展后治理","绿水青山就是金山银山","限制经济发展"],"answer":2,"explanation":"习近平生态文明思想坚持绿水青山就是金山银山的理念，强调保护生态环境就是保护生产力、改善生态环境就是发展生产力。故选C。","__sub":"中特"},{"id":"zz-32770","module":"zhengzhi","prompt":"习近平总书记提出的人类文明新形态的创造者是：","options":["东亚模式","西方现代化","苏联模式","中国式现代化"],"answer":3,"explanation":"中国式现代化创造了人类文明新形态，它深深植根于中华优秀传统文化，体现科学社会主义的先进本质。故选D。","__sub":"中特"},{"id":"zz-32771","module":"zhengzhi","prompt":"新时代党的建设的主线是：","options":["加强党的长期执政能力建设、先进性和纯洁性建设","加强党的组织建设","加强党的作风建设","加强党的制度建设"],"answer":0,"explanation":"新时代党的建设总要求明确，以加强党的长期执政能力建设、先进性和纯洁性建设为主线，全面推进党的各方面建设。故选A。","__sub":"中特"},{"id":"zz-32772","module":"zhengzhi","prompt":"习近平总书记强调的“江山就是人民、人民就是江山”揭示的关系是：","options":["国家与政党的关系","江山与领土的关系","政权与军队的关系","党领导人民打江山、守江山，守的是人民的心"],"answer":3,"explanation":"习近平总书记指出，江山就是人民、人民就是江山，打江山、守江山，守的是人民的心，深刻揭示了党同人民的血肉联系。故选D。","__sub":"中特"},{"id":"zz-32773","module":"zhengzhi","prompt":"新时代我国对外开放的新格局要求是：","options":["单向引进外资","维持沿海开放格局","收缩对外交往","推动形成全面开放新格局"],"answer":3,"explanation":"党的十九大提出推动形成全面开放新格局，要求以“一带一路”建设为重点，坚持引进来和走出去并重。故选D。","__sub":"中特"},{"id":"zz-32774","module":"zhengzhi","prompt":"习近平总书记提出的“一带一路”是指：","options":["丝绸之路经济带和21世纪海上丝绸之路","长江经济带和京津冀协同发展","西部陆海新通道和东北振兴","经济特区和自贸试验区"],"answer":0,"explanation":"“一带一路”即丝绸之路经济带和21世纪海上丝绸之路，是我国推动构建人类命运共同体的重要实践平台。故选A。","__sub":"中特"},{"id":"zz-32775","module":"zhengzhi","prompt":"习近平新时代中国特色社会主义思想强调的“两个革命”是指：","options":["经济革命和政治革命","社会革命和自我革命","文化革命和科技革命","产业革命和信息革命"],"answer":1,"explanation":"习近平总书记强调，我们党既要领导人民进行伟大的社会革命，又要进行伟大的自我革命，以自我革命引领社会革命。故选B。","__sub":"中特"},{"id":"zz-32776","module":"zhengzhi","prompt":"现行党章修改的会议是：","options":["中共十九届六中全会","中共十九大","中共二十大","中共二十届三中全会"],"answer":2,"explanation":"2022年10月中共二十大通过《中国共产党章程（修正案）》，对党章作出部分修改，体现了党的十九大以来的理论创新和实践发展。故选C。","__sub":"党章党规"},{"id":"zz-32777","module":"zhengzhi","prompt":"党章规定，党的最高理想和最终目标是：","options":["实现现代化","实现共同富裕","建成小康社会","实现共产主义"],"answer":3,"explanation":"党章总纲开宗明义指出，党的最高理想和最终目标是实现共产主义，这是共产党人前进的根本方向。故选D。","__sub":"党章党规"},{"id":"zz-32778","module":"zhengzhi","prompt":"党章规定，年满多少岁的中国工人、农民、军人、知识分子和其他社会阶层的先进分子可以申请加入中国共产党：","options":["二十二岁","十六岁","二十岁","十八岁"],"answer":3,"explanation":"党章第一条规定，年满十八岁的中国工人、农民、军人、知识分子和其他社会阶层的先进分子，承认党的纲领和章程，愿意参加党的一个组织并在其中积极工作、执行党的决议和按期交纳党费的，可以申请加入中国共产党。故选D。","__sub":"党章党规"},{"id":"zz-32779","module":"zhengzhi","prompt":"发展党员必须坚持的原则是：","options":["批量发展的原则","集体吸收的原则","个别吸收的原则","指定发展的原则"],"answer":2,"explanation":"党章规定，发展党员必须经过党的支部，坚持个别吸收的原则，保证新发展党员的质量。故选C。","__sub":"党章党规"},{"id":"zz-32780","module":"zhengzhi","prompt":"申请入党的人应当有几名入党介绍人：","options":["一名正式党员","两名正式党员","两名预备党员","三名正式党员"],"answer":1,"explanation":"党章规定，申请入党的人要填写入党志愿书，要有两名正式党员作介绍人，并经过支部大会讨论通过和上级党组织批准。故选B。","__sub":"党章党规"},{"id":"zz-32781","module":"zhengzhi","prompt":"预备党员的预备期为：","options":["一年","半年","两年","三年"],"answer":0,"explanation":"党章规定，预备党员的预备期为一年，预备期从支部大会通过其为预备党员之日算起。故选A。","__sub":"党章党规"},{"id":"zz-32782","module":"zhengzhi","prompt":"预备党员与正式党员相比，没有的权利是：","options":["申诉权和控告权","知情权和参与权","建议权和批评权","表决权、选举权和被选举权"],"answer":3,"explanation":"党章规定，预备党员的义务同正式党员一样，权利上除了没有表决权、选举权和被选举权以外，也同正式党员一样。故选D。","__sub":"党章党规"},{"id":"zz-32783","module":"zhengzhi","prompt":"入党宣誓誓词中，最后四个字是：","options":["牺牲一切","奋斗终身","永不叛党","严守纪律"],"answer":2,"explanation":"入党宣誓誓词为：我志愿加入中国共产党，拥护党的纲领，遵守党的章程，履行党员义务，执行党的决定，严守党的纪律，保守党的秘密，对党忠诚，积极工作，为共产主义奋斗终身，随时准备为党和人民牺牲一切，永不叛党。故选C。","__sub":"党章党规"},{"id":"zz-32784","module":"zhengzhi","prompt":"党章规定的党员第一项义务是：","options":["认真学习马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想","坚持党和人民的利益高于一切","自觉遵守党的纪律","维护党的团结和统一"],"answer":0,"explanation":"党章第三条规定的党员第一项义务是认真学习马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想等，提高为人民服务的本领。故选A。","__sub":"党章党规"},{"id":"zz-32785","module":"zhengzhi","prompt":"党员如果没有正当理由，连续多长时间不参加党的组织生活或不交纳党费、不做党所分配的工作，就被认为是自行脱党：","options":["两年","三个月","一年","六个月"],"answer":3,"explanation":"党章规定，党员如果没有正当理由，连续六个月不参加党的组织生活，或不交纳党费，或不做党所分配的工作，就被认为是自行脱党。故选D。","__sub":"党章党规"},{"id":"zz-32786","module":"zhengzhi","prompt":"民主集中制在各级党委的具体运用之一是：","options":["实行轮流执政的制度","实行首长个人说了算的制度","实行集体领导和个人分工负责相结合的制度","实行下级全权自治的制度"],"answer":2,"explanation":"民主集中制要求各级党委实行集体领导和个人分工负责相结合的制度，凡属重大问题都要按照集体领导、民主集中、个别酝酿、会议决定的原则作出决定。故选C。","__sub":"党章党规"},{"id":"zz-32787","module":"zhengzhi","prompt":"“四个服从”的内容是：","options":["少数服从多数，多数服从少数，全党服从中央，中央服从群众","个人服从集体，集体服从国家，国家服从人民，人民服从宪法","下级服从上级，地方服从中央，局部服从整体，当前服从长远","党员个人服从党的组织，少数服从多数，下级组织服从上级组织，全党各个组织和全体党员服从党的全国代表大会和中央委员会"],"answer":3,"explanation":"党章规定的“四个服从”是党员个人服从党的组织，少数服从多数，下级组织服从上级组织，全党各个组织和全体党员服从党的全国代表大会和中央委员会。故选D。","__sub":"党章党规"},{"id":"zz-32788","module":"zhengzhi","prompt":"党的最高领导机关是：","options":["中央政治局常委会","中央政治局","党的全国代表大会和它所产生的中央委员会","中央书记处"],"answer":2,"explanation":"党章规定，党的最高领导机关是党的全国代表大会和它所产生的中央委员会，地方各级领导机关是地方各级党的代表大会和它们所产生的委员会。故选C。","__sub":"党章党规"},{"id":"zz-32789","module":"zhengzhi","prompt":"党的全国代表大会每几年举行一次：","options":["五年","三年","四年","六年"],"answer":0,"explanation":"党章规定，党的全国代表大会每五年举行一次，由中央委员会召集，讨论并决定党的重大问题。故选A。","__sub":"党章党规"},{"id":"zz-32790","module":"zhengzhi","prompt":"党的中央委员会每届任期为：","options":["五年","三年","四年","十年"],"answer":0,"explanation":"党章规定，党的中央委员会每届任期五年，全国代表大会如提前或延期举行，其任期也相应改变。故选A。","__sub":"党章党规"},{"id":"zz-32791","module":"zhengzhi","prompt":"党的基层委员会每届任期为：","options":["一年至三年","三年至五年","五年至十年","两年至四年"],"answer":1,"explanation":"党章规定，党的基层委员会每届任期三年至五年，总支部委员会、支部委员会每届任期三年至五年。故选B。","__sub":"党章党规"},{"id":"zz-32792","module":"zhengzhi","prompt":"党的纪律处分共有几种：","options":["四种","五种","六种","七种"],"answer":1,"explanation":"党章规定的党的纪律处分有五种：警告、严重警告、撤销党内职务、留党察看、开除党籍。故选B。","__sub":"党章党规"},{"id":"zz-32793","module":"zhengzhi","prompt":"党内最高的纪律处分是：","options":["严重警告","留党察看","撤销党内职务","开除党籍"],"answer":3,"explanation":"开除党籍是党内最高处分，受到开除党籍处分的党员，五年内不得重新入党。故选D。","__sub":"党章党规"},{"id":"zz-32794","module":"zhengzhi","prompt":"留党察看的期限是：","options":["二年或者三年","三个月或者六个月","一年或者二年","六个月或者一年"],"answer":2,"explanation":"党章规定，留党察看的期限为一年或者二年，最长不超过二年，留党察看期间没有表决权、选举权和被选举权。故选C。","__sub":"党章党规"},{"id":"zz-32795","module":"zhengzhi","prompt":"党的纪律主要包括：","options":["政治纪律、组织纪律、廉洁纪律、群众纪律、工作纪律、生活纪律","思想纪律、学习纪律、工作纪律、生活纪律、财经纪律、保密纪律","政治纪律、经济纪律、文化纪律、社会纪律、生态纪律、外事纪律","组织纪律、人事纪律、财务纪律、安全纪律、保密纪律、宣传纪律"],"answer":0,"explanation":"《中国共产党纪律处分条例》规定，党的纪律主要包括政治纪律、组织纪律、廉洁纪律、群众纪律、工作纪律、生活纪律六大纪律。故选A。","__sub":"党章党规"},{"id":"zz-32796","module":"zhengzhi","prompt":"在党的各项纪律中，最重要、最根本、最关键的纪律是：","options":["廉洁纪律","组织纪律","政治纪律","工作纪律"],"answer":2,"explanation":"政治纪律是党最重要、最根本、最关键的纪律，遵守党的政治纪律是遵守党的全部纪律的重要基础。故选C。","__sub":"党章党规"},{"id":"zz-32797","module":"zhengzhi","prompt":"对党员的纪律处分必须经过的程序是：","options":["支部大会讨论决定，并按照规定程序审批","党委书记个人决定","上级纪委直接宣布","群众投票表决"],"answer":0,"explanation":"党章规定，对党员的纪律处分，必须经过支部大会讨论决定，并按照规定程序报批，坚持实事求是的原则。故选A。","__sub":"党章党规"},{"id":"zz-32798","module":"zhengzhi","prompt":"党章规定，党的领导主要是：","options":["政治、思想和组织的领导","经济、文化和军事的领导","立法、行政和司法的领导","计划、组织和监督的领导"],"answer":0,"explanation":"党章总纲规定，党的领导主要是政治、思想和组织的领导，党要适应改革开放和社会主义现代化建设的要求，加强和改善党的领导。故选A。","__sub":"党章党规"},{"id":"zz-32799","module":"zhengzhi","prompt":"党章规定的党的思想路线是：","options":["解放思想，改革开放，凝聚力量，攻坚克难","一切为了群众，一切依靠群众，从群众中来，到群众中去","一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真理","独立自主，自力更生，艰苦奋斗，勤俭建国"],"answer":2,"explanation":"党章总纲规定，党的思想路线是一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真理。故选C。","__sub":"党章党规"},{"id":"zz-32800","module":"zhengzhi","prompt":"党章规定的党的群众路线是：","options":["一切为了群众，一切依靠群众，从群众中来，到群众中去","一切从实际出发，理论联系实际，实事求是","解放思想，实事求是，与时俱进，求真务实","批评与自我批评，团结与自我团结"],"answer":0,"explanation":"党章总纲规定，党在自己的政治生活中正确地开展批评和自我批评，坚持党的群众路线，即一切为了群众，一切依靠群众，从群众中来，到群众中去。故选A。","__sub":"党章党规"},{"id":"zz-32801","module":"zhengzhi","prompt":"党的三大优良作风是：","options":["改革创新、求真务实、勤政为民","谦虚谨慎、戒骄戒躁、艰苦奋斗","解放思想、实事求是、与时俱进","理论联系实际、密切联系群众、批评与自我批评"],"answer":3,"explanation":"党的三大优良作风是理论联系实际、密切联系群众、批评与自我批评，是党区别于其他政党的显著标志。故选D。","__sub":"党章党规"},{"id":"zz-32802","module":"zhengzhi","prompt":"党的群众路线教育实践活动聚焦解决的突出问题是：","options":["文山会海和迎来送往","形式主义、官僚主义、享乐主义和奢靡之风","懒政怠政和不作为","贪污受贿和权钱交易"],"answer":1,"explanation":"2013年开始的党的群众路线教育实践活动，聚焦解决形式主义、官僚主义、享乐主义和奢靡之风这“四风”问题，密切了党同人民群众的血肉联系。故选B。","__sub":"党章党规"},{"id":"zz-32803","module":"zhengzhi","prompt":"党的作风建设要解决的核心问题是：","options":["提高干部的收入水平","保持党同人民群众的血肉联系","扩大党的组织规模","改善机关办公条件"],"answer":1,"explanation":"党的作风建设以保持党同人民群众的血肉联系为核心问题，党章强调党坚持全心全意为人民服务，坚持群众路线，坚决反对形式主义、官僚主义。故选B。","__sub":"党章党规"},{"id":"zz-32804","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》最近一次修订的施行时间是：","options":["2022年1月1日","2024年1月1日","2023年1月1日","2025年1月1日"],"answer":1,"explanation":"2023年12月，中共中央发布修订后的《中国共产党纪律处分条例》，自2024年1月1日起施行，进一步严明党的纪律。故选B。","__sub":"党章党规"},{"id":"zz-32805","module":"zhengzhi","prompt":"监督执纪“四种形态”中，让“红红脸、出出汗”成为的是：","options":["少数","大多数","常态","极少数"],"answer":2,"explanation":"监督执纪“四种形态”要求让“红红脸、出出汗”成为常态，党纪轻处分、组织调整成为违纪处理的大多数，党纪重处分、重大职务调整的成为少数，严重违纪涉嫌犯罪追究刑事责任的成为极少数。故选C。","__sub":"党章党规"},{"id":"zz-32806","module":"zhengzhi","prompt":"“三会一课”制度中的“一课”是指：","options":["按期召开支部委员会","定期召开支部党员大会","按时上好党课","经常召开党小组会"],"answer":2,"explanation":"“三会一课”制度中的“一课”指按时上好党课，“三会”指支部党员大会、支部委员会、党小组会，是党的组织生活的基本制度。故选C。","__sub":"党章党规"},{"id":"zz-32807","module":"zhengzhi","prompt":"党章规定的党员享有的第一项权利是：","options":["参加党的有关会议，阅读党的有关文件，接受党的教育和培训","在党的会议上和党报党刊上参加讨论","对党的工作提出建议和倡议","行使表决权、选举权，有被选举权"],"answer":0,"explanation":"党章第四条规定的党员第一项权利是参加党的有关会议，阅读党的有关文件，接受党的教育和培训，保障党员的知情权和受教育权。故选A。","__sub":"党章党规"},{"id":"zz-32808","module":"zhengzhi","prompt":"党的各级纪律检查委员会的主要任务是：","options":["负责意识形态宣传","负责干部的选拔任用","负责经济建设规划","维护党的章程和其他党内法规，检查党的路线、方针、政策和决议的执行情况，协助党的委员会推进全面从严治党、加强党风建设和组织协调反腐败工作"],"answer":3,"explanation":"党章规定，党的各级纪律检查委员会的主要任务是维护党的章程和其他党内法规，检查党的路线、方针、政策和决议的执行情况，协助党的委员会推进全面从严治党、加强党风建设和组织协调反腐败工作。故选D。","__sub":"党章党规"},{"id":"zz-32809","module":"zhengzhi","prompt":"党委议事决策实行的“十六字”原则是：","options":["集体领导、分工负责、层层把关、逐级上报","集体领导、民主集中、个别酝酿、会议决定","民主协商、广泛参与、充分酝酿、投票表决","统一领导、分级管理、权责结合、注重实效"],"answer":1,"explanation":"党委议事和决策坚持集体领导、民主集中、个别酝酿、会议决定的“十六字”原则，保证决策的科学化、民主化。故选B。","__sub":"党章党规"},{"id":"zz-32810","module":"zhengzhi","prompt":"发展党员工作的“十六字”方针是：","options":["积极培养、严格把关、稳步发展、注重实效","坚持标准、保证质量、改善结构、慎重发展","控制总量、优化结构、提高质量、发挥作用","成熟一个、发展一个、教育一个、提高一个"],"answer":2,"explanation":"发展党员工作坚持控制总量、优化结构、提高质量、发挥作用的“十六字”方针，保持党员队伍的先进性和纯洁性。故选C。","__sub":"党章党规"},{"id":"zz-32811","module":"zhengzhi","prompt":"党章规定，中国共产党是中国特色社会主义事业的：","options":["外围组织","参政力量","监督机构","领导核心"],"answer":3,"explanation":"党章总纲规定，中国共产党是中国工人阶级的先锋队，同时是中国人民和中华民族的先锋队，是中国特色社会主义事业的领导核心。故选D。","__sub":"党章党规"},{"id":"zz-32812","module":"zhengzhi","prompt":"党章规定的党的行动指南包括马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观和：","options":["习近平新时代中国特色社会主义思想","新时代党的创新理论纲要","社会主义核心价值体系","党的基本路线"],"answer":0,"explanation":"党章总纲规定，中国共产党以马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想作为自己的行动指南。故选A。","__sub":"党章党规"},{"id":"zz-32813","module":"zhengzhi","prompt":"党章规定，党除了工人阶级和最广大人民群众的利益，没有自己：","options":["固定的经费","独立的纲领","特殊的利益","单独的纪律"],"answer":2,"explanation":"党章总纲规定，党除了工人阶级和最广大人民群众的利益，没有自己特殊的利益，这体现了党的性质和宗旨的统一。故选C。","__sub":"党章党规"},{"id":"zz-32814","module":"zhengzhi","prompt":"党章规定，党在任何时候都把群众利益放在：","options":["次要位置","第二位","第一位","参考位置"],"answer":2,"explanation":"党章总纲强调，党在任何时候都把群众利益放在第一位，同群众同甘共苦，保持最密切的联系。故选C。","__sub":"党章党规"},{"id":"zz-32815","module":"zhengzhi","prompt":"党章规定，我们党的最大政治优势是密切联系群众，党执政后的最大危险是：","options":["消极腐败","能力不足","脱离群众","精神懈怠"],"answer":2,"explanation":"党章总纲指出，我们党的最大政治优势是密切联系群众，党执政后的最大危险是脱离群众，党风问题关系党的生死存亡。故选C。","__sub":"党章党规"},{"id":"zz-32816","module":"zhengzhi","prompt":"党章规定，党的建设的四项基本要求之一是坚持：","options":["依法治国方略","改革开放方针","市场经济体制","党的基本路线"],"answer":3,"explanation":"党章总纲规定党的建设必须坚决实现四项基本要求，第一项就是坚持党的基本路线，全党要用基本路线统一思想、统一行动。故选D。","__sub":"党章党规"},{"id":"zz-32817","module":"zhengzhi","prompt":"党章规定的党的建设四项基本要求中，与思想路线相关的是：","options":["坚持解放思想，实事求是，与时俱进，求真务实","坚持民主集中制","坚持全心全意为人民服务","坚持党的基本路线"],"answer":0,"explanation":"党章总纲规定的四项基本要求包括坚持党的基本路线、坚持解放思想实事求是与时俱进求真务实、坚持全心全意为人民服务、坚持民主集中制，其中第二项与思想路线相关。故选A。","__sub":"党章党规"},{"id":"zz-32818","module":"zhengzhi","prompt":"党章规定的党的建设四项基本要求中，涉及组织原则的是：","options":["坚持全心全意为人民服务","坚持党的基本路线","坚持解放思想实事求是","坚持民主集中制"],"answer":3,"explanation":"党章总纲规定，党的建设必须坚持民主集中制，民主集中制是民主基础上的集中和集中指导下的民主相结合。故选D。","__sub":"党章党规"},{"id":"zz-32819","module":"zhengzhi","prompt":"党章规定，党要适应改革开放和社会主义现代化建设的要求，坚持科学执政、民主执政、：","options":["高效执政","廉洁执政","依法执政","为民执政"],"answer":2,"explanation":"党章总纲规定，党要适应改革开放和社会主义现代化建设的要求，坚持科学执政、民主执政、依法执政，加强和改善党的领导。故选C。","__sub":"党章党规"},{"id":"zz-32820","module":"zhengzhi","prompt":"党章规定，我国社会主义建设的根本任务是：","options":["实现共同富裕","建成小康社会","进一步解放生产力，发展生产力，逐步实现社会主义现代化","建设精神文明"],"answer":2,"explanation":"党章总纲规定，我国社会主义建设的根本任务是进一步解放生产力，发展生产力，逐步实现社会主义现代化，并且为此而改革生产关系和上层建筑中不适应生产力发展的方面和环节。故选C。","__sub":"党章党规"},{"id":"zz-32821","module":"zhengzhi","prompt":"党章规定，必须坚持和完善的基本经济制度是：","options":["公有制为主体、多种所有制经济共同发展","私有制为主体","全民所有制单一发展","计划经济体制"],"answer":0,"explanation":"党章总纲规定，必须坚持和完善公有制为主体、多种所有制经济共同发展的基本经济制度，坚持和完善按劳分配为主体、多种分配方式并存的分配制度。故选A。","__sub":"党章党规"},{"id":"zz-32822","module":"zhengzhi","prompt":"党章规定，中国共产党同各民主党派实行的方针是：","options":["长期共存、互相监督、肝胆相照、荣辱与共","轮流执政、相互制衡","全面领导、直接管理","各自为政、互不干涉"],"answer":0,"explanation":"党章总纲规定，中国共产党同全国各民族工人、农民、知识分子团结在一起，同各民主党派、无党派人士团结在一起，实行“长期共存、互相监督、肝胆相照、荣辱与共”的方针。故选A。","__sub":"党章党规"},{"id":"zz-32823","module":"zhengzhi","prompt":"党章规定，我国要形成的社会主义民族关系是：","options":["平等团结互助和谐","独立自主平等互利","团结奋进共同繁荣","和睦相处共谋发展"],"answer":0,"explanation":"党章总纲规定，中国共产党坚持和完善民族区域自治制度，铸牢中华民族共同体意识，发展平等团结互助和谐的社会主义民族关系。故选A。","__sub":"党章党规"},{"id":"zz-32824","module":"zhengzhi","prompt":"党章规定，党尊重和保障的宗教政策是：","options":["政教合一","宗教信仰自由","国教优先","取缔一切宗教"],"answer":1,"explanation":"党章总纲规定，党实行宗教信仰自由政策，团结广大信教群众，发挥他们在促进经济社会发展中的积极作用。故选B。","__sub":"党章党规"},{"id":"zz-32825","module":"zhengzhi","prompt":"党章总纲规定，我国坚持的外交政策是：","options":["优先发展大国外交政策","结盟对抗的外交政策","不干涉内政的孤立政策","独立自主的和平外交政策"],"answer":3,"explanation":"党章总纲规定，中国共产党坚持独立自主的和平外交政策，坚持和平发展道路，坚持互利共赢的开放战略。「和平共处五项原则」是我国对外关系的基本准则，与外交政策表述不同，A、B、C项均非党章表述。故选D。","__sub":"党章党规"},{"id":"zz-32826","module":"zhengzhi","prompt":"党章规定，发展社会主义民主政治，建设社会主义政治文明，要健全的制度是：","options":["等级制度，规范上下关系","集权制度，强化行政命令","民主制度，丰富民主形式","协商制度，取消选举程序"],"answer":2,"explanation":"党章总纲规定，发展社会主义民主政治，建设社会主义政治文明，要坚持和完善人民代表大会制度等制度，健全民主制度，丰富民主形式，拓宽民主渠道。故选C。","__sub":"党章党规"},{"id":"zz-32827","module":"zhengzhi","prompt":"党章规定，建设社会主义精神文明要实行的方针是：","options":["以德治取代法治","以人治代替法治","依法治国和以德治国相结合","以经济手段治理一切"],"answer":2,"explanation":"党章总纲规定，建设社会主义精神文明，实行依法治国和以德治国相结合，提高全民族的思想道德素质和科学文化素质。故选C。","__sub":"党章党规"},{"id":"zz-32828","module":"zhengzhi","prompt":"党章规定，党必须在什么范围内活动：","options":["党内规章","党的纪律","行政命令","宪法和法律"],"answer":3,"explanation":"党章总纲规定，党必须在宪法和法律范围内活动，这是党治国理政的基本要求，也是依法执政的体现。故选D。","__sub":"党章党规"},{"id":"zz-32829","module":"zhengzhi","prompt":"党章规定，党的领导主要是政治、思想和组织的领导，其中政治领导的核心是：","options":["包办一切行政事务","任免所有干部","制定正确的路线方针政策","直接指挥司法机关"],"answer":2,"explanation":"党章总纲规定党的领导主要是政治、思想和组织的领导，政治领导的核心是制定正确的路线方针政策，并保证其贯彻执行。故选C。","__sub":"党章党规"},{"id":"zz-32830","module":"zhengzhi","prompt":"党章规定，党的思想路线的核心是：","options":["实事求是","解放思想","与时俱进","求真务实"],"answer":0,"explanation":"党章总纲规定，党的思想路线是一切从实际出发，理论联系实际，实事求是，在实践中检验真理和发展真理，其中实事求是是核心。故选A。","__sub":"党章党规"},{"id":"zz-32831","module":"zhengzhi","prompt":"党章规定，党的建设的新的伟大工程要以什么为统领：","options":["党的政治建设","党的组织建设","党的作风建设","党的制度建设"],"answer":0,"explanation":"党章总纲规定，新时代党的建设要以加强党的长期执政能力建设、先进性和纯洁性建设为主线，以党的政治建设为统领，全面推进党的各项建设。故选A。","__sub":"党章党规"},{"id":"zz-32832","module":"zhengzhi","prompt":"党章规定，党的建设总体布局中，要把什么贯穿其中：","options":["经济建设","制度建设","文化建设","社会建设"],"answer":1,"explanation":"党章总纲规定，全面推进党的政治建设、思想建设、组织建设、作风建设、纪律建设，把制度建设贯穿其中，深入推进反腐败斗争。故选B。","__sub":"党章党规"},{"id":"zz-32833","module":"zhengzhi","prompt":"党章规定，全面从严治党永恒的课题是：","options":["加强党的长期执政能力建设、先进性和纯洁性建设","扩大党的组织规模","提高干部待遇水平","增加党员数量"],"answer":0,"explanation":"党章总纲规定，以加强党的长期执政能力建设、先进性和纯洁性建设为主线，这是新时代党的建设必须长期坚持的主线。故选A。","__sub":"党章党规"},{"id":"zz-32834","module":"zhengzhi","prompt":"党章规定，党坚持的干部路线是：","options":["群众选干部","党管干部","领导定干部","考试定干部"],"answer":1,"explanation":"党章总纲规定，党坚持党管干部原则，按照德才兼备、以德为先的原则选拔干部，努力实现干部队伍的革命化、年轻化、知识化、专业化。故选B。","__sub":"党章党规"},{"id":"zz-32835","module":"zhengzhi","prompt":"党章规定，党的各级领导干部必须具备的基本条件之一是具有：","options":["显赫的家庭背景","雄厚的个人财产","履行职责所需要的理论水平和专业能力","广泛的海外关系"],"answer":2,"explanation":"党章第三十四条规定，党的各级领导干部必须具备的基本条件之一是具有履行职责所需要的马克思列宁主义、毛泽东思想、邓小平理论等的理论水平，努力用马克思主义立场、观点、方法分析和解决实际问题。故选C。","__sub":"党章党规"},{"id":"zz-32836","module":"zhengzhi","prompt":"党章规定，党的干部要正确行使人民赋予的权力，做到：","options":["任人唯亲，结党营私","独断专行，以权谋私","坚持原则，依法办事，清正廉洁，勤政为民","贪图享受，脱离群众"],"answer":2,"explanation":"党章第三十五条规定，党的各级领导干部必须坚持原则，依法办事，清正廉洁，勤政为民，做到自重自省自警自励，反对形式主义、官僚主义、享乐主义和奢靡之风。故选C。","__sub":"党章党规"},{"id":"zz-32837","module":"zhengzhi","prompt":"党章规定，党的干部职务：","options":["一经任命终身有效","都不是终身的，都可以变动或解除","由个人决定去留","只升不降"],"answer":1,"explanation":"党章第三十六条规定，党的干部职务都不是终身的，都可以变动或者解除，年龄和健康状况不适宜继续担任工作的，应当按照国家的规定退离休。故选B。","__sub":"党章党规"},{"id":"zz-32838","module":"zhengzhi","prompt":"党章规定，党的中央军事委员会组成人员由谁决定：","options":["中央政治局常委会单独决定","全国人民代表大会","国务院","中央委员会"],"answer":3,"explanation":"党章规定，党的中央军事委员会组成人员由中央委员会决定，中央军事委员会实行主席负责制。故选D。","__sub":"党章党规"},{"id":"zz-32839","module":"zhengzhi","prompt":"党章规定，中央委员会总书记必须从什么职务中产生：","options":["中央书记处书记中产生","中央委员中任意产生","中央政治局委员中任意产生","中央政治局常务委员会委员"],"answer":3,"explanation":"党章规定，中央委员会总书记必须从中央政治局常务委员会委员中产生，负责召集中央政治局会议和政治局常务委员会会议，并主持中央书记处的工作。故选D。","__sub":"党章党规"},{"id":"zz-32840","module":"zhengzhi","prompt":"党章规定，在中央和地方国家机关、人民团体等领导机关中可以成立：","options":["党总支","党委","党组","党支部"],"answer":2,"explanation":"党章规定，在中央和地方国家机关、人民团体、经济组织、文化组织和其他非党组织的领导机关中，可以成立党组，发挥把方向、管大局、保落实的领导作用。故选C。","__sub":"党章党规"},{"id":"zz-32841","module":"zhengzhi","prompt":"党章规定，党组设书记，必要时还可以设：","options":["候补书记","名誉书记","副书记","代理书记"],"answer":2,"explanation":"党章规定，党组设书记，必要时还可以设副书记，党组书记一般由本单位领导班子主要负责人担任。故选C。","__sub":"党章党规"},{"id":"zz-32842","module":"zhengzhi","prompt":"党章规定，中国共产主义青年团是中国共产党领导的先进青年的：","options":["行政机关，是党的执行机构","群团组织，是党的助手和后备军","监督机构，是党的检查机关","经济组织，是党的经营实体"],"answer":1,"explanation":"党章规定，中国共产主义青年团是中国共产党领导的先进青年的群团组织，是广大青年在实践中学习中国特色社会主义和共产主义的学校，是党的助手和后备军。故选B。","__sub":"党章党规"},{"id":"zz-32843","module":"zhengzhi","prompt":"党章规定，中国共产党党徽的图案是：","options":["五角星和麦穗组成的图案","镰刀和锤头组成的图案","红旗和火炬组成的图案","锤头和齿轮组成的图案"],"answer":1,"explanation":"党章规定，中国共产党党徽为镰刀和锤头组成的图案，象征着工人阶级和农民阶级的联盟。故选B。","__sub":"党章党规"},{"id":"zz-32844","module":"zhengzhi","prompt":"党章规定，中国共产党党旗是：","options":["旗面缀有金黄色党徽图案的红旗","旗面缀有五角星图案的红旗","旗面缀有镰刀锤头的蓝旗","旗面缀有国徽图案的红旗"],"answer":0,"explanation":"党章规定，中国共产党党旗为旗面缀有金黄色党徽图案的红旗，是党的象征和标志。故选A。","__sub":"党章党规"},{"id":"zz-32845","module":"zhengzhi","prompt":"党章规定，预备党员入党宣誓应当面向：","options":["党旗","国旗","军旗","团旗"],"answer":0,"explanation":"党章规定，预备党员必须面向党旗进行入党宣誓，这是发展党员工作的重要程序，体现了入党的庄严性和严肃性。故选A。","__sub":"党章党规"},{"id":"zz-32846","module":"zhengzhi","prompt":"党章规定，党员的义务共有：","options":["十项","六项","八项","十二项"],"answer":2,"explanation":"党章第三条规定，党员必须履行八项义务，包括认真学习理论、贯彻基本路线、坚持党和人民利益高于一切、自觉遵守党的纪律等。故选C。","__sub":"党章党规"},{"id":"zz-32847","module":"zhengzhi","prompt":"党章规定，党员的权利共有：","options":["八项","六项","十项","十二项"],"answer":0,"explanation":"党章第四条规定，党员享有八项权利，包括参加党的有关会议、参加党的政策问题讨论、对党的工作提出建议和倡议等。故选A。","__sub":"党章党规"},{"id":"zz-32848","module":"zhengzhi","prompt":"党章规定的党员第二项义务是：","options":["认真学习马克思列宁主义等理论","贯彻执行党的基本路线和各项方针、政策，带头参加改革开放和社会主义现代化建设","坚持党和人民的利益高于一切","自觉遵守党的纪律"],"answer":1,"explanation":"党章第三条规定的党员第二项义务是贯彻执行党的基本路线和各项方针、政策，带头参加改革开放和社会主义现代化建设，带动群众为经济发展和社会进步艰苦奋斗。故选B。","__sub":"党章党规"},{"id":"zz-32849","module":"zhengzhi","prompt":"党章规定的党员第三项义务是：","options":["坚持党和人民的利益高于一切，个人利益服从党和人民的利益，吃苦在前，享受在后，克己奉公，多做贡献","认真学习党的理论","维护党的团结和统一","发扬社会主义新风尚"],"answer":0,"explanation":"党章第三条规定的党员第三项义务要求党员坚持党和人民的利益高于一切，吃苦在前，享受在后，克己奉公，绝对不得假公济私，损公肥私。故选A。","__sub":"党章党规"},{"id":"zz-32850","module":"zhengzhi","prompt":"党章规定的党员第四项义务强调自觉遵守党的纪律，首先是：","options":["组织纪律","党的政治纪律和政治规矩","廉洁纪律","工作纪律"],"answer":1,"explanation":"党章第三条规定的党员第四项义务是自觉遵守党的纪律，首先是党的政治纪律和政治规矩，模范遵守国家的法律法规。故选B。","__sub":"党章党规"},{"id":"zz-32851","module":"zhengzhi","prompt":"党章规定的党员第五项义务是：","options":["维护党的团结和统一，对党忠诚老实，言行一致","坚持党和人民的利益高于一切","密切联系群众","开展批评和自我批评"],"answer":0,"explanation":"党章第三条规定的党员第五项义务是维护党的团结和统一，对党忠诚老实，言行一致，坚决反对一切派别组织和小集团活动。故选A。","__sub":"党章党规"},{"id":"zz-32852","module":"zhengzhi","prompt":"党章规定的党员第六项义务是：","options":["切实开展批评和自我批评，勇于揭露和纠正违反党的原则的言行","认真学习党的理论","自觉遵守党的纪律","发扬社会主义新风尚"],"answer":0,"explanation":"党章第三条规定的党员第六项义务是切实开展批评和自我批评，勇于揭露和纠正违反党的原则的言行和工作中的缺点、错误，坚决同消极腐败现象作斗争。故选A。","__sub":"党章党规"},{"id":"zz-32853","module":"zhengzhi","prompt":"党章规定的党员第七项义务是：","options":["维护党的团结和统一","密切联系群众，向群众宣传党的主张","坚持党和人民的利益高于一切","贯彻执行党的基本路线"],"answer":1,"explanation":"党章第三条规定的党员第七项义务是密切联系群众，向群众宣传党的主张，遇事同群众商量，及时向党反映群众的意见和要求，维护群众的正当利益。故选B。","__sub":"党章党规"},{"id":"zz-32854","module":"zhengzhi","prompt":"党章规定的党员第八项义务是：","options":["密切联系群众","发扬社会主义新风尚，带头实践社会主义核心价值观和社会主义荣辱观","维护党的团结和统一","自觉遵守党的纪律"],"answer":1,"explanation":"党章第三条规定的党员第八项义务是发扬社会主义新风尚，带头实践社会主义核心价值观和社会主义荣辱观，弘扬中华民族传统美德，为了保护国家和人民的利益挺身而出。故选B。","__sub":"党章党规"},{"id":"zz-32855","module":"zhengzhi","prompt":"党章规定的党员第二项权利是：","options":["在党的会议上和党报党刊上，参加关于党的政策问题的讨论","参加党的有关会议","对党的工作提出建议和倡议","行使表决权、选举权"],"answer":0,"explanation":"党章第四条规定的党员第二项权利是在党的会议上和党报党刊上，参加关于党的政策问题的讨论，保障党员的参与权。故选A。","__sub":"党章党规"},{"id":"zz-32856","module":"zhengzhi","prompt":"党章规定的党员第三项权利是：","options":["提出请求、申诉和控告","参加党的政策问题讨论","有根据地批评党的任何组织和党员","对党的工作提出建议和倡议"],"answer":3,"explanation":"党章第四条规定的党员第三项权利是对党的工作提出建议和倡议，鼓励党员为党的事业建言献策。故选D。","__sub":"党章党规"},{"id":"zz-32857","module":"zhengzhi","prompt":"党章规定的党员第四项权利是：","options":["行使表决权、选举权","对党的工作提出建议和倡议","参加党的政策问题讨论","在党的会议上有根据地批评党的任何组织和任何党员"],"answer":3,"explanation":"党章第四条规定的党员第四项权利是在党的会议上有根据地批评党的任何组织和任何党员，向党负责地揭发、检举任何组织和任何党员违法乱纪的事实。故选D。","__sub":"党章党规"},{"id":"zz-32858","module":"zhengzhi","prompt":"党章规定的党员第六项权利是：","options":["在党组织讨论决定对党员的党纪处分或作出鉴定时，本人有权参加和申辩","对党的工作提出建议和倡议","参加党的政策问题讨论","行使表决权、选举权"],"answer":0,"explanation":"党章第四条规定的党员第六项权利是在党组织讨论决定对党员的党纪处分或作出鉴定时，本人有权参加和申辩，其他党员可以为他作证和辩护。故选A。","__sub":"党章党规"},{"id":"zz-32859","module":"zhengzhi","prompt":"党章规定的党员第七项权利是：","options":["在党组织讨论决定对党员的党纪处分时本人有权参加和申辩","对党的决议和政策如有不同意见，在坚决执行的前提下，可以声明保留，并且可以把自己的意见向党的上级组织直至中央提出","对党的工作提出建议和倡议","行使表决权、选举权"],"answer":1,"explanation":"党章第四条规定的党员第七项权利是对党的决议和政策如有不同意见，在坚决执行的前提下，可以声明保留，并且可以把自己的意见向党的上级组织直至中央提出。故选B。","__sub":"党章党规"},{"id":"zz-32860","module":"zhengzhi","prompt":"党章规定，党员的入党时间从何时算起：","options":["入党宣誓之日","上级党委批准之日","支部大会通过其为预备党员之日","转为正式党员之日"],"answer":2,"explanation":"党章规定，预备党员的预备期从支部大会通过其为预备党员之日算起，党员的党龄从预备期满转为正式党员之日算起。故选C。","__sub":"党章党规"},{"id":"zz-32861","module":"zhengzhi","prompt":"党章规定，党员的党龄从何时算起：","options":["递交入党申请书之日","预备期满转为正式党员之日","被确定为入党积极分子之日","支部大会通过其为预备党员之日"],"answer":1,"explanation":"党章规定，党员的党龄从预备期满转为正式党员之日算起，与入党时间（预备期起算日）相区别。故选B。","__sub":"党章党规"},{"id":"zz-32862","module":"zhengzhi","prompt":"党章规定，预备党员转正需要经过的程序是：","options":["党委书记个人批准","本人提出转正申请，经支部大会讨论通过，报上级党组织批准","支部委员会直接宣布","群众投票表决"],"answer":1,"explanation":"党章规定，预备党员预备期满，党支部应当及时讨论其能否转为正式党员，认真履行党员义务、具备党员条件的应当按期转为正式党员，需本人提出转正申请，经支部大会讨论通过，报上级党组织批准。故选B。","__sub":"党章党规"},{"id":"zz-32863","module":"zhengzhi","prompt":"党章规定，党员有退党的自由，要求退党的党员应当：","options":["自动失去党员身份无需程序","由党委书记直接批准","报中央委员会备案","经支部大会讨论后宣布除名"],"answer":3,"explanation":"党章规定，党员有退党的自由，要求退党的党员，经支部大会讨论后宣布除名，并报上级党组织备案。故选D。","__sub":"党章党规"},{"id":"zz-32864","module":"zhengzhi","prompt":"党章规定，对缺乏革命意志、不履行党员义务、不符合党员条件的党员，经教育仍无转变的，应当：","options":["留党察看","直接开除党籍","劝他退党","党内警告"],"answer":2,"explanation":"党章规定，党员缺乏革命意志，不履行党员义务，不符合党员条件，党的支部应当对他进行教育，要求他限期改正，经教育仍无转变的，应当劝他退党。故选C。","__sub":"党章党规"},{"id":"zz-32865","module":"zhengzhi","prompt":"党章规定，对劝而不退的党员应当：","options":["予以除名","继续保留党籍","留党察看","降为预备党员"],"answer":0,"explanation":"党章规定，党员应当劝其退党而本人坚持不退的，应当提交支部大会讨论，决定把他除名，并报上级党组织批准。故选A。","__sub":"党章党规"},{"id":"zz-32866","module":"zhengzhi","prompt":"党章规定，党员严重违犯党纪、本人拒不接受党组织教育处理的，应当：","options":["留党察看","劝其退党","开除党籍","严重警告"],"answer":2,"explanation":"党章规定，党员严重违犯党纪、本人拒不接受党组织教育处理的，应当开除党籍，这是严肃党的纪律的必然要求。故选C。","__sub":"党章党规"},{"id":"zz-32867","module":"zhengzhi","prompt":"党章规定的党的全国代表大会职权之一是：","options":["批准省级区划调整","任免国务院总理","决定国家预算","修改党的章程"],"answer":3,"explanation":"党章规定的党的全国代表大会职权包括听取和审查中央委员会的报告、审查中央纪律检查委员会的报告、讨论并决定党的重大问题、修改党的章程、选举中央委员会、选举中央纪律检查委员会。故选D。","__sub":"党章党规"},{"id":"zz-32868","module":"zhengzhi","prompt":"党章规定，党的全国代表大会闭会期间，领导党的全部工作、对外代表中国共产党的是：","options":["中央政治局","中央委员会","中央书记处","国务院"],"answer":1,"explanation":"党章规定，在全国代表大会闭会期间，中央委员会执行全国代表大会的决议，领导党的全部工作，对外代表中国共产党。故选B。","__sub":"党章党规"},{"id":"zz-32869","module":"zhengzhi","prompt":"党章规定，党的省、自治区、直辖市的代表大会每几年举行一次：","options":["五年","三年","四年","六年"],"answer":0,"explanation":"党章规定，党的省、自治区、直辖市的代表大会，设区的市和自治州的代表大会，县（旗、自治县、不设区的市和市辖区）的代表大会，每五年举行一次。故选A。","__sub":"党章党规"},{"id":"zz-32870","module":"zhengzhi","prompt":"党章规定，党的基层组织是党在社会基层组织中的：","options":["联络站点","行政机关","派出机构","战斗堡垒"],"answer":3,"explanation":"党章规定，党的基层组织是党在社会基层组织中的战斗堡垒，是党的全部工作和战斗力的基础。故选D。","__sub":"党章党规"},{"id":"zz-32871","module":"zhengzhi","prompt":"党章规定，凡是有正式党员几人以上的基层单位，都应当成立党的基层组织：","options":["十人","五人","七人","三人"],"answer":3,"explanation":"党章规定，企业、农村、机关、学校、科研院所、街道社区、社会组织、人民解放军连队和其他基层单位，凡是有正式党员三人以上的，都应当成立党的基层组织。故选D。","__sub":"党章党规"},{"id":"zz-32872","module":"zhengzhi","prompt":"党章规定，党的支部委员会由谁选举产生：","options":["党委书记指定","上级党委任命","党员大会","群众代表推选"],"answer":2,"explanation":"党章规定，党的支部委员会由党员大会选举产生，代表会议产生的委员会由代表会议选举产生。故选C。","__sub":"党章党规"},{"id":"zz-32873","module":"zhengzhi","prompt":"党章规定，党的基层组织的基本任务之一是：","options":["审批政府预算","制定国家法律法规","宣传和执行党的路线方针政策","管理国有资产"],"answer":2,"explanation":"党章规定的党的基层组织基本任务包括宣传和执行党的路线方针政策，教育党员和群众自觉抵制不良倾向，组织党员认真学习等。故选C。","__sub":"党章党规"},{"id":"zz-32874","module":"zhengzhi","prompt":"党章规定，党的纪律是党的各级组织和全体党员必须遵守的：","options":["参考意见","道德规范","工作流程","行为规则"],"answer":3,"explanation":"党章规定，党的纪律是党的各级组织和全体党员必须遵守的行为规则，是维护党的团结统一、完成党的任务的保证。故选D。","__sub":"党章党规"},{"id":"zz-32875","module":"zhengzhi","prompt":"党章规定，党组织必须严格执行和维护党的纪律，共产党员必须：","options":["在监督下遵守纪律","选择性遵守党的纪律","自觉接受党的纪律的约束","经批准后遵守纪律"],"answer":2,"explanation":"党章规定，党组织必须严格执行和维护党的纪律，共产党员必须自觉接受党的纪律的约束，这是党员的基本义务。故选C。","__sub":"党章党规"},{"id":"zz-32876","module":"zhengzhi","prompt":"党章规定，对严重违犯党纪、本身又不能纠正的党组织，上一级党委在查明核实后，应当根据情节严重的程度，予以：","options":["改组或解散","警告或严重警告","罚款或通报","合并或撤销"],"answer":0,"explanation":"党章规定，对严重违犯党纪、本身又不能纠正的党组织，上一级党委在查明核实后，应当根据情节严重的程度，作出进行改组或予以解散的决定。故选A。","__sub":"党章党规"},{"id":"zz-32877","module":"zhengzhi","prompt":"党章规定，党的中央纪律检查委员会在谁领导下进行工作：","options":["党的中央委员会","全国人民代表大会","国务院","中央政治局常委会单独领导"],"answer":0,"explanation":"党章规定，党的中央纪律检查委员会在党的中央委员会领导下进行工作，地方各级纪律检查委员会在同级党的委员会和上级纪律检查委员会双重领导下进行工作。故选A。","__sub":"党章党规"},{"id":"zz-32878","module":"zhengzhi","prompt":"党章规定，地方各级纪律检查委员会实行的领导体制是：","options":["同级政府领导","垂直单一领导","同级党的委员会和上级纪律检查委员会双重领导","同级人大领导"],"answer":2,"explanation":"党章规定，地方各级纪律检查委员会在同级党的委员会和上级纪律检查委员会双重领导下进行工作，这保证了纪检工作的独立性和权威性。故选C。","__sub":"党章党规"},{"id":"zz-32879","module":"zhengzhi","prompt":"党章规定，党的纪律检查机关的职责是：","options":["计划、组织、协调","立法、执法、司法","决策、执行、反馈","监督、执纪、问责"],"answer":3,"explanation":"党章规定，党的各级纪律检查委员会的职责是监督、执纪、问责，协助党委推进全面从严治党、加强党风建设和组织协调反腐败工作。故选D。","__sub":"党章党规"},{"id":"zz-32880","module":"zhengzhi","prompt":"党章规定，党的各级领导干部必须具备的基本条件中，政治上的要求是：","options":["具有海外留学经历","具有履行职责所需要的马克思主义理论水平","具有高级职称","具有丰富经商经验"],"answer":1,"explanation":"党章第三十四条规定，党的各级领导干部必须具有履行职责所需要的马克思列宁主义、毛泽东思想、邓小平理论等的理论水平，努力用马克思主义立场、观点、方法分析和解决实际问题。故选B。","__sub":"党章党规"},{"id":"zz-32881","module":"zhengzhi","prompt":"党章规定，选拔干部要坚持的原则是：","options":["德才兼备、以德为先","唯才是举、不问品德","论资排辈、平衡照顾","任人唯亲、近水楼台"],"answer":0,"explanation":"党章总纲规定，党按照德才兼备、以德为先的原则选拔干部，坚持五湖四海、任人唯贤，反对任人唯亲。故选A。","__sub":"党章党规"},{"id":"zz-32882","module":"zhengzhi","prompt":"党章规定，党的干部要努力实现的“四化”是：","options":["现代化、信息化、城镇化、市场化","革命化、年轻化、知识化、专业化","规范化、制度化、程序化、法治化","科学化、民主化、法治化、智能化"],"answer":1,"explanation":"党章总纲规定，党努力实现干部队伍的革命化、年轻化、知识化、专业化，建设一支高素质的干部队伍。故选B。","__sub":"党章党规"},{"id":"zz-32883","module":"zhengzhi","prompt":"党章规定，党的中央和地方各级委员会的委员、候补委员的党龄要求是：","options":["十年以上","三年以上","七年以上","五年以上"],"answer":3,"explanation":"党章规定，党的中央和地方各级委员会委员、候补委员必须有五年以上的党龄，保证领导机关成员的政治成熟和经验积累。故选D。","__sub":"党章党规"},{"id":"zz-32884","module":"zhengzhi","prompt":"党章规定，党的各级委员会向同级的代表大会负责并：","options":["报告工作","请示经费","申请编制","汇报生活"],"answer":0,"explanation":"党章规定，党的各级委员会向同级的代表大会负责并报告工作，接受代表大会的监督，体现了代表大会的最高领导机关地位。故选A。","__sub":"党章党规"},{"id":"zz-32885","module":"zhengzhi","prompt":"党章规定，党的中央政治局、中央政治局常务委员会和中央委员会总书记由谁选举产生：","options":["上届中央委员会指定","党的全国代表大会直接选举","中央书记处提名","中央委员会全体会议"],"answer":3,"explanation":"党章规定，中央政治局、中央政治局常务委员会和中央委员会总书记，由中央委员会全体会议选举，保证党中央领导机构的权威性。故选D。","__sub":"党章党规"},{"id":"zz-32886","module":"zhengzhi","prompt":"党章规定，党的市（旗、区）辖区和不设区的市的人民政府党组的设立：","options":["由人大决定是否成立","一律不得成立党组","必须成立党组","经批准可以成立党组"],"answer":3,"explanation":"党章规定，在中央和地方国家机关、人民团体、经济组织、文化组织和其他非党组织的领导机关中，可以成立党组，具体设立须经批准。故选D。","__sub":"党章党规"},{"id":"zz-32887","module":"zhengzhi","prompt":"党章规定，党的基层委员会、总支部委员会、支部委员会每届任期：","options":["三年至五年","一年至三年","五年至十年","两年至四年"],"answer":0,"explanation":"党章规定，党的基层委员会、总支部委员会、支部委员会每届任期三年至五年，具体任期由批准其成立的党组织根据实际情况确定。故选A。","__sub":"党章党规"},{"id":"zz-32888","module":"zhengzhi","prompt":"党章规定，党的各级组织的选举要体现：","options":["上级领导的意图","选举人的意志","少数人的意见","既定的安排"],"answer":1,"explanation":"党章规定，党的各级组织的选举要充分体现选举人的意志，采用无记名投票的方式，保证选举的民主性。故选B。","__sub":"党章党规"},{"id":"zz-32889","module":"zhengzhi","prompt":"党章规定，任何党员和党的组织都不能凌驾于：","options":["司法机关之上","地方政府之上","党的全国代表大会和中央委员会之上","群众组织之上"],"answer":2,"explanation":"党章规定，党的最高领导机关是党的全国代表大会和它所产生的中央委员会，任何党员和党的组织都不能凌驾于其之上。故选C。","__sub":"党章党规"},{"id":"zz-32890","module":"zhengzhi","prompt":"党章规定，党的各级领导干部要密切联系群众，坚持：","options":["从文件中来，到文件中去","从领导中来，到领导中去","从机关中来，到机关中去","从群众中来，到群众中去"],"answer":3,"explanation":"党章总纲规定，党的各级领导干部要坚持从群众中来、到群众中去的工作路线，密切联系群众，全心全意为人民服务。故选D。","__sub":"党章党规"},{"id":"zz-32891","module":"zhengzhi","prompt":"党章规定，党的中央纪律检查委员会委员的名额由谁决定：","options":["全国人民代表大会","中央委员会","国务院","中央军委"],"answer":1,"explanation":"党章规定，中央纪律检查委员会委员的名额由中央委员会决定，地方各级纪委委员的名额由同级党委决定。故选B。","__sub":"党章党规"},{"id":"zz-32892","module":"zhengzhi","prompt":"党章规定，党的各级委员会实行集体领导和个人分工负责相结合的制度，凡属重大问题都要按照什么原则作出决定：","options":["先斩后奏、事后报告","个人决定、集体负责","集体领导、民主集中、个别酝酿、会议决定","多数服从少数"],"answer":2,"explanation":"党章规定，凡属重大问题都要按照集体领导、民主集中、个别酝酿、会议决定的原则，由党的委员会集体讨论作出决定，委员会成员要根据集体决定和分工切实履行自己的职责。故选C。","__sub":"党章党规"},{"id":"zz-32893","module":"zhengzhi","prompt":"党章规定，党的中央和地方各级党委在必要时可以召集：","options":["全体国民大会","代表会议","各界协商会议","国际会议"],"answer":1,"explanation":"党章规定，党的中央和地方各级委员会在必要时召集代表会议，讨论和决定需要及时解决的重大问题，代表会议代表的名额和产生办法由召集代表会议的委员会决定。故选B。","__sub":"党章党规"},{"id":"zz-32894","module":"zhengzhi","prompt":"党章规定，党的各级领导干部必须坚持解放思想、实事求是、与时俱进、：","options":["因循守旧","开拓创新","墨守成规","照搬照抄"],"answer":1,"explanation":"党章第三十四条规定，党的各级领导干部必须坚持解放思想、实事求是、与时俱进、开拓创新，认真调查研究，能够把党的方针政策同本地区本部门的实际相结合。故选B。","__sub":"党章党规"},{"id":"zz-32895","module":"zhengzhi","prompt":"党章规定，党的基层组织要组织党员认真学习的内容是：","options":["外国宪法","西方经济学理论","古代典籍","马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想"],"answer":3,"explanation":"党章规定的党的基层组织基本任务之一是组织党员认真学习马克思列宁主义、毛泽东思想、邓小平理论、“三个代表”重要思想、科学发展观、习近平新时代中国特色社会主义思想，推进“两学一做”学习教育常态化制度化。故选D。","__sub":"党章党规"},{"id":"zz-32896","module":"zhengzhi","prompt":"党章规定，党的各级领导干部要正确行使人民赋予的权力，反对：","options":["勤勉工作、乐于奉献","依法履职、秉公用权","滥用职权、谋求私利","廉洁自律、克己奉公"],"answer":2,"explanation":"党章第三十五条规定，党的各级领导干部要正确行使人民赋予的权力，坚持原则，依法办事，反对滥用职权、谋求私利的不正之风。故选C。","__sub":"党章党规"},{"id":"zz-32897","module":"zhengzhi","prompt":"党章规定，党的中央纪律检查委员会全体会议每年至少召开：","options":["一次","两次","三次","四次"],"answer":0,"explanation":"党章规定，中央纪律检查委员会全体会议每年至少召开一次，研究部署纪检监察工作，履行监督执纪问责职责。故选A。","__sub":"党章党规"},{"id":"zz-32898","module":"zhengzhi","prompt":"党章规定，党的基层组织按照什么原则选举产生书记、副书记：","options":["等额选举的办法","差额选举的办法","上级指定的办法","轮流担任的办法"],"answer":1,"explanation":"党章规定，党的基层委员会和纪律检查委员会书记、副书记的产生，按照党章和有关规定实行差额选举，充分发扬党内民主。故选B。","__sub":"党章党规"},{"id":"zz-32899","module":"zhengzhi","prompt":"党章规定，党的各级领导干部要发扬党的优良传统和作风，做到：","options":["自重、自省、自警、自励","自满、自大、自负、自私","自由、散漫、懒惰、消极","自保、自利、自吹、自擂"],"answer":0,"explanation":"党章第三十五条规定，党的各级领导干部要做到自重、自省、自警、自励，反对形式主义、官僚主义、享乐主义和奢靡之风，永葆共产党人政治本色。故选A。","__sub":"党章党规"},{"id":"zz-32900","module":"zhengzhi","prompt":"党章规定，党的各级组织要严格执行和维护党的纪律，党员违犯党纪的应当：","options":["移交司法机关处理","一律开除党籍","给予批评教育或纪律处分","不作任何处理"],"answer":2,"explanation":"党章规定，党组织对违犯党纪的党员，应当本着惩前毖后、治病救人的精神，给予批评教育或者纪律处分，严重违犯党纪的必须开除党籍。故选C。","__sub":"党章党规"},{"id":"zz-32901","module":"zhengzhi","prompt":"党章规定，党的中央委员会每届任期五年，全国代表大会提前或延期举行时，其任期：","options":["相应改变","自动延长一年","自动缩短一年","保持不变"],"answer":0,"explanation":"党章规定，党的中央委员会每届任期五年，全国代表大会如提前或延期举行，它的任期也相应改变，保证领导机关的连续性。故选A。","__sub":"党章党规"},{"id":"zz-32902","module":"zhengzhi","prompt":"党章规定，党的地区委员会和相当于地区委员会的组织是：","options":["中央的派出机构","一级独立的地方党委","省、自治区党委派出的代表机关","人大的常设机构"],"answer":2,"explanation":"党章规定，党的地区委员会和相当于地区委员会的组织，是省、自治区党委在几个县、自治县、市范围内派出的代表机关，它根据省、自治区党委的授权领导本地区的工作。故选C。","__sub":"党章党规"},{"id":"zz-32903","module":"zhengzhi","prompt":"党章规定，党的基层组织对党员进行教育、管理、监督和服务，提高党员素质的是：","options":["增加党员福利","增强党性，严格党的组织生活","扩大党员数量","提高党员待遇"],"answer":1,"explanation":"党章规定的党的基层组织基本任务包括对党员进行教育、管理、监督和服务，提高党员素质，增强党性，严格党的组织生活，开展批评和自我批评。故选B。","__sub":"党章党规"},{"id":"zz-32904","module":"zhengzhi","prompt":"党章规定，党的各级领导干部应当具备的基本条件之一是：","options":["坚持个人专断、独断专行","坚持和维护党的民主集中制，有民主作风","坚持一言堂、家长制","坚持分散主义、自由主义"],"answer":1,"explanation":"党章第三十四条规定，党的各级领导干部必须坚持和维护党的民主集中制，有民主作风，有全局观念，善于团结同志，包括团结同自己有不同意见的同志一道工作。故选B。","__sub":"党章党规"},{"id":"zz-32905","module":"zhengzhi","prompt":"党章规定，党的中央和地方各级委员会候补委员的权利是：","options":["有否决权","有表决权、选举权","有被选举权","出席委员会全体会议，有发言权"],"answer":3,"explanation":"党章规定，党的中央和地方各级委员会候补委员出席委员会全体会议，有发言权，但没有表决权、选举权和被选举权，这与正式委员的权利相区别。故选D。","__sub":"党章党规"},{"id":"zz-32906","module":"zhengzhi","prompt":"党章规定，党的各级纪律检查委员会发现同级党的委员会委员有违犯党的纪律的行为，可以先进行：","options":["初步核实","直接逮捕","公开审判","行政拘留"],"answer":0,"explanation":"党章规定，各级纪律检查委员会发现同级党的委员会委员有违犯党的纪律的行为，可以先进行初步核实，如果需要立案检查的，应当在向同级党委报告的同时向上一级纪律检查委员会报告。故选A。","__sub":"党章党规"},{"id":"zz-32907","module":"zhengzhi","prompt":"党章规定，党的各级组织和党员要维护国家的：","options":["割据和分立","分裂和对抗","封闭和孤立","统一和民族团结"],"answer":3,"explanation":"党章总纲规定，中国共产党维护和发展平等团结互助和谐的社会主义民族关系，坚决维护国家统一和民族团结，反对一切分裂国家的活动。故选D。","__sub":"党章党规"},{"id":"zz-32908","module":"zhengzhi","prompt":"党章规定，党的各级领导干部必须具备的基本条件之一是：","options":["有广泛的海外联系","有雄厚的个人资产","有显赫的社会地位","有强烈的革命事业心和政治责任感"],"answer":3,"explanation":"党章第三十四条规定，党的各级领导干部必须有强烈的革命事业心和政治责任感，有实践经验，有胜任领导工作的组织能力、文化水平和专业知识。故选D。","__sub":"党章党规"},{"id":"zz-32909","module":"zhengzhi","prompt":"党章规定，党的各级组织和全体党员要自觉同一切违反党的原则的行为作斗争，维护党的：","options":["对立和分裂","分散和独立","松散和自由","团结和统一"],"answer":3,"explanation":"党章总纲和条文都强调，党的各级组织和全体党员要坚决维护党的团结和统一，这是党的力量所在，是党的事业胜利的保证。故选D。","__sub":"党章党规"},{"id":"zz-32910","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》的制定依据是：","options":["《中国共产党章程》","《中华人民共和国宪法》","《中华人民共和国刑法》","《中国共产党党内监督条例》"],"answer":0,"explanation":"《中国共产党纪律处分条例》第一条明确，根据《中国共产党章程》制定本条例，党章是纪律处分条例的根本依据。故选A。","__sub":"党章党规"},{"id":"zz-32911","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》的适用范围是：","options":["违犯党纪应当受到党纪责任追究的党组织和党员","全体公民","国家公务员","民主党派成员"],"answer":0,"explanation":"《中国共产党纪律处分条例》规定，本条例适用于违犯党纪应当受到党纪责任追究的党组织和党员，体现党纪严于国法的要求。故选A。","__sub":"党章党规"},{"id":"zz-32912","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定的纪律处分工作应当坚持的原则是：","options":["从严从重、一票否决","坚持党要管党、全面从严治党，惩前毖后、治病救人","下不为例、既往不咎","宽严相济、法外开恩"],"answer":1,"explanation":"《中国共产党纪律处分条例》规定，党的纪律处分工作应当坚持党要管党、全面从严治党，惩前毖后、治病救人，党员在纪律面前一律平等。故选B。","__sub":"党章党规"},{"id":"zz-32913","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，党员受到警告处分的影响期是一年内不得：","options":["领取工资待遇","调离原工作岗位","参加组织生活","在党内提升职务和向党外组织推荐担任高于其原任职务的党外职务"],"answer":3,"explanation":"《中国共产党纪律处分条例》规定，党员受到警告处分一年内、受到严重警告处分一年半内，不得在党内提升职务和向党外组织推荐担任高于其原任职务的党外职务。故选D。","__sub":"党章党规"},{"id":"zz-32914","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，党员受到严重警告处分的影响期是：","options":["一年","一年半","两年","三年"],"answer":1,"explanation":"《中国共产党纪律处分条例》规定，党员受到严重警告处分一年半内，不得在党内提升职务和向党外组织推荐担任高于其原任职务的党外职务。故选B。","__sub":"党章党规"},{"id":"zz-32915","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，党员受到撤销党内职务处分的影响期是：","options":["一年","二年","一年半","三年"],"answer":1,"explanation":"《中国共产党纪律处分条例》规定，党员受到撤销党内职务处分二年内，不得在党内担任和向党外组织推荐担任与其原任职务相当或者高于其原任职务的职务。故选B。","__sub":"党章党规"},{"id":"zz-32916","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，从轻或者减轻处分的情形之一是：","options":["包庇同案人员","拒不承认违纪事实","串供或者伪造证据","主动交代本人应当受到党纪处分的问题"],"answer":3,"explanation":"《中国共产党纪律处分条例》规定，主动交代本人应当受到党纪处分的问题的，可以从轻或者减轻处分，体现惩前毖后、治病救人的原则。故选D。","__sub":"党章党规"},{"id":"zz-32917","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，从重或者加重处分的情形之一是：","options":["积极配合组织调查","主动交代违纪问题","主动上交违纪所得","强迫、唆使他人违纪"],"answer":3,"explanation":"《中国共产党纪律处分条例》规定，强迫、唆使他人违纪的，应当从重或者加重处分，体现对主观恶性大的违纪行为的从严惩处。故选D。","__sub":"党章党规"},{"id":"zz-32918","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，违纪行为有关责任人员区分为：","options":["全部责任、部分责任、无责任","首要责任者、次要责任者、连带责任者","直接责任者、主要领导责任者、重要领导责任者","领导责任、个人责任、集体责任"],"answer":2,"explanation":"《中国共产党纪律处分条例》规定，违纪行为有关责任人员的区分包括直接责任者、主要领导责任者、重要领导责任者，据此确定责任大小和处分轻重。故选C。","__sub":"党章党规"},{"id":"zz-32919","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，公开发表坚持资产阶级自由化立场、反对四项基本原则文章的，给予：","options":["严重警告处分","警告处分","开除党籍处分","留党察看处分"],"answer":2,"explanation":"《中国共产党纪律处分条例》规定，公开发表坚持资产阶级自由化立场、反对四项基本原则，反对党的改革开放决策的文章、演说、宣言、声明等的，给予开除党籍处分。故选C。","__sub":"党章党规"},{"id":"zz-32920","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，违反民主集中制原则，拒不执行或者擅自改变党组织作出的重大决定的行为属于：","options":["违反组织纪律","违反政治纪律","违反廉洁纪律","违反生活纪律"],"answer":0,"explanation":"《中国共产党纪律处分条例》将违反民主集中制原则、拒不执行或者擅自改变党组织作出的重大决定等行为列为违反组织纪律的行为。故选A。","__sub":"党章党规"},{"id":"zz-32921","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，收受可能影响公正执行公务的礼品、礼金、消费卡等行为属于：","options":["违反政治纪律","违反廉洁纪律","违反组织纪律","违反生活纪律"],"answer":1,"explanation":"《中国共产党纪律处分条例》规定，收受可能影响公正执行公务的礼品、礼金、消费卡等的，属于违反廉洁纪律的行为，情节较重的给予警告或者严重警告处分。故选B。","__sub":"党章党规"},{"id":"zz-32922","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，侵害群众知情权、参与权、表达权、监督权等行为属于：","options":["违反群众纪律","违反政治纪律","违反组织纪律","违反工作纪律"],"answer":0,"explanation":"《中国共产党纪律处分条例》将侵害群众知情权、参与权、表达权、监督权，对涉及群众切身利益的问题依照政策能解决而不及时解决等行为列为违反群众纪律。故选A。","__sub":"党章党规"},{"id":"zz-32923","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，党组织不履行全面从严治党主体责任或者履行不力的行为属于：","options":["违反组织纪律","违反政治纪律","违反工作纪律","违反群众纪律"],"answer":2,"explanation":"《中国共产党纪律处分条例》将党组织不履行全面从严治党主体责任或者履行全面从严治党主体责任不力等行为列为违反工作纪律的行为。故选C。","__sub":"党章党规"},{"id":"zz-32924","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，生活奢靡、贪图享乐、追求低级趣味等行为属于：","options":["违反生活纪律","违反政治纪律","违反组织纪律","违反廉洁纪律"],"answer":0,"explanation":"《中国共产党纪律处分条例》将生活奢靡、贪图享乐、追求低级趣味，造成不良影响的行为列为违反生活纪律的行为。故选A。","__sub":"党章党规"},{"id":"zz-32925","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，一人有两种以上（含两种）应当受到党纪处分的违纪行为，应当：","options":["合并处理，按其数种违纪行为中应当受到的最高处分加重一档给予处分","只按最重的一种处分","只按最轻的一种处分","分别处分后合并执行"],"answer":0,"explanation":"《中国共产党纪律处分条例》规定，一人有两种以上（含两种）应当受到党纪处分的违纪行为，应当合并处理，按其数种违纪行为中应当受到的最高处分加重一档给予处分。故选A。","__sub":"党章党规"},{"id":"zz-32926","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，违纪后下落不明的党员，对有严重违纪行为、应当给予开除党籍处分的，党组织应当：","options":["暂不处理","作出开除党籍处分决定","留党察看","劝其退党"],"answer":1,"explanation":"《中国共产党纪律处分条例》规定，违纪后下落不明的党员，对有严重违纪行为、应当给予开除党籍处分的，党组织应当作出决定，予以开除党籍。故选B。","__sub":"党章党规"},{"id":"zz-32927","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，二人以上（含二人）共同故意违纪的，对为首者：","options":["免予处分","从轻处分","从重处分","不予处分"],"answer":2,"explanation":"《中国共产党纪律处分条例》规定，二人以上（含二人）共同故意违纪的，对为首者从重处分，对其他成员按照其在共同违纪中所起的作用和应负的责任分别给予处分。故选C。","__sub":"党章党规"},{"id":"zz-32928","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，党员受到党纪追究，涉嫌违法犯罪的：","options":["交由群众评议处理","只作党纪处分不再移送","由党组织代为处理","移送有关国家机关依法处理"],"answer":3,"explanation":"《中国共产党纪律处分条例》规定，党员受到党纪追究，涉嫌违法犯罪的，应当及时移送有关国家机关依法处理，体现纪法衔接。故选D。","__sub":"党章党规"},{"id":"zz-32929","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，在党的十八大后不收敛、不收手的，应当：","options":["不予处分","从轻或者减轻处分","免予处分","从重或者加重处分"],"answer":3,"explanation":"《中国共产党纪律处分条例》规定，在党的十八大后不收敛、不收手的，应当从重或者加重处分，体现对顶风违纪行为的从严惩处。故选D。","__sub":"党章党规"},{"id":"zz-32930","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，主动上交违纪所得的可以：","options":["一律免予处分","从重或者加重处分","从轻或者减轻处分","不予记录"],"answer":2,"explanation":"《中国共产党纪律处分条例》规定，主动上交违纪所得的，可以从轻或者减轻处分，鼓励违纪人员主动纠错。故选C。","__sub":"党章党规"},{"id":"zz-32931","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，凡是有正式党员几人以上的基层单位，应当成立党支部：","options":["五人","三人","七人","十人"],"answer":1,"explanation":"《中国共产党支部工作条例（试行）》规定，凡是有正式党员三人以上的基层单位，应当成立党支部，这是党支部设立的基本条件。故选B。","__sub":"党章党规"},{"id":"zz-32932","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，党支部党员人数一般不超过：","options":["三十人","五十人","一百人","二百人"],"answer":1,"explanation":"《中国共产党支部工作条例（试行）》规定，党支部党员人数一般不超过五十人，规模过大的可以设立党总支部或者划分若干党小组。故选B。","__sub":"党章党规"},{"id":"zz-32933","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，党支部委员会人数一般为：","options":["三至五人，最多不超过七人","五至九人，最多不超过十一人","一至三人，最多不超过五人","七至九人，最多不超过十五人"],"answer":0,"explanation":"《中国共产党支部工作条例（试行）》规定，党支部委员会人数一般为三至五人，最多不超过七人，由党员大会选举产生。故选A。","__sub":"党章党规"},{"id":"zz-32934","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，村、社区党支部委员会每届任期为：","options":["六年","三年","四年","五年"],"answer":3,"explanation":"《中国共产党支部工作条例（试行）》规定，村、社区党支部委员会每届任期五年，其他基层单位党支部委员会一般每届任期三年，与党章和有关法规相衔接。故选D。","__sub":"党章党规"},{"id":"zz-32935","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，党支部书记、副书记、委员由谁选举产生：","options":["上级党委任命","支部党员大会","支部委员会推选","党小组会决定"],"answer":1,"explanation":"《中国共产党支部工作条例（试行）》规定，党支部书记、副书记、委员由支部党员大会选举产生，保证支部领导机构体现党员意志。故选B。","__sub":"党章党规"},{"id":"zz-32936","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，党支部担负的职责是：","options":["制定法律法规、监督司法审判","领导行政工作、管理社会事务、审批财政预算","直接教育党员、管理党员、监督党员，组织群众、宣传群众、凝聚群众、服务群众","经营国有资产、管理企业事务"],"answer":2,"explanation":"《中国共产党支部工作条例（试行）》规定，党支部担负直接教育党员、管理党员、监督党员和组织群众、宣传群众、凝聚群众、服务群众的职责。故选C。","__sub":"党章党规"},{"id":"zz-32937","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，党支部党员大会一般每季度召开：","options":["每月一次","一次","每半年一次","每年一次"],"answer":1,"explanation":"《中国共产党支部工作条例（试行）》规定，党支部党员大会一般每季度召开一次，是党支部的最高领导机构。故选B。","__sub":"党章党规"},{"id":"zz-32938","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，党支部委员会会议一般每月召开：","options":["一次","每季度一次","每半年一次","每年一次"],"answer":0,"explanation":"《中国共产党支部工作条例（试行）》规定，党支部委员会会议一般每月召开一次，根据需要可以随时召开，研究决定支部重要事项。故选A。","__sub":"党章党规"},{"id":"zz-32939","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，党课一般每季度至少开展：","options":["每半年一次","每月一次","一次","两年一次"],"answer":2,"explanation":"《中国共产党支部工作条例（试行）》规定，党课一般每季度至少开展一次，突出政治学习和教育，突出党性锻炼。故选C。","__sub":"党章党规"},{"id":"zz-32940","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，党支部组织生活会一般每年召开：","options":["每两年一次","每月一次","每季度一次","一次"],"answer":3,"explanation":"《中国共产党支部工作条例（试行）》规定，党支部组织生活会一般每年召开一次，组织党员开展批评和自我批评。故选D。","__sub":"党章党规"},{"id":"zz-32941","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，党支部委员会成员之间、党支部委员会成员和党员之间每年至少谈心谈话：","options":["每两年一次","每月一次","每季度一次","一次"],"answer":3,"explanation":"《中国共产党支部工作条例（试行）》规定，党支部委员会成员之间、党支部委员会成员和党员之间每年至少谈心谈话一次，及时掌握党员思想动态。故选D。","__sub":"党章党规"},{"id":"zz-32942","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，民主评议党员一般每年开展：","options":["每季度一次","每月一次","一次","每三年一次"],"answer":2,"explanation":"《中国共产党支部工作条例（试行）》规定，民主评议党员一般每年开展一次，按照个人自评、党员互评、民主测评的程序进行。故选C。","__sub":"党章党规"},{"id":"zz-32943","module":"zhengzhi","prompt":"《中国共产党党员教育管理工作条例》规定的党员教育管理目标是建设：","options":["规模庞大、结构复杂、层级分明、分工细致、运转高效的党员队伍","信念坚定、政治可靠、素质优良、纪律严明、作用突出的党员队伍","年轻化、知识化、专业化、市场化、国际化的党员队伍","高学历、高职称、高收入、高消费、高福利的党员队伍"],"answer":1,"explanation":"《中国共产党党员教育管理工作条例》规定，党员教育管理的目标是建设信念坚定、政治可靠、素质优良、纪律严明、作用突出的党员队伍。故选B。","__sub":"党章党规"},{"id":"zz-32944","module":"zhengzhi","prompt":"《中国共产党党员教育管理工作条例》规定，党员日常教育管理的主要方式是：","options":["党校","党委","党组","党支部"],"answer":3,"explanation":"《中国共产党党员教育管理工作条例》规定，党支部是党员日常教育管理的主要方式，要依托党支部开展经常性的教育管理工作。故选D。","__sub":"党章党规"},{"id":"zz-32945","module":"zhengzhi","prompt":"《中国共产党党员教育管理工作条例》规定，党员每年集中培训时间一般不少于：","options":["四十八学时","十六学时","三十二学时","六十四学时"],"answer":2,"explanation":"《中国共产党党员教育管理工作条例》规定，党员每年集中培训时间一般不少于三十二学时，其中新党员培训不少于二十四学时。故选C。","__sub":"党章党规"},{"id":"zz-32946","module":"zhengzhi","prompt":"《中国共产党党员教育管理工作条例》规定，党员外出地点相对固定、时间六个月以上的，一般应当：","options":["注销党员身份","保留组织关系原地不动","转移党员组织关系","重新申请入党"],"answer":2,"explanation":"《中国共产党党员教育管理工作条例》规定，党员外出地点相对固定、时间六个月以上的，一般应当转移党员组织关系，纳入流入地党组织管理。故选C。","__sub":"党章党规"},{"id":"zz-32947","module":"zhengzhi","prompt":"《中国共产党党员教育管理工作条例》规定，党员教育的基本任务之一是：","options":["开展商业技能培训","加强政治理论教育","组织休闲娱乐活动","进行经济利益激励"],"answer":1,"explanation":"《中国共产党党员教育管理工作条例》规定，党员教育的基本任务包括加强政治理论教育、突出政治教育和政治训练、强化党章党规党纪教育、加强党的宗旨教育等。故选B。","__sub":"党章党规"},{"id":"zz-32948","module":"zhengzhi","prompt":"《中国共产党问责条例》规定的问责对象是：","options":["民主党派成员","全体公民","国家公务员","党组织和党的领导干部"],"answer":3,"explanation":"《中国共产党问责条例》规定，问责对象是党组织和党的领导干部，重点是党委（党组）、纪委（纪检组）及其领导成员。故选D。","__sub":"党章党规"},{"id":"zz-32949","module":"zhengzhi","prompt":"《中国共产党问责条例》规定的对党组织的问责方式是：","options":["警告、严重警告、撤销党内职务","检查、通报、改组","诫勉、降职、撤职","罚款、通报批评、停职"],"answer":1,"explanation":"《中国共产党问责条例》规定，对党组织的问责方式包括检查、通报、改组三种，根据情节轻重依次递进。故选B。","__sub":"党章党规"},{"id":"zz-32950","module":"zhengzhi","prompt":"《中国共产党问责条例》规定的对党的领导干部的问责方式是：","options":["警告、记过、降级、撤职","通报、诫勉、组织调整或者组织处理、纪律处分","罚款、拘留、判刑","批评、检讨、道歉、辞职"],"answer":1,"explanation":"《中国共产党问责条例》规定，对党的领导干部的问责方式包括通报、诫勉、组织调整或者组织处理、纪律处分四种，可以单独使用也可以合并使用。故选B。","__sub":"党章党规"},{"id":"zz-32951","module":"zhengzhi","prompt":"《中国共产党问责条例》规定的问责原则是：","options":["依规依纪、实事求是，失责必问、问责必严","下不为例、既往不咎","法不责众、网开一面","重结果轻程序"],"answer":0,"explanation":"《中国共产党问责条例》规定，问责工作应当坚持依规依纪、实事求是，失责必问、问责必严，把问责的板子打准打实。故选A。","__sub":"党章党规"},{"id":"zz-32952","module":"zhengzhi","prompt":"《中国共产党问责条例》规定，问责决定应当由谁作出：","options":["有管理权限的党组织","纪检监察机关单独决定","司法机关决定","群众组织决定"],"answer":0,"explanation":"《中国共产党问责条例》规定，问责决定应当由有管理权限的党组织作出，其中对党的领导干部的问责，按照管理权限由相应党组织作出。故选A。","__sub":"党章党规"},{"id":"zz-32953","module":"zhengzhi","prompt":"《中国共产党问责条例》最新一次修订的时间是：","options":["2016年","2019年","2018年","2021年"],"answer":1,"explanation":"《中国共产党问责条例》于2016年制定，2019年进行修订，进一步完善了问责的原则、程序和方式。故选B。","__sub":"党章党规"},{"id":"zz-32954","module":"zhengzhi","prompt":"《中国共产党廉洁自律准则》规定的党员廉洁自律规范之一是：","options":["坚持公私不分，先己后人","坚持公私分明，先公后私，克己奉公","坚持损公肥私，假公济私","坚持公私兼顾，以私为先"],"answer":1,"explanation":"《中国共产党廉洁自律准则》规定，党员廉洁自律规范包括坚持公私分明，先公后私，克己奉公；坚持崇廉拒腐，清白做人，干净做事等。故选B。","__sub":"党章党规"},{"id":"zz-32955","module":"zhengzhi","prompt":"《中国共产党廉洁自律准则》规定的党员领导干部廉洁自律规范之一是：","options":["廉洁结盟，自觉编织关系网络","廉洁谋私，自觉扩大个人利益","廉洁享乐，自觉提高消费水平","廉洁从政，自觉保持人民公仆本色"],"answer":3,"explanation":"《中国共产党廉洁自律准则》规定，党员领导干部廉洁自律规范包括廉洁从政，自觉保持人民公仆本色；廉洁用权，自觉维护人民根本利益等。故选D。","__sub":"党章党规"},{"id":"zz-32956","module":"zhengzhi","prompt":"《中国共产党廉洁自律准则》的适用对象是：","options":["民主党派成员","全体公民","国家公务员","全体党员和党员领导干部"],"answer":3,"explanation":"《中国共产党廉洁自律准则》适用于全体党员和党员领导干部，其中对党员领导干部提出了更高要求，体现自律规范的层次性。故选D。","__sub":"党章党规"},{"id":"zz-32957","module":"zhengzhi","prompt":"《中国共产党廉洁自律准则》规定的党员领导干部廉洁自律规范中，涉及家风建设的是：","options":["廉洁投资，自觉增加个人收入","廉洁交友，自觉扩大朋友圈","廉洁消费，自觉提高生活品质","廉洁齐家，自觉带头树立良好家风"],"answer":3,"explanation":"《中国共产党廉洁自律准则》规定，党员领导干部要廉洁齐家，自觉带头树立良好家风，把家风建设作为领导干部作风建设的重要内容。故选D。","__sub":"党章党规"},{"id":"zz-32958","module":"zhengzhi","prompt":"《中国共产党党内监督条例》规定的党内监督体系包括党委（党组）全面监督、纪律检查机关专责监督、党的工作部门职能监督、党的基层组织日常监督和：","options":["媒体舆论监督","群众信访监督","党员民主监督","社会公众监督"],"answer":2,"explanation":"《中国共产党党内监督条例》规定，建立健全党委（党组）全面监督、纪律检查机关专责监督、党的工作部门职能监督、党的基层组织日常监督、党员民主监督的党内监督体系。故选C。","__sub":"党章党规"},{"id":"zz-32959","module":"zhengzhi","prompt":"《中国共产党党内监督条例》规定的党内监督重点对象是：","options":["普通党员","党的领导机关和领导干部特别是主要领导干部","基层干部","退休人员"],"answer":1,"explanation":"《中国共产党党内监督条例》规定，党内监督的重点对象是党的领导机关和领导干部特别是主要领导干部，体现对关键少数的从严要求。故选B。","__sub":"党章党规"},{"id":"zz-32960","module":"zhengzhi","prompt":"《中国共产党党内监督条例》强调，党内监督：","options":["只针对基层干部","没有禁区、没有例外","只针对普通党员","只针对退休干部"],"answer":1,"explanation":"《中国共产党党内监督条例》强调，党内监督没有禁区、没有例外，信任不能代替监督，各级党组织和领导干部必须接受监督。故选B。","__sub":"党章党规"},{"id":"zz-32961","module":"zhengzhi","prompt":"《中国共产党党内监督条例》规定，纪律检查机关在党内监督体系中的定位是：","options":["全面监督","专责监督","职能监督","日常监督"],"answer":1,"explanation":"《中国共产党党内监督条例》规定，纪律检查机关在党内监督体系中承担专责监督职责，是党内监督的专门力量。故选B。","__sub":"党章党规"},{"id":"zz-32962","module":"zhengzhi","prompt":"《中国共产党巡视工作条例》强调，巡视是党内监督的：","options":["战略性制度安排","临时性工作措施","辅助性工作方法","阶段性工作任务"],"answer":0,"explanation":"《中国共产党巡视工作条例》和中央有关文件强调，巡视是党内监督的战略性制度安排，是发现问题的尖兵、纪律审查的前哨。故选A。","__sub":"党章党规"},{"id":"zz-32963","module":"zhengzhi","prompt":"《中国共产党巡视工作条例》规定的巡视监督要实现：","options":["选择性覆盖","重点覆盖","局部覆盖","全覆盖"],"answer":3,"explanation":"《中国共产党巡视工作条例》规定，巡视监督要实现党的中央和省、自治区、直辖市委员会一届任期内对所管理的地方、部门、企事业单位党组织全覆盖。故选D。","__sub":"党章党规"},{"id":"zz-32964","module":"zhengzhi","prompt":"《党政领导干部选拔任用工作条例》规定的选拔任用干部的基本程序包括动议、民主推荐、考察、讨论决定和：","options":["试用期即结束","公示即结束","任职","培训即结束"],"answer":2,"explanation":"《党政领导干部选拔任用工作条例》规定，选拔任用党政领导干部必须经过动议、民主推荐、考察、讨论决定、任职等程序，不得简化程序。故选C。","__sub":"党章党规"},{"id":"zz-32965","module":"zhengzhi","prompt":"《中国共产党发展党员工作细则》规定，发展党员必须坚持的原则是：","options":["入党自愿原则和个别吸收原则","批量发展原则","指标分配原则","轮流入党原则"],"answer":0,"explanation":"《中国共产党发展党员工作细则》规定，发展党员必须坚持入党自愿原则和个别吸收原则，成熟一个、发展一个，禁止突击发展。故选A。","__sub":"党章党规"},{"id":"zz-32966","module":"zhengzhi","prompt":"《中国共产党党员权利保障条例》规定的党员权利共有：","options":["十六项","八项","十项","十三项"],"answer":3,"explanation":"《中国共产党党员权利保障条例》（2020年修订）在党章规定的党员八项权利基础上细化为十三项权利，包括党内知情权、接受党的教育培训权等。故选D。","__sub":"党章党规"},{"id":"zz-32967","module":"zhengzhi","prompt":"《中国共产党党员权利保障条例》规定的党员权利之一是：","options":["党内特权","党内否决权","党内豁免权","党内知情权"],"answer":3,"explanation":"《中国共产党党员权利保障条例》规定的党员权利包括党内知情权、接受党的教育培训权、党内参加讨论权、党内建议和倡议权等十三项。故选D。","__sub":"党章党规"},{"id":"zz-32968","module":"zhengzhi","prompt":"《中国共产党农村基层组织工作条例》规定，村党组织每届任期为：","options":["四年","三年","五年","六年"],"answer":2,"explanation":"《中国共产党农村基层组织工作条例》规定，村党组织每届任期五年，与村“两委”换届相衔接，保证农村基层组织的稳定性。故选C。","__sub":"党章党规"},{"id":"zz-32969","module":"zhengzhi","prompt":"《中国共产党党内法规制定条例》规定的党内法规的名称包括：","options":["党章、准则、条例、规定、办法、细则","法律、法规、规章、制度、通知、意见","宪法、法律、行政法规、地方性法规","决议、决定、命令、公报、公告"],"answer":0,"explanation":"《中国共产党党内法规制定条例》规定，党内法规的名称为党章、准则、条例、规定、办法、细则，各类名称有相应的适用范围。故选A。","__sub":"党章党规"},{"id":"zz-32970","module":"zhengzhi","prompt":"党内法规体系中具有最高效力的是：","options":["条例","准则","党章","规定"],"answer":2,"explanation":"《中国共产党党内法规制定条例》规定，党章在党内法规中具有最高效力，其他任何党内法规都不得同党章相抵触。故选C。","__sub":"党章党规"},{"id":"zz-32971","module":"zhengzhi","prompt":"《中国共产党重大事项请示报告条例》要求，请示报告应当坚持的原则是：","options":["大事小事都请示","该请示的请示、该报告的报告","只报喜不报忧","先斩后奏"],"answer":1,"explanation":"《中国共产党重大事项请示报告条例》规定，请示报告应当坚持该请示的请示、该报告的报告，既讲规矩又讲效率，防止层层请示、事事报告。故选B。","__sub":"党章党规"},{"id":"zz-32972","module":"zhengzhi","prompt":"《中国共产党宣传工作条例》规定的宣传工作的根本任务是：","options":["增加广告收入","扩大媒体经营规模","高举中国特色社会主义伟大旗帜，巩固马克思主义在意识形态领域的指导地位","提高收视率"],"answer":2,"explanation":"《中国共产党宣传工作条例》规定，宣传工作的根本任务是高举中国特色社会主义伟大旗帜，巩固马克思主义在意识形态领域的指导地位，巩固全党全国人民团结奋斗的共同思想基础。故选C。","__sub":"党章党规"},{"id":"zz-32973","module":"zhengzhi","prompt":"《中国共产党统一战线工作条例》规定，统一战线工作应当发挥的作用是：","options":["管理宗教事务的行政力量","分配资源、划分利益的渠道","凝聚人心、汇聚力量的政治优势","审批社团活动的职能部门"],"answer":2,"explanation":"《中国共产党统一战线工作条例》第二条规定，统一战线是中国共产党凝聚人心、汇聚力量的政治优势和战略方针。统一战线是党的事业取得胜利的重要法宝，不是行政管理部门，也不承担资源分配与社团审批职能。故选C。","__sub":"党章党规"},{"id":"zz-32974","module":"zhengzhi","prompt":"《中国共产党国有企业基层组织工作条例（试行）》规定，国有企业党组织的领导作用是：","options":["管经营、抓生产、创利润","把方向、管大局、保落实","只管党务不管业务","只管监督不管决策"],"answer":1,"explanation":"《中国共产党国有企业基层组织工作条例（试行）》规定，国有企业党组织发挥把方向、管大局、保落实的领导作用，依照规定讨论和决定企业重大事项。故选B。","__sub":"党章党规"},{"id":"zz-32975","module":"zhengzhi","prompt":"《中国共产党纪律检查机关监督执纪工作规则》强调，审查调查工作的安全要求是：","options":["提高办案速度","追求办案数量","确保审查调查安全","扩大办案范围"],"answer":2,"explanation":"《中国共产党纪律检查机关监督执纪工作规则》强调，要确保审查调查安全，严格落实安全责任，防范安全事故发生。故选C。","__sub":"党章党规"},{"id":"zz-32976","module":"zhengzhi","prompt":"《中国共产党纪律检查机关监督执纪工作规则》规定的监督执纪工作的领导体制是：","options":["同级人大领导","同级政府领导","同级党委和上级纪委领导","司法机关领导"],"answer":2,"explanation":"《中国共产党纪律检查机关监督执纪工作规则》规定，监督执纪工作坚持同级党委和上级纪委领导，重要事项及时向同级党委和上级纪委报告。故选C。","__sub":"党章党规"},{"id":"zz-32977","module":"zhengzhi","prompt":"《中国共产党组织处理规定（试行）》规定的组织处理方式包括：","options":["警告、记过、降级、撤职、开除","停职检查、调整职务、责令辞职、免职、降职","罚款、拘留、判刑","通报、诫勉、约谈、警告"],"answer":1,"explanation":"《中国共产党组织处理规定（试行）》规定的组织处理方式包括停职检查、调整职务、责令辞职、免职、降职等，是对不适宜担任现职干部的组织措施。故选B。","__sub":"党章党规"},{"id":"zz-32978","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，对严重违犯党纪的党组织的纪律处理措施是：","options":["合并、撤销","警告、通报","罚款、停业","改组、解散"],"answer":3,"explanation":"《中国共产党纪律处分条例》规定，对严重违犯党纪、本身又不能纠正的党组织，应当予以改组或者解散，与对党员的五种处分相区别。故选D。","__sub":"党章党规"},{"id":"zz-32979","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，故意违纪受处分后又因故意违纪应当受到党纪处分的，应当：","options":["合并处理不加档","从轻处分","免予处分","从重处分"],"answer":3,"explanation":"《中国共产党纪律处分条例》规定，故意违纪受处分后又因故意违纪应当受到党纪处分的，应当从重处分，体现对屡犯者的从严要求。故选D。","__sub":"党章党规"},{"id":"zz-32980","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，党员犯罪情节轻微，人民检察院依法作出不起诉决定的，或者人民法院依法作出有罪判决并免予刑事处罚的，应当给予：","options":["撤销党内职务、留党察看或者开除党籍处分","警告或者严重警告处分","不作处分","批评教育"],"answer":0,"explanation":"《中国共产党纪律处分条例》规定，党员犯罪情节轻微，人民检察院依法作出不起诉决定的，或者人民法院依法作出有罪判决并免予刑事处罚的，应当给予撤销党内职务、留党察看或者开除党籍处分。故选A。","__sub":"党章党规"},{"id":"zz-32981","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，因故意犯罪被依法判处刑法规定的主刑（含宣告缓刑）的党员，应当给予：","options":["严重警告处分","留党察看处分","撤销党内职务处分","开除党籍处分"],"answer":3,"explanation":"《中国共产党纪律处分条例》规定，因故意犯罪被依法判处刑法规定的主刑（含宣告缓刑）的，应当给予开除党籍处分，体现纪法衔接的刚性要求。故选D。","__sub":"党章党规"},{"id":"zz-32982","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定的党纪处分运用规则中，减轻处分是指：","options":["在本条例规定的违纪行为应当受到的处分幅度以外，减轻一档给予处分","在处分幅度以内给予较轻处分","免除一切处分","降为预备党员"],"answer":0,"explanation":"《中国共产党纪律处分条例》规定，减轻处分是指在本条例规定的违纪行为应当受到的处分幅度以外，减轻一档给予处分，从轻处分则在幅度以内给予较轻处分。故选A。","__sub":"党章党规"},{"id":"zz-32983","module":"zhengzhi","prompt":"《中国共产党纪律处分条例》规定，违纪党员在纪律审查期间主动交代问题并如实说明情况的，可以：","options":["从轻或者减轻处分","从重或者加重处分","维持原拟处分","移交司法机关"],"answer":0,"explanation":"《中国共产党纪律处分条例》规定，违纪党员在纪律审查期间主动交代问题并如实说明情况的，可以从轻或者减轻处分，体现宽严相济。故选A。","__sub":"党章党规"},{"id":"zz-32984","module":"zhengzhi","prompt":"《中国共产党支部工作条例（试行）》规定，党支部每月相对固定一天开展的活动是：","options":["主题党日","民主生活会","述责述廉会","巡视工作会"],"answer":0,"explanation":"《中国共产党支部工作条例（试行）》规定，党支部每月相对固定一天开展主题党日，组织党员集中学习、过组织生活、进行民主议事和志愿服务等。故选A。","__sub":"党章党规"},{"id":"zz-32985","module":"zhengzhi","prompt":"《中国共产党党员教育管理工作条例》规定，党员教育管理坚持的原则之一是：","options":["坚持重形式轻实效","坚持放任自流、宽松软散","坚持重业务轻党建","坚持党要管党、全面从严治党"],"answer":3,"explanation":"《中国共产党党员教育管理工作条例》规定，党员教育管理坚持党要管党、全面从严治党，把党员教育管理作为党的建设的基础性经常性工作。故选D。","__sub":"党章党规"},{"id":"zz-32986","module":"zhengzhi","prompt":"《关于新形势下党内政治生活的若干准则》是在哪次会议上审议通过的？","options":["党的十八届三中全会","党的十八届六中全会","党的十九大","党的十九届四中全会"],"answer":1,"explanation":"2016年10月党的十八届六中全会审议通过《关于新形势下党内政治生活的若干准则》，对新形势下加强和规范党内政治生活作出全面部署。故选B。","__sub":"党章党规"},{"id":"zz-32987","module":"zhengzhi","prompt":"《关于新形势下党内政治生活的若干准则》强调，加强和规范党内政治生活，重点是：","options":["各级领导机关和领导干部","基层党支部书记","普通党员","纪检干部"],"answer":0,"explanation":"《关于新形势下党内政治生活的若干准则》明确，加强和规范党内政治生活，重点是各级领导机关和领导干部，关键是高级干部特别是中央委员会、中央政治局的组成人员。故选A。","__sub":"党章党规"},{"id":"zz-32988","module":"zhengzhi","prompt":"《关于新形势下党内政治生活的若干准则》指出，民主集中制是党内政治生活正常开展的：","options":["根本评价标准","首要前提条件","重要制度保障","最终奋斗目标"],"answer":2,"explanation":"《关于新形势下党内政治生活的若干准则》强调，民主集中制是党内政治生活正常开展的重要制度保障，坚持民主集中制是规范党内政治生活的重要内容。故选C。","__sub":"党章党规"},{"id":"zz-32989","module":"zhengzhi","prompt":"《关于新形势下党内政治生活的若干准则》指出，纪律严明是党内政治生活的：","options":["唯一手段","基本前提","重要保证","外在形式"],"answer":2,"explanation":"《关于新形势下党内政治生活的若干准则》强调，纪律严明是党内政治生活的重要保证，必须严明党的政治纪律和政治规矩，用铁的纪律从严治党。故选C。","__sub":"党章党规"},{"id":"zz-32990","module":"zhengzhi","prompt":"《关于新形势下党内政治生活的若干准则》指出，批评和自我批评是我们党强身治病、保持肌体健康的：","options":["辅助办法","锐利武器","权宜之计","外部约束"],"answer":1,"explanation":"《关于新形势下党内政治生活的若干准则》指出，批评和自我批评是我们党强身治病、保持肌体健康的锐利武器，也是加强和规范党内政治生活的重要手段。故选B。","__sub":"党章党规"},{"id":"zz-32991","module":"zhengzhi","prompt":"《关于新形势下党内政治生活的若干准则》提出着力增强党内政治生活的：","options":["系统性、整体性、协同性、实效性","纪律性、组织性、保密性、先进性","科学性、民主性、法治性、规范性","政治性、时代性、原则性、战斗性"],"answer":3,"explanation":"《关于新形势下党内政治生活的若干准则》提出，要着力增强党内政治生活的政治性、时代性、原则性、战斗性，使党内政治生活真正起到教育改造党员的作用。故选D。","__sub":"党章党规"},{"id":"zz-32992","module":"zhengzhi","prompt":"《关于新形势下党内政治生活的若干准则》强调，坚决维护党中央权威、保证全党令行禁止，是加强和规范党内政治生活的：","options":["附加内容","次要任务","临时要求","重要目的"],"answer":3,"explanation":"《关于新形势下党内政治生活的若干准则》强调，坚决维护党中央权威、保证全党令行禁止，是加强和规范党内政治生活的重要目的，全党必须自觉在思想上政治上行动上同党中央保持高度一致。故选D。","__sub":"党章党规"},{"id":"zz-32993","module":"zhengzhi","prompt":"按照有关规定，县以上党和国家机关党员领导干部民主生活会每年召开：","options":["每半年1次","2次","1次","每季度1次"],"answer":2,"explanation":"按照《县以上党和国家机关党员领导干部民主生活会若干规定》，民主生活会每年召开1次，一般安排在第四季度，因特殊情况需要提前或延期召开的须报上级党组织同意。故选C。","__sub":"党章党规"},{"id":"zz-32994","module":"zhengzhi","prompt":"党支部每年至少召开几次组织生活会？","options":["2次","1次","3次","4次"],"answer":1,"explanation":"按照党内有关规定，党支部每年至少召开1次组织生活会，组织生活会一般以党员大会、党支部委员会会议或者党小组会形式召开，认真开展批评和自我批评。故选B。","__sub":"党章党规"},{"id":"zz-32995","module":"zhengzhi","prompt":"党员领导干部要以普通党员身份参加所在党支部或者党小组的：","options":["述职述廉会议","领导班子民主生活会","组织生活会","干部考察谈话"],"answer":2,"explanation":"按照党内有关规定，党员领导干部应当以普通党员身份参加所在党支部或者党小组的组织生活会，这体现了党的组织生活制度面前党员一律平等的要求。故选C。","__sub":"党章党规"},{"id":"zz-32996","module":"zhengzhi","prompt":"按照党内监督条例规定，党委（党组）负责人应当每年至少同领导班子成员进行几次谈心谈话？","options":["1次","2次","每月1次","每季度1次"],"answer":0,"explanation":"《中国共产党党内监督条例》规定，党委（党组）负责人应当每年至少同领导班子成员进行1次谈心谈话，及时掌握其思想、工作、作风状况，有针对性地做好思想政治工作。故选A。","__sub":"党章党规"},{"id":"zz-32997","module":"zhengzhi","prompt":"《中国共产党党内监督条例》规定，党的纪律检查委员会在党内监督体系中履行：","options":["专责监督职责","全面监督职责","职能监督职责","日常监督职责"],"answer":0,"explanation":"《中国共产党党内监督条例》构建了党委（党组）全面监督、纪律检查机关专责监督、党的工作部门职能监督、党的基层组织日常监督、党员民主监督的监督体系，纪委履行专责监督职责。故选A。","__sub":"党章党规"},{"id":"zz-32998","module":"zhengzhi","prompt":"按照党内监督条例规定，党委（党组）领导班子成员应当定期在哪里开展述责述廉？","options":["中央委员会","党委（党组）","纪律检查委员会","所在党支部"],"answer":1,"explanation":"《中国共产党党内监督条例》规定，党委（党组）领导班子成员应当在党委（党组）会议上定期开展述责述廉，接受班子成员监督，如实报告执行廉洁纪律等情况。故选B。","__sub":"党章党规"},{"id":"zz-32999","module":"zhengzhi","prompt":"《中国共产党党内监督条例》指出，巡视是党内监督的：","options":["外部性评价方式","临时性工作措施","辅助性了解渠道","战略性制度安排"],"answer":3,"explanation":"《中国共产党党内监督条例》指出，巡视是党内监督的战略性制度安排，要推动巡视向纵深发展，实现巡视全覆盖，发挥巡视利剑作用。故选D。","__sub":"党章党规"},{"id":"zz-33000","module":"zhengzhi","prompt":"加强和规范党内政治生活，是党组织教育管理党员和党员进行党性锻炼的：","options":["主要平台","唯一途径","附加任务","外部条件"],"answer":0,"explanation":"《关于新形势下党内政治生活的若干准则》指出，党内政治生活是党组织教育管理党员和党员进行党性锻炼的主要平台，必须把加强思想政治建设摆在首位。故选A。","__sub":"党章党规"}]);